import { GoogleGenAI, Type } from "@google/genai";
import { PerformanceInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getPerformanceInsight = async (
  attendance: number,
  score: number,
  assignments: number
): Promise<PerformanceInsight> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze this HSC Science student's performance: 
      Attendance: ${attendance}%, Exam Score: ${score}%, Assignment Completion: ${assignments}%. 
      Provide a concise 1-sentence academic suggestion.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['Critical', 'Warning', 'Good', 'Excellent'] },
            color: { type: Type.STRING, description: 'CSS color code like red, yellow, green' },
            message: { type: Type.STRING }
          },
          required: ['status', 'color', 'message']
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    // Fallback logic
    if (score < 50 || attendance < 60) {
      return { status: 'Critical', color: 'red', message: 'Urgent attention required in both attendance and core subjects.' };
    }
    return { status: 'Good', color: 'green', message: 'Maintaining steady progress. Keep focusing on revisions.' };
  }
};

import React, { useState, useEffect } from 'react';
import { UserRole, Student } from './types';
import { MOCK_STUDENTS } from './constants';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Courses from './pages/Courses';
import Teachers from './pages/Teachers';
import Admission from './pages/Admission';
import Contact from './pages/Contact';
import Login from './pages/Login';
import StudentDashboard from './pages/StudentDashboard';
import AdminDashboard from './pages/AdminDashboard';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('home');
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [user, setUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const navigate = (page: string) => {
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogin = (selectedRole: UserRole, email: string) => {
    setRole(selectedRole);
    if (selectedRole === UserRole.STUDENT) {
      const found = MOCK_STUDENTS.find(s => s.email === email);
      setUser(found || MOCK_STUDENTS[0]);
      navigate('student-dashboard');
    } else {
      setUser({ name: 'Headmaster Admin' });
      navigate('admin-dashboard');
    }
  };

  const handleLogout = () => {
    setRole(UserRole.GUEST);
    setUser(null);
    navigate('home');
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home': return <Home navigate={navigate} />;
      case 'courses': return <Courses />;
      case 'teachers': return <Teachers />;
      case 'admission': return <Admission />;
      case 'contact': return <Contact />;
      case 'login': return <Login onLogin={handleLogin} />;
      case 'student-dashboard': return <StudentDashboard student={user} onLogout={handleLogout} />;
      case 'admin-dashboard': return <AdminDashboard onLogout={handleLogout} />;
      default: return <Home navigate={navigate} />;
    }
  };

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <Navbar 
        currentPage={currentPage} 
        navigate={navigate} 
        role={role} 
        onLogout={handleLogout}
        darkMode={darkMode}
        toggleDarkMode={() => setDarkMode(!darkMode)}
      />
      <main className="flex-grow pt-16">
        {renderPage()}
      </main>
      <Footer />
    </div>
  );
};

export default App;

