import React, { useState, useEffect } from 'react';
import { Student, PerformanceInsight } from '../types';
import { getPerformanceInsight } from '../services/geminiService';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell } from 'recharts';

interface Props {
  student: Student;
  onLogout: () => void;
}

const StudentDashboard: React.FC<Props> = ({ student, onLogout }) => {
  const [insight, setInsight] = useState<PerformanceInsight | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchInsight = async () => {
      const data = await getPerformanceInsight(student.attendance, student.averageScore, student.assignments);
      setInsight(data);
      setLoading(false);
    };
    fetchInsight();
  }, [student]);

  const statsData = [
    { subject: 'Attendance', value: student.attendance, full: 100 },
    { subject: 'Exam Score', value: student.averageScore, full: 100 },
    { subject: 'Assignments', value: student.assignments, full: 100 },
  ];

  const chartData = [
    { name: 'Physics', score: 85 },
    { name: 'Chem', score: 72 },
    { name: 'Math', score: 90 },
    { name: 'Biology', score: 65 },
    { name: 'ICT', score: 95 },
  ];

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Welcome, {student.name}</h1>
          <p className="text-slate-500">Class: {student.class}</p>
        </div>
        <div className={`px-4 py-2 rounded-lg font-bold ${student.feesPaid ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
          Fee Status: {student.feesPaid ? 'Paid' : 'Due'}
        </div>
      </header>

      {/* Heatmap Section */}
      <section className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl p-8 border border-slate-100 dark:border-slate-700">
        <div className="flex flex-col md:flex-row gap-8 items-center">
          <div className="flex-1 w-full text-center md:text-left space-y-4">
            <h2 className="text-2xl font-bold flex items-center justify-center md:justify-start">
              🔥 Performance Heatmap
            </h2>
            <div className="flex items-center space-x-4 justify-center md:justify-start">
              <div className="w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg" style={{ backgroundColor: insight?.color || '#ccc' }}>
                {loading ? '...' : (insight?.status === 'Excellent' ? '🌟' : '💡')}
              </div>
              <div>
                <p className="text-sm font-bold uppercase text-slate-400">Analysis Status</p>
                <p className="text-xl font-extrabold" style={{ color: insight?.color }}>
                  {loading ? 'Analyzing...' : insight?.status}
                </p>
              </div>
            </div>
            <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl italic text-slate-600 dark:text-slate-400 border-l-4 border-orange-500">
              "{loading ? 'Summoning AI mentor insights...' : insight?.message}"
            </div>
          </div>

          <div className="w-full md:w-1/3 h-[250px]">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={statsData}>
                <PolarGrid stroke="#e2e8f0" />
                <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12 }} />
                <PolarRadiusAxis angle={30} domain={[0, 100]} />
                <Radar name="Student" dataKey="value" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.6} />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </section>

      {/* Main Grid */}
      <div className="grid md:grid-cols-3 gap-8">
        {/* Left Column - Progress */}
        <div className="md:col-span-2 space-y-8">
           <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
             <h3 className="text-xl font-bold mb-6">Subject Progress</h3>
             <div className="h-64">
               <ResponsiveContainer width="100%" height="100%">
                 <BarChart data={chartData}>
                    <XAxis dataKey="name" axisLine={false} tickLine={false} />
                    <Tooltip cursor={{ fill: 'transparent' }} contentStyle={{ borderRadius: '12px' }} />
                    <Bar dataKey="score" radius={[8, 8, 0, 0]}>
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.score > 80 ? '#f97316' : '#3b82f6'} />
                      ))}
                    </Bar>
                 </BarChart>
               </ResponsiveContainer>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-4">
              <div className="p-6 bg-blue-600 text-white rounded-3xl shadow-lg">
                <h4 className="font-bold">Next Class</h4>
                <p className="text-3xl mt-2">Physics</p>
