           <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
             <h3 className="text-xl font-bold mb-4">Class Routine</h3>
             <div className="space-y-3">
               {['Monday: Physics (10AM)', 'Tuesday: Math (11AM)', 'Wednesday: Bio (9AM)'].map((day, i) => (
                 <div key={i} className="p-3 bg-slate-50 dark:bg-slate-900 rounded-xl text-sm border border-slate-100 dark:border-slate-800 flex justify-between">
                   <span>{day.split(':')[0]}</span>
                   <span className="font-bold text-blue-500">{day.split(':')[1]}</span>
                 </div>
               ))}
             </div>
             <button className="w-full mt-6 py-2 border-2 border-slate-200 dark:border-slate-700 rounded-xl text-sm font-bold hover:bg-slate-50">
               View Full Routine
             </button>
           </div>

           <div className="bg-orange-500 p-6 rounded-3xl shadow-lg text-white space-y-4">
             <h3 className="text-xl font-bold">Study Materials</h3>
             <p className="text-sm opacity-90">Access lecture notes, PDFs, and recorded sessions.</p>
             <button className="w-full py-3 bg-white text-orange-600 font-bold rounded-xl shadow-md">
               Download Hub
             </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;

