          <div className="space-y-2">
            <label className="text-sm font-semibold">Password</label>
            <input 
              required
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-4 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-blue-500"
              placeholder="••••••••"
            />
          </div>
          <button type="submit" className={`w-full py-4 text-white font-bold rounded-xl shadow-lg transition-transform hover:-translate-y-1 ${selectedRole === UserRole.STUDENT ? 'bg-blue-600' : 'bg-orange-600'}`}>
            Login as {selectedRole === UserRole.STUDENT ? 'Student' : 'Admin'}
          </button>
        </form>

        <div className="text-center space-y-1 pt-4">
          <p className="text-xs text-slate-400 font-medium">Demo Credentials:</p>
          <p className="text-[10px] text-slate-500">Admin: <span className="font-mono text-orange-500">admin@phoenix.com</span></p>
          <p className="text-[10px] text-slate-500">Student: <span className="font-mono text-blue-500">arif@student.com</span></p>
          <p className="text-[10px] text-slate-400 italic mt-2">(Use any password to log in)</p>
        </div>
      </div>
    </div>
  );
