          {role === UserRole.GUEST ? (
            <button onClick={() => navigate('login')} className="block w-full text-left py-2 text-blue-600 font-bold">Login</button>
          ) : (
            <button onClick={onLogout} className="block w-full text-left py-2 text-red-500">Logout</button>
