          <h3 className="text-xl font-bold">Site Configuration</h3>
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-500 uppercase">Logo Icon / Text (1-2 chars)</label>
              <div className="flex gap-4 items-center">
                <input 
                  type="text" 
                  maxLength={5}
                  value={logo}
                  onChange={(e) => setLogo(e.target.value)}
                  className="p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none flex-1"
                  placeholder="e.g. P or PH"
                />
                <div className="w-12 h-12 bg-orange-500 rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg">
                  {logo}
                </div>
              </div>
