          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-200 dark:border-slate-700">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold">Add New Student</h2>
              <button onClick={() => setIsAddModalOpen(false)} className="text-slate-400 hover:text-slate-600">✕</button>
            </div>
            <form onSubmit={handleAddStudent} className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-500">Full Name</label>
                <input required type="text" className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-blue-500" value={newStudent.name} onChange={e => setNewStudent({...newStudent, name: e.target.value})}/>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-500">Email Address</label>
                <input required type="email" className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-blue-500" value={newStudent.email} onChange={e => setNewStudent({...newStudent, email: e.target.value})}/>
              </div>
              <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsAddModalOpen(false)} className="flex-1 py-3 bg-slate-100 dark:bg-slate-700 font-bold rounded-xl">Cancel</button>
                <button type="submit" className="flex-1 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-200 dark:border-slate-700">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold">Add New Subject</h2>
              <button onClick={() => setIsCourseModalOpen(false)} className="text-slate-400 hover:text-slate-600">✕</button>
            </div>
            <form onSubmit={handleAddCourse} className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-500">Subject Name</label>
                <input required type="text" className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none" value={newCourse.name} onChange={e => setNewCourse({...newCourse, name: e.target.value})} placeholder="e.g. Physics"/>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-500">Icon (Emoji)</label>
                <input type="text" className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none" value={newCourse.icon} onChange={e => setNewCourse({...newCourse, icon: e.target.value})} placeholder="🧪"/>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-500">Classes Per Week</label>
                <input type="number" className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none" value={newCourse.classesPerWeek} onChange={e => setNewCourse({...newCourse, classesPerWeek: Number(e.target.value)})}/>
              </div>
              <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsCourseModalOpen(false)} className="flex-1 py-3 bg-slate-100 dark:bg-slate-700 font-bold rounded-xl">Cancel</button>
                <button type="submit" className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl shadow-lg">Add Course</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { MOCK_STUDENTS } from '../constants';
import { Student, Subject } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis } from 'recharts';

const growthData = [
  { name: 'Jan', students: 400 },
  { name: 'Feb', students: 520 },
  { name: 'Mar', students: 680 },
  { name: 'Apr', students: 750 },
  { name: 'May', students: 900 },
  { name: 'Jun', students: 850 },
];

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout, logo, setLogo, subjects, setSubjects }) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);

  // Attendance state: Map of studentId -> boolean (present today)
  const [attendanceToday, setAttendanceToday] = useState<Record<string, boolean>>({});

  // Student Form State
  const [newStudent, setNewStudent] = useState({
    name: '',
    email: '',
    class: 'HSC 1st Year' as 'HSC 1st Year' | 'HSC 2nd Year',
    averageScore: 0
  });

  // Course Form State
  const [newCourse, setNewCourse] = useState({
    name: '',
    icon: '📚',
    classesPerWeek: 3
  });

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.name || !newStudent.email) return;

    const studentToAdd: Student = {
      id: `s${Date.now()}`,
      name: newStudent.name,
      email: newStudent.email,
      class: newStudent.class,
      attendance: 100,
      averageScore: Number(newStudent.averageScore),
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name)
    };

    setStudents([studentToAdd, ...students]);
    setIsAddModalOpen(false);
    setNewStudent({ name: '', email: '', class: 'HSC 1st Year', averageScore: 0 });
  };

  const handleDeleteStudent = (id: string) => {
    if (confirm('Are you sure you want to delete this student?')) {
      setStudents(students.filter(s => s.id !== id));
    }
  };

  const toggleAttendance = (id: string) => {
    setAttendanceToday(prev => ({
      ...prev,
      [id]: !prev[id]
    }));

    // Update local students list to reflect a simulated increase in percentage if marked present
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        const isCurrentlyPresent = attendanceToday[id];
        // If we are marking as present now (!isCurrentlyPresent), slightly bump the percentage for demo
        const newAttendance = !isCurrentlyPresent 
          ? Math.min(100, s.attendance + 0.5) 
          : Math.max(0, s.attendance - 0.5);
        return { ...s, attendance: parseFloat(newAttendance.toFixed(1)) };
      }
      return s;
    }));
  };

  const handleAddCourse = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCourse.name) return;
    const courseToAdd: Subject = {
      id: `sub-${Date.now()}`,
      ...newCourse
    };
    setSubjects([...subjects, courseToAdd]);
    setIsCourseModalOpen(false);
    setNewCourse({ name: '', icon: '📚', classesPerWeek: 3 });
  };

  const handleDeleteCourse = (id: string) => {
    if (confirm('Are you sure you want to delete this course?')) {
      setSubjects(subjects.filter(s => s.id !== id));
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold">Admin Console</h1>
          <p className="text-slate-500">Phoenix Edu Care Management</p>
        </div>
        <div className="flex space-x-2">
           <button className="px-4 py-2 bg-orange-500 text-white rounded-xl font-bold text-sm shadow-md hover:bg-orange-600 transition-colors">
             Send Announcement
           </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto">
        {['Overview', 'Students', 'Attendance', 'Courses', 'Settings'].map(tab => (
          <button 
            key={tab}
            onClick={() => setActiveTab(tab.toLowerCase())}
            className={`pb-4 px-2 text-sm font-bold whitespace-nowrap transition-all ${activeTab === tab.toLowerCase() ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
          >
            {tab}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Total Students</p>
               <p className="text-4xl font-bold">{students.length + 1200}</p>
               <p className="text-xs text-green-500 mt-2">↑ 12% from last month</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Total Courses</p>
               <p className="text-4xl font-bold">{subjects.length}</p>
               <p className="text-xs text-blue-500 mt-2">Active curriculum</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Monthly Revenue</p>
               <p className="text-4xl font-bold">$12,450</p>
               <p className="text-xs text-green-500 mt-2">↑ 5% target achieved</p>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-sm border dark:border-slate-700">
             <h3 className="text-xl font-bold mb-8">Enrolment Growth</h3>
             <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={growthData}>
                    <defs>
                      <linearGradient id="colorStudents" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                    <Area type="monotone" dataKey="students" stroke="#3b82f6" fillOpacity={1} fill="url(#colorStudents)" />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Class</th>
                <th className="px-6 py-4">Performance</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-slate-700">
              {students.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center text-blue-600 dark:text-blue-300 font-bold text-xs">
                        {student.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-bold cursor-pointer hover:text-blue-600" onClick={() => setViewingStudent(student)}>{student.name}</p>
                        <p className="text-xs text-slate-500">{student.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm">{student.class}</td>
                  <td className="px-6 py-4 text-sm">
                    <div className="flex items-center space-x-2">
                       <span className={`w-2 h-2 rounded-full ${student.averageScore > 75 ? 'bg-green-500' : 'bg-orange-500'}`}></span>
                       <span>{student.averageScore}% avg</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded-full ${student.feesPaid ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {student.feesPaid ? 'Active' : 'Fee Due'}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right space-x-3">
                    <button 
                      onClick={() => setViewingStudent(student)}
                      className="text-blue-600 font-bold text-xs opacity-0 group-hover:opacity-100 transition-opacity hover:underline"
                    >
                      View
                    </button>
                    <button 
                      onClick={() => handleDeleteStudent(student.id)}
                      className="text-red-500 font-bold text-xs opacity-0 group-hover:opacity-100 transition-opacity hover:underline"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="p-6 text-center border-t dark:border-slate-700">
             <button 
               onClick={() => setIsAddModalOpen(true)}
               className="text-sm font-bold text-blue-600 hover:text-blue-700 flex items-center justify-center mx-auto space-x-2"
             >
               <span>+</span>
               <span>Add New Student</span>
             </button>
          </div>
        </div>
      )}

      {activeTab === 'attendance' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b dark:border-slate-700 flex justify-between items-center">
            <h3 className="font-bold text-lg">Mark Attendance - {new Date().toLocaleDateString()}</h3>
            <span className="text-xs text-slate-500 bg-slate-100 dark:bg-slate-900 px-3 py-1 rounded-full uppercase font-bold tracking-wider">Daily Tracker</span>
          </div>
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Class</th>
                <th className="px-6 py-4 text-center">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-slate-700">
              {students.map(student => (
                <tr key={`att-${student.id}`} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center font-bold text-xs">
                        {student.name.charAt(0)}
                      </div>
                      <p className="font-bold">{student.name}</p>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm">{student.class}</td>
                  <td className="px-6 py-4 text-center">
                    <button 
                      onClick={() => toggleAttendance(student.id)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-sm ${attendanceToday[student.id] ? 'bg-green-500 text-white' : 'bg-slate-100 dark:bg-slate-900 text-slate-500'}`}
                    >
                      {attendanceToday[student.id] ? '✓ Present' : 'Mark Present'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="p-8 bg-slate-50 dark:bg-slate-900/50 text-center">
             <p className="text-sm text-slate-500 italic">"Attendance updates real-time performance indicators for students."</p>
          </div>
        </div>
      )}

      {activeTab === 'courses' && (
        <div className="space-y-6">
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {subjects.map(sub => (
              <div key={sub.id} className="p-6 bg-white dark:bg-slate-800 rounded-3xl border dark:border-slate-700 shadow-sm relative group">
                <div className="text-4xl mb-4">{sub.icon}</div>
                <h4 className="text-xl font-bold">{sub.name}</h4>
                <p className="text-sm text-slate-500">{sub.classesPerWeek} Classes/Week</p>
                <button 
                  onClick={() => handleDeleteCourse(sub.id)}
                  className="absolute top-4 right-4 text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  ✕
                </button>
              </div>
            ))}
            <button 
              onClick={() => setIsCourseModalOpen(true)}
              className="p-6 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-3xl flex flex-col items-center justify-center text-slate-400 hover:border-blue-500 hover:text-blue-500 transition-all"
            >
              <span className="text-3xl">+</span>
              <span className="font-bold text-sm">Add New Subject</span>
            </button>
          </div>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="max-w-2xl bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 shadow-sm space-y-8">
          <h3 className="text-xl font-bold">Site Configuration</h3>
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-500 uppercase">Logo Icon / Text (1-2 chars)</label>
              <div className="flex gap-4 items-center">
                <input 
                  type="text" 
                  maxLength={5}
                  value={logo}
                  onChange={(e) => setLogo(e.target.value)}
                  className="p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none flex-1"
                  placeholder="e.g. P or PH"
                />
                <div className="w-12 h-12 bg-orange-500 rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg">
                  {logo}
                </div>
              </div>
            </div>
            <p className="text-xs text-slate-400 italic">This logo reflects in the main navigation bar and footer.</p>
          </div>
        </div>
      )}

      {/* Viewing Student Details Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
            <div className="flex-1 p-8 md:p-12 space-y-8 overflow-y-auto">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-3xl font-bold">{viewingStudent.name}</h2>
                  <p className="text-slate-500">{viewingStudent.email}</p>
                </div>
                <button onClick={() => setViewingStudent(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-slate-200">✕</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Academic Record</p>
                  <p className="text-4xl font-extrabold text-blue-600">{viewingStudent.averageScore}%</p>
                  <p className="text-xs mt-1">Average Grade Point</p>
                </div>
                <div className="p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Attendance</p>
                  <p className="text-4xl font-extrabold text-orange-500">{viewingStudent.attendance}%</p>
                  <p className="text-xs mt-1">Class Participation</p>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="font-bold">Enrolled Subjects</h4>
                <div className="flex flex-wrap gap-2">
                  {viewingStudent.subjects.map(s => (
                    <span key={s} className="px-4 py-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full text-sm font-bold border border-blue-100 dark:border-blue-800">
