            </tbody>
          </table>
          <div className="p-6 text-center border-t dark:border-slate-700">
             <button onClick={() => setIsAddModalOpen(true)} className="text-sm font-bold text-blue-600">+ Add New Student</button>
          </div>
        </div>
      )}

      {activeTab === 'pending' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          {pendingStudents.length === 0 ? (
            <div className="p-12 text-center text-slate-400 font-medium italic">No pending verifications.</div>
