                      >
                        Approve & Verify
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === 'attendance' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4 text-center">Mark Attendance</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={`att-${student.id}`}>
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center font-bold text-xs">{student.name.charAt(0)}</div>
                      <p className="font-bold">{student.name}</p>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button 
                      onClick={() => toggleAttendance(student.id)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold ${attendanceToday[student.id] ? 'bg-green-500 text-white' : 'bg-slate-100 dark:bg-slate-900 text-slate-500'}`}
                    >
                      {attendanceToday[student.id] ? '✓ Present' : 'Mark Present'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="grid md:grid-cols-2 gap-8">
          {/* Admin Profile Update */}
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-xl font-bold">Admin Profile</h3>
            <form onSubmit={handleUpdateAdminProfile} className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase">Admin Name</label>
                <input 
                  type="text" 
                  value={editAdmin.name}
                  onChange={e => setEditAdmin({...editAdmin, name: e.target.value})}
                  className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase">Admin Email</label>
                <input 
                  type="email" 
                  value={editAdmin.email}
                  onChange={e => setEditAdmin({...editAdmin, email: e.target.value})}
                  className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase">Avatar URL</label>
                <input 
                  type="text" 
                  value={editAdmin.avatar}
                  onChange={e => setEditAdmin({...editAdmin, avatar: e.target.value})}
                  className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none"
                />
              </div>
              <button type="submit" className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg">Update Profile</button>
            </form>
          </div>

          {/* Site Settings */}
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-xl font-bold">Site Configuration</h3>
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-500 uppercase">Logo Icon / Text</label>
                <div className="flex gap-4 items-center">
                  <input 
                    type="text" 
                    maxLength={5}
                    value={logo}
                    onChange={(e) => setLogo(e.target.value)}
                    className="p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none flex-1"
                  />
                  <div className="w-12 h-12 bg-orange-500 rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg">
                    {logo}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Student Details Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden p-8 space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-bold">{viewingStudent.name}</h2>
              <button onClick={() => setViewingStudent(null)} className="p-2 bg-slate-100 rounded-full">✕</button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl">
                <p className="text-xs text-slate-500 uppercase font-bold">Performance</p>
                <p className="text-2xl font-bold text-blue-600">{viewingStudent.averageScore}%</p>
              </div>
              <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl">
                <p className="text-xs text-slate-500 uppercase font-bold">Attendance</p>
                <p className="text-2xl font-bold text-orange-500">{viewingStudent.attendance}%</p>
              </div>
            </div>
            <div>
              <p className="text-sm font-bold mb-2">Enrolled Subjects:</p>
              <div className="flex flex-wrap gap-2">
                {viewingStudent.subjects.map(s => <span key={s} className="px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-xs font-bold">{s}</span>)}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Add Student Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-200 dark:border-slate-700">
            <h2 className="text-2xl font-bold mb-6">Add Verified Student</h2>
            <form onSubmit={handleAddStudent} className="space-y-4">
              <input required type="text" className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Student Name" value={newStudent.name} onChange={e => setNewStudent({...newStudent, name: e.target.value})}/>
              <input required type="email" className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Email" value={newStudent.email} onChange={e => setNewStudent({...newStudent, email: e.target.value})}/>
              <button type="submit" className="w-full py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg">Save Student</button>
              <button type="button" onClick={() => setIsAddModalOpen(false)} className="w-full py-2 text-slate-500">Cancel</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AdminUser } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const growthData = [
  { name: 'Jan', students: 400 },
  { name: 'Feb', students: 520 },
  { name: 'Mar', students: 680 },
  { name: 'Apr', students: 750 },
  { name: 'May', students: 900 },
  { name: 'Jun', students: 850 },
];

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, adminProfile, setAdminProfile 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [attendanceToday, setAttendanceToday] = useState<Record<string, boolean>>({});

  // Admin Profile State
  const [editAdmin, setEditAdmin] = useState<AdminUser>({ ...adminProfile });

  // Student Form State
  const [newStudent, setNewStudent] = useState({
    name: '',
    email: '',
    class: 'HSC 1st Year' as 'HSC 1st Year' | 'HSC 2nd Year',
    averageScore: 0
  });

  // Course Form State
  const [courseForm, setCourseForm] = useState({
    name: '',
    icon: '📚',
    classesPerWeek: 3
  });

  useEffect(() => {
    if (editingCourse) {
      setCourseForm({
        name: editingCourse.name,
        icon: editingCourse.icon,
        classesPerWeek: editingCourse.classesPerWeek
      });
    } else {
      setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
    }
  }, [editingCourse]);

  const handleUpdateAdminProfile = (e: React.FormEvent) => {
    e.preventDefault();
    setAdminProfile(editAdmin);
    alert("Admin Profile Updated Successfully!");
  };

  const verifyStudent = (id: string) => {
    setStudents(prev => prev.map(s => s.id === id ? { ...s, isVerified: true } : s));
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.name || !newStudent.email) return;

    const studentToAdd: Student = {
      id: `s${Date.now()}`,
      name: newStudent.name,
      email: newStudent.email,
      class: newStudent.class,
      attendance: 100,
      averageScore: Number(newStudent.averageScore),
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: true
    };

    setStudents([studentToAdd, ...students]);
    setIsAddModalOpen(false);
    setNewStudent({ name: '', email: '', class: 'HSC 1st Year', averageScore: 0 });
  };

  const handleDeleteStudent = (id: string) => {
    if (confirm('Are you sure you want to delete this student?')) {
      setStudents(students.filter(s => s.id !== id));
    }
  };

  const toggleAttendance = (id: string) => {
    setAttendanceToday(prev => ({
      ...prev,
      [id]: !prev[id]
    }));

    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        const isCurrentlyPresent = attendanceToday[id];
        const newAttendance = !isCurrentlyPresent 
          ? Math.min(100, s.attendance + 0.5) 
          : Math.max(0, s.attendance - 0.5);
        return { ...s, attendance: parseFloat(newAttendance.toFixed(1)) };
      }
      return s;
    }));
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!courseForm.name) return;

    if (editingCourse) {
      // Edit existing
      setSubjects(subjects.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
    } else {
      // Add new
      const courseToAdd: Subject = {
        id: `sub-${Date.now()}`,
        ...courseForm
      };
      setSubjects([...subjects, courseToAdd]);
    }

    setIsCourseModalOpen(false);
    setEditingCourse(null);
    setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
  };

  const handleDeleteCourse = (id: string) => {
    if (confirm('Are you sure you want to delete this course? This might affect student data.')) {
      setSubjects(subjects.filter(s => s.id !== id));
    }
  };

  const openEditCourse = (sub: Subject) => {
    setEditingCourse(sub);
    setIsCourseModalOpen(true);
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <img src={adminProfile.avatar} className="w-12 h-12 rounded-full border-2 border-orange-500" alt="Admin" />
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">System Administrator</p>
          </div>
        </div>
        <div className="flex space-x-2">
           <button className="px-4 py-2 bg-orange-500 text-white rounded-xl font-bold text-sm shadow-md hover:bg-orange-600 transition-colors">
             Send Announcement
           </button>
           <button onClick={onLogout} className="px-4 py-2 bg-slate-200 dark:bg-slate-800 rounded-xl font-bold text-sm">
             Logout
           </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto">
        {[
          { id: 'overview', label: 'Overview' },
          { id: 'students', label: 'Students' },
          { id: 'pending', label: `Pending (${pendingStudents.length})` },
          { id: 'attendance', label: 'Attendance' },
          { id: 'courses', label: 'Courses' },
          { id: 'settings', label: 'Settings' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`pb-4 px-2 text-sm font-bold whitespace-nowrap transition-all ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Total Verified</p>
               <p className="text-4xl font-bold">{verifiedStudents.length}</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Pending Approval</p>
               <p className="text-4xl font-bold text-orange-500">{pendingStudents.length}</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Active Courses</p>
               <p className="text-4xl font-bold">{subjects.length}</p>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-sm border dark:border-slate-700">
             <h3 className="text-xl font-bold mb-8">Enrolment Growth</h3>
             <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={growthData}>
                    <defs>
                      <linearGradient id="colorStudents" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none' }} />
                    <Area type="monotone" dataKey="students" stroke="#3b82f6" fillOpacity={1} fill="url(#colorStudents)" />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4">Class</th>
                <th className="px-6 py-4 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center text-blue-600 font-bold text-xs">
                        {student.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-bold cursor-pointer hover:text-blue-600" onClick={() => setViewingStudent(student)}>{student.name}</p>
                        <p className="text-xs text-slate-500">{student.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm">{student.class}</td>
                  <td className="px-6 py-4 text-right space-x-3">
                    <button onClick={() => setViewingStudent(student)} className="text-blue-600 font-bold text-xs">View</button>
                    <button onClick={() => handleDeleteStudent(student.id)} className="text-red-500 font-bold text-xs">Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="p-6 text-center border-t dark:border-slate-700">
             <button onClick={() => setIsAddModalOpen(true)} className="text-sm font-bold text-blue-600">+ Add New Student</button>
          </div>
        </div>
      )}

      {activeTab === 'pending' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          {pendingStudents.length === 0 ? (
            <div className="p-12 text-center text-slate-400 font-medium italic">No pending verifications.</div>
          ) : (
            <table className="w-full text-left">
              <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
                <tr>
                  <th className="px-6 py-4">Applicant</th>
                  <th className="px-6 py-4">Class</th>
                  <th className="px-6 py-4 text-right">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-700">
                {pendingStudents.map(student => (
                  <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                    <td className="px-6 py-4">
                      <div>
                        <p className="font-bold">{student.name}</p>
                        <p className="text-xs text-slate-500">{student.email}</p>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm">{student.class}</td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => verifyStudent(student.id)}
                        className="bg-green-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-green-700"
                      >
                        Approve & Verify
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === 'attendance' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4 text-center">Mark Attendance</th>
