                  onChange={e => setCourseForm({...courseForm, icon: e.target.value})} 
                  placeholder="🧪"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-500">Classes Per Week</label>
                <input 
                  type="number" 
                  className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none" 
                  value={courseForm.classesPerWeek} 
                  onChange={e => setCourseForm({...courseForm, classesPerWeek: Number(e.target.value)})}
                />
              </div>
              <div className="pt-4 flex gap-3">
                <button 
                  type="button" 
                  onClick={() => { setIsCourseModalOpen(false); setEditingCourse(null); }} 
                  className="flex-1 py-3 bg-slate-100 dark:bg-slate-700 font-bold rounded-xl"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className={`flex-1 py-3 text-white font-bold rounded-xl shadow-lg ${editingCourse ? 'bg-blue-600' : 'bg-orange-500'}`}
