      {activeTab === 'courses' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-xl font-bold">Curriculum</h3>
            <button onClick={() => { setEditingCourse(null); setIsCourseModalOpen(true); }} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-md">+ New Subject</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {subjects.map(sub => (
              <div key={sub.id} className="p-6 bg-white dark:bg-slate-800 rounded-3xl border dark:border-slate-700 flex flex-col justify-between">
                <div>
                  <div className="text-3xl mb-2">{sub.icon}</div>
                  <h4 className="font-bold">{sub.name}</h4>
                  <p className="text-xs text-slate-500">{sub.classesPerWeek} Classes/Week</p>
                </div>
                <div className="mt-4 flex gap-2">
                  <button onClick={() => {setEditingCourse(sub); setIsCourseModalOpen(true);}} className="text-[10px] font-bold text-blue-600">Edit</button>
                  <button onClick={() => handleDeleteCourse(sub.id)} className="text-[10px] font-bold text-red-500">Delete</button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="grid md:grid-cols-2 gap-8">
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 space-y-4">
            <h3 className="font-bold">Admin Profile</h3>
            <input type="text" value={editAdmin.name} onChange={e => setEditAdmin({...editAdmin, name: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Name" />
            <input type="email" value={editAdmin.email} onChange={e => setEditAdmin({...editAdmin, email: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Email" />
            <button onClick={handleUpdateAdminProfile} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold">Update Profile</button>
          </div>
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 space-y-4">
            <h3 className="font-bold">Branding</h3>
            <input type="text" value={logo} onChange={e => setLogo(e.target.value)} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Logo Text" />
          </div>
        </div>
      )}

      {/* Modals */}
      {isTeacherModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-200">
            <h2 className="text-2xl font-bold mb-6">{editingTeacher ? 'Edit Teacher' : 'Add Teacher'}</h2>
            <form onSubmit={handleTeacherSubmit} className="space-y-4">
              <input required type="text" value={teacherForm.name} onChange={e => setTeacherForm({...teacherForm, name: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Full Name" />
              <input required type="text" value={teacherForm.subject} onChange={e => setTeacherForm({...teacherForm, subject: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Subject Expertise" />
              <input type="text" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Qualification" />
              <input type="text" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Experience (e.g. 5 Years)" />
              <input type="text" value={teacherForm.image} onChange={e => setTeacherForm({...teacherForm, image: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Image URL" />
              <button type="submit" className="w-full py-3 bg-orange-600 text-white font-bold rounded-xl shadow-lg">{editingTeacher ? 'Update' : 'Add Teacher'}</button>
              <button type="button" onClick={() => {setIsTeacherModalOpen(false); setEditingTeacher(null);}} className="w-full py-2 text-slate-500">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-200">
            <h2 className="text-2xl font-bold mb-6">{editingCourse ? 'Edit Subject' : 'Add Subject'}</h2>
            <form onSubmit={handleCourseSubmit} className="space-y-4">
              <input required type="text" value={courseForm.name} onChange={e => setCourseForm({...courseForm, name: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Name" />
              <input type="text" value={courseForm.icon} onChange={e => setCourseForm({...courseForm, icon: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Icon (Emoji)" />
              <input type="number" value={courseForm.classesPerWeek} onChange={e => setCourseForm({...courseForm, classesPerWeek: Number(e.target.value)})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Classes/Week" />
              <button type="submit" className="w-full py-3 bg-blue-600 text-white font-bold rounded-xl">{editingCourse ? 'Update' : 'Add'}</button>
              <button type="button" onClick={() => {setIsCourseModalOpen(false); setEditingCourse(null);}} className="w-full py-2 text-slate-500">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {isAddModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-200">
            <h2 className="text-2xl font-bold mb-6">Add Verified Student</h2>
            <form onSubmit={handleAddStudent} className="space-y-4">
              <input required type="text" value={newStudent.name} onChange={e => setNewStudent({...newStudent, name: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Name" />
              <input required type="email" value={newStudent.email} onChange={e => setNewStudent({...newStudent, email: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Email" />
              <button type="submit" className="w-full py-3 bg-blue-600 text-white font-bold rounded-xl">Save</button>
              <button type="button" onClick={() => setIsAddModalOpen(false)} className="w-full py-2 text-slate-500">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {viewingStudent && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl p-8 space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-bold">{viewingStudent.name}</h2>
              <button onClick={() => setViewingStudent(null)} className="p-2 bg-slate-100 rounded-full">✕</button>
