            <div className="grid grid-cols-2 gap-4 text-sm">
              <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl">
                <p className="text-slate-500 uppercase font-bold">Performance</p>
                <p className="text-2xl font-bold text-blue-600">{viewingStudent.averageScore}%</p>
              </div>
              <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl">
                <p className="text-slate-500 uppercase font-bold">Attendance</p>
