export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AdminUser, Teacher } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Radar, RadarChart, PolarGrid, PolarAngleAxis } from 'recharts';

const growthData = [
  { name: 'Jan', students: 400 },
  { name: 'Feb', students: 520 },
  { name: 'Mar', students: 680 },
  { name: 'Apr', students: 750 },
  { name: 'May', students: 900 },
  { name: 'Jun', students: 850 },
];

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, adminProfile, setAdminProfile 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);

  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [attendanceToday, setAttendanceToday] = useState<Record<string, boolean>>({});
  const [lastMarkedId, setLastMarkedId] = useState<string | null>(null);

  // Admin Profile State
  const [editAdmin, setEditAdmin] = useState<AdminUser>({ ...adminProfile });

  // Form States
  const [newStudent, setNewStudent] = useState({
    name: '',
    email: '',
    class: 'HSC 1st Year' as 'HSC 1st Year' | 'HSC 2nd Year',
    averageScore: 0
  });

  const [courseForm, setCourseForm] = useState({
    name: '',
    icon: '📚',
    classesPerWeek: 3
  });

  const [teacherForm, setTeacherForm] = useState({
    name: '',
    subject: '',
    qualification: '',
    experience: '',
    image: ''
  });

  // Sync edit forms
  useEffect(() => {
    if (editingCourse) {
      setCourseForm({
        name: editingCourse.name,
        icon: editingCourse.icon,
        classesPerWeek: editingCourse.classesPerWeek
      });
    } else {
      setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
    }
  }, [editingCourse]);

  useEffect(() => {
    if (editingTeacher) {
      setTeacherForm({
        name: editingTeacher.name,
        subject: editingTeacher.subject,
        qualification: editingTeacher.qualification,
        experience: editingTeacher.experience,
        image: editingTeacher.image
      });
    } else {
      setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
    }
  }, [editingTeacher]);

  const handleUpdateAdminProfile = (e: React.FormEvent) => {
    e.preventDefault();
    setAdminProfile(editAdmin);
    alert("Admin Profile Updated Successfully!");
  };

  const verifyStudent = (id: string) => {
    setStudents(prev => prev.map(s => s.id === id ? { ...s, isVerified: true } : s));
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.name || !newStudent.email) return;

    const studentToAdd: Student = {
      id: `s${Date.now()}`,
      name: newStudent.name,
      email: newStudent.email,
      class: newStudent.class,
      attendance: 100,
      averageScore: Number(newStudent.averageScore),
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: true
    };

    setStudents([studentToAdd, ...students]);
    setIsAddModalOpen(false);
    setNewStudent({ name: '', email: '', class: 'HSC 1st Year', averageScore: 0 });
  };

  const handleDeleteStudent = (id: string) => {
    if (confirm('Are you sure you want to delete this student?')) {
      setStudents(students.filter(s => s.id !== id));
    }
  };

  const toggleAttendance = (id: string) => {
    const isCurrentlyPresent = attendanceToday[id];

    // Set feedback indicator
    setLastMarkedId(id);
    setTimeout(() => setLastMarkedId(null), 1000);

    setAttendanceToday(prev => ({
      ...prev,
      [id]: !isCurrentlyPresent
    }));

    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        // If we are marking as present (+0.5%), if marking as absent (-0.5%)
        const newAttendance = !isCurrentlyPresent 
          ? Math.min(100, s.attendance + 0.5) 
          : Math.max(0, s.attendance - 0.5);
        return { ...s, attendance: parseFloat(newAttendance.toFixed(1)) };
      }
      return s;
    }));
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!courseForm.name) return;

    if (editingCourse) {
      setSubjects(subjects.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
    } else {
      const courseToAdd: Subject = {
        id: `sub-${Date.now()}`,
        ...courseForm
      };
      setSubjects([...subjects, courseToAdd]);
    }

    setIsCourseModalOpen(false);
    setEditingCourse(null);
  };

  const handleDeleteCourse = (id: string) => {
    if (confirm('Are you sure you want to delete this course?')) {
      setSubjects(subjects.filter(s => s.id !== id));
    }
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!teacherForm.name) return;

    if (editingTeacher) {
      setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    } else {
      const teacherToAdd: Teacher = {
        id: `t-${Date.now()}`,
        ...teacherForm
      };
      setTeachers([...teachers, teacherToAdd]);
    }

    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleDeleteTeacher = (id: string) => {
    if (confirm('Are you sure you want to delete this teacher?')) {
      setTeachers(teachers.filter(t => t.id !== id));
    }
  };

  const openEditTeacher = (teacher: Teacher) => {
    setEditingTeacher(teacher);
    setIsTeacherModalOpen(true);
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);
  const presentCount = Object.values(attendanceToday).filter(v => v).length;

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <img src={adminProfile.avatar} className="w-12 h-12 rounded-full border-2 border-orange-500" alt="Admin" />
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">System Administrator</p>
          </div>
        </div>
        <div className="flex space-x-2">
           <button className="px-4 py-2 bg-orange-500 text-white rounded-xl font-bold text-sm shadow-md hover:bg-orange-600 transition-colors">
             Send Announcement
           </button>
           <button onClick={onLogout} className="px-4 py-2 bg-slate-200 dark:bg-slate-800 rounded-xl font-bold text-sm">
             Logout
           </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto">
        {[
          { id: 'overview', label: 'Overview' },
          { id: 'students', label: 'Students' },
          { id: 'teachers', label: 'Teachers' },
          { id: 'pending', label: `Pending (${pendingStudents.length})` },
          { id: 'attendance', label: 'Attendance' },
          { id: 'courses', label: 'Courses' },
          { id: 'settings', label: 'Settings' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`pb-4 px-2 text-sm font-bold whitespace-nowrap transition-all ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Total Students</p>
               <p className="text-4xl font-bold">{verifiedStudents.length}</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Total Faculty</p>
               <p className="text-4xl font-bold">{teachers.length}</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Pending</p>
               <p className="text-4xl font-bold text-orange-500">{pendingStudents.length}</p>
            </div>
            <div className="p-6 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
               <p className="text-sm font-bold text-slate-500 mb-1 uppercase">Courses</p>
               <p className="text-4xl font-bold">{subjects.length}</p>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-sm border dark:border-slate-700">
             <h3 className="text-xl font-bold mb-8">System Analytics</h3>
             <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={growthData}>
                    <defs>
                      <linearGradient id="colorStudents" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8}/>
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#94a3b8' }} />
                    <Tooltip />
                    <Area type="monotone" dataKey="students" stroke="#3b82f6" fillOpacity={1} fill="url(#colorStudents)" />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs uppercase font-bold text-slate-500">
              <tr>
                <th className="px-6 py-4">Student</th>
                <th className="px-6 py-4 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">{student.name.charAt(0)}</div>
                      <div>
                        <p className="font-bold cursor-pointer hover:text-blue-600" onClick={() => setViewingStudent(student)}>{student.name}</p>
                        <p className="text-xs text-slate-500">{student.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right space-x-3">
                    <button onClick={() => setViewingStudent(student)} className="text-blue-600 font-bold text-xs">View</button>
                    <button onClick={() => handleDeleteStudent(student.id)} className="text-red-500 font-bold text-xs">Delete</button>
                  </td>
                </tr>
