              className="bg-orange-600 text-white px-4 py-2 rounded-xl text-sm font-bold"
            >
              + Add New Teacher
            </button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {teachers.map(teacher => (
              <div key={teacher.id} className="bg-white dark:bg-slate-800 p-6 rounded-3xl border dark:border-slate-700 shadow-sm relative group flex items-start space-x-4">
                <img src={teacher.image || 'https://via.placeholder.com/80'} className="w-16 h-16 rounded-2xl object-cover" alt={teacher.name} />
                <div className="flex-grow">
