                  <p className="text-xs font-bold text-orange-500">{teacher.subject}</p>
                  <p className="text-xs text-slate-500 mt-1">{teacher.experience} Exp</p>
                  <div className="mt-4 flex gap-2">
                    <button onClick={() => openEditTeacher(teacher)} className="text-[10px] font-bold text-blue-600 hover:underline">Edit</button>
                    <button onClick={() => handleDeleteTeacher(teacher.id)} className="text-[10px] font-bold text-red-500 hover:underline">Delete</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'pending' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500">
              <tr><th className="px-6 py-4">Applicant</th><th className="px-6 py-4 text-right">Action</th></tr>
            </thead>
            <tbody className="divide-y dark:divide-slate-700">
              {pendingStudents.map(student => (
                <tr key={student.id}>
                  <td className="px-6 py-4">
                    <p className="font-bold">{student.name}</p>
                    <p className="text-xs text-slate-500">{student.email}</p>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => verifyStudent(student.id)} className="bg-green-600 text-white px-4 py-2 rounded-xl text-xs font-bold">Verify</button>
                  </td>
                </tr>
              ))}
              {pendingStudents.length === 0 && (
                <tr><td colSpan={2} className="p-8 text-center text-slate-400 italic">No pending requests</td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'attendance' && (
        <div className="space-y-6">
          <div className="bg-blue-600 text-white p-6 rounded-3xl shadow-lg flex flex-col md:flex-row justify-between items-center gap-4">
            <div>
              <h3 className="text-xl font-bold">Daily Attendance Summary</h3>
              <p className="text-blue-100 text-sm">{new Date().toDateString()}</p>
            </div>
            <div className="flex items-center space-x-6">
              <div className="text-center">
                <p className="text-3xl font-extrabold">{presentCount}</p>
                <p className="text-[10px] uppercase font-bold opacity-75">Present</p>
              </div>
              <div className="w-px h-10 bg-blue-400 opacity-50"></div>
              <div className="text-center">
                <p className="text-3xl font-extrabold">{verifiedStudents.length - presentCount}</p>
                <p className="text-[10px] uppercase font-bold opacity-75">Absent</p>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 dark:bg-slate-900 text-xs font-bold text-slate-500 uppercase">
                <tr>
                  <th className="px-6 py-4">Student Name</th>
                  <th className="px-6 py-4 text-center">Current %</th>
                  <th className="px-6 py-4 text-center">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-700">
                {verifiedStudents.map(student => (
                  <tr key={`att-${student.id}`} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                    <td className="px-6 py-4 font-bold">{student.name}</td>
                    <td className="px-6 py-4 text-center">
                      <span className={`text-sm font-bold ${student.attendance < 75 ? 'text-red-500' : 'text-green-500'}`}>
                        {student.attendance}%
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center relative">
                      <button 
                        onClick={() => toggleAttendance(student.id)} 
                        className={`px-6 py-2 rounded-xl text-xs font-bold transition-all transform active:scale-95 shadow-sm ${
                          attendanceToday[student.id] 
                            ? 'bg-green-500 text-white ring-2 ring-green-100 dark:ring-green-900' 
                            : 'bg-slate-100 dark:bg-slate-900 text-slate-500 hover:bg-slate-200'
                        }`}
                      >
                        {attendanceToday[student.id] ? '✓ Present' : 'Mark Present'}
                      </button>
                      {lastMarkedId === student.id && (
                        <span className="absolute -top-1 left-1/2 -translate-x-1/2 bg-green-500 text-white text-[8px] font-bold px-2 py-0.5 rounded-full animate-bounce">
                          SAVED
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'courses' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-xl font-bold">Curriculum</h3>
            <button onClick={() => { setEditingCourse(null); setIsCourseModalOpen(true); }} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-md">+ New Subject</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {subjects.map(sub => (
              <div key={sub.id} className="p-6 bg-white dark:bg-slate-800 rounded-3xl border dark:border-slate-700 flex flex-col justify-between">
                <div>
                  <div className="text-3xl mb-2">{sub.icon}</div>
                  <h4 className="font-bold">{sub.name}</h4>
                  <p className="text-xs text-slate-500">{sub.classesPerWeek} Classes/Week</p>
                </div>
                <div className="mt-4 flex gap-2">
                  <button onClick={() => {setEditingCourse(sub); setIsCourseModalOpen(true);}} className="text-[10px] font-bold text-blue-600">Edit</button>
                  <button onClick={() => handleDeleteCourse(sub.id)} className="text-[10px] font-bold text-red-500">Delete</button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="grid md:grid-cols-2 gap-8">
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 space-y-4">
            <h3 className="font-bold">Admin Profile</h3>
            <input type="text" value={editAdmin.name} onChange={e => setEditAdmin({...editAdmin, name: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Name" />
            <input type="email" value={editAdmin.email} onChange={e => setEditAdmin({...editAdmin, email: e.target.value})} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Email" />
            <button onClick={handleUpdateAdminProfile} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold">Update Profile</button>
          </div>
          <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border dark:border-slate-700 space-y-4">
            <h3 className="font-bold">Branding</h3>
            <input type="text" value={logo} onChange={e => setLogo(e.target.value)} className="w-full p-3 rounded-xl border dark:bg-slate-900" placeholder="Logo Text" />
          </div>
        </div>
      )}

      {/* Student Details Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
            <div className="flex-1 p-8 md:p-12 space-y-8 overflow-y-auto">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-3xl font-bold">{viewingStudent.name}</h2>
                  <p className="text-slate-500">{viewingStudent.email}</p>
                </div>
                <button onClick={() => setViewingStudent(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-slate-200">✕</button>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div className="p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Exam Avg</p>
                  <p className="text-4xl font-extrabold text-blue-600">{viewingStudent.averageScore}%</p>
                </div>
                <div className="p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Attendance</p>
                  <p className="text-4xl font-extrabold text-orange-500">{viewingStudent.attendance}%</p>
                </div>
                <div className="p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 col-span-2 md:col-span-1">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Assignments</p>
                  <p className="text-4xl font-extrabold text-purple-600">{viewingStudent.assignments}%</p>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="font-bold text-sm uppercase tracking-wider text-slate-400">Student Profile Information</h4>
                <div className="grid grid-cols-2 gap-6 bg-slate-50 dark:bg-slate-900 p-6 rounded-3xl border border-slate-100 dark:border-slate-800">
                  <div>
                    <p className="text-xs text-slate-400">Class Level</p>
                    <p className="font-bold">{viewingStudent.class}</p>
                  </div>
                  <div>
                    <p className="text-xs text-slate-400">Fee Status</p>
                    <p className={`font-bold ${viewingStudent.feesPaid ? 'text-green-500' : 'text-red-500'}`}>
                      {viewingStudent.feesPaid ? 'Paid' : 'Payment Due'}
                    </p>
                  </div>
                  <div className="col-span-2">
                    <p className="text-xs text-slate-400 mb-2">Enrolled Subjects</p>
                    <div className="flex flex-wrap gap-2">
                      {viewingStudent.subjects.map(s => (
                        <span key={s} className="px-3 py-1 bg-white dark:bg-slate-800 border dark:border-slate-700 text-blue-600 rounded-full text-xs font-bold">
                          {s}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="w-full md:w-80 bg-slate-50 dark:bg-slate-900 p-8 flex flex-col items-center justify-center border-l dark:border-slate-800">
              <h4 className="text-sm font-bold uppercase text-slate-400 mb-8">Performance Radar</h4>
              <div className="w-full h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <RadarChart cx="50%" cy="50%" outerRadius="80%" data={[
                    { subject: 'Att', value: viewingStudent.attendance },
                    { subject: 'Exam', value: viewingStudent.averageScore },
                    { subject: 'Asgn', value: viewingStudent.assignments },
                    { subject: 'Fees', value: viewingStudent.feesPaid ? 100 : 0 },
                  ]}>
                    <PolarGrid stroke="#cbd5e1" />
                    <PolarAngleAxis dataKey="subject" tick={{ fontSize: 10, fill: '#94a3b8' }} />
                    <Radar name="Student" dataKey="value" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.6} />
                  </RadarChart>
                </ResponsiveContainer>
              </div>
              <div className="mt-8 text-center px-4">
                <p className="text-[10px] text-slate-400 leading-relaxed italic">
