        <p className="text-slate-600 dark:text-slate-400">Your account has been created and is currently <b>pending verification</b> by our admin team. You can log in once approved.</p>
        <button 
          onClick={() => setSubmitted(false)}
          className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold"
        >
          Close
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="grid md:grid-cols-2 gap-12">
        <div className="space-y-6">
          <h1 className="text-4xl font-bold text-blue-600">Start Your Journey</h1>
