          <div className="space-y-4">
            <div className="flex items-center space-x-4">
              <span className="w-10 h-10 flex items-center justify-center bg-orange-100 text-orange-600 rounded-lg font-bold">1</span>
              <span>Register your basic information</span>
            </div>
