              <span className="w-10 h-10 flex items-center justify-center bg-orange-100 text-orange-600 rounded-lg font-bold">3</span>
              <span>Login to access Dashboard</span>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-700 space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-semibold">Full Name</label>
            <input 
              required 
              type="text" 
              className="w-full p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 focus:ring-2 ring-orange-500 outline-none font-medium" 
              placeholder="Enter student name" 
              value={formData.name}
              onChange={e => setFormData({...formData, name: e.target.value})}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-semibold">Guardian Phone</label>
              <input 
