    switch (currentPage) {
      case 'home': return <Home navigate={navigate} />;
      case 'courses': return <Courses subjects={subjects} />;
      case 'teachers': return <TeachersPage teachers={teachers} />;
      case 'admission': return <Admission onSubmit={handleAdmissionSubmit} />;
      case 'contact': return <Contact />;
      case 'login': return <Login onLogin={handleLogin} />;
      case 'student-dashboard': return <StudentDashboard student={user} exams={exams} onLogout={handleLogout} />;
      case 'admin-dashboard': return (
        <AdminDashboard 
          onLogout={handleLogout} 
          logo={logo} 
          setLogo={setLogo} 
          subjects={subjects} 
          setSubjects={setSubjects}
          students={students}
          setStudents={setStudents}
          teachers={teachers}
          setTeachers={setTeachers}
          exams={exams}
          setExams={setExams}
          adminProfile={adminProfile}
          setAdminProfile={setAdminProfile}
        />
      );
      default: return <Home navigate={navigate} />;
    }
  };

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <Navbar 
        currentPage={currentPage} 
        navigate={navigate} 
        role={role} 
        onLogout={handleLogout}
        darkMode={darkMode}
        toggleDarkMode={() => setDarkMode(!darkMode)}
        logoText={logo}
      />
      <main className="flex-grow pt-16">
        {renderPage()}
      </main>
      <Footer />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { PerformanceInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getPerformanceInsight = async (
  attendance: number,
  score: number,
  assignments: number
): Promise<PerformanceInsight> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze this HSC Science student's performance: 
      Attendance: ${attendance}%, Exam Score: ${score}%, Assignment Completion: ${assignments}%. 
      Provide a concise 1-sentence academic suggestion.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ['Critical', 'Warning', 'Good', 'Excellent'] },
            color: { type: Type.STRING, description: 'CSS color code like red, yellow, green' },
            message: { type: Type.STRING }
          },
          required: ['status', 'color', 'message']
        }
      }
    });

    // Handle potential undefined or empty text response
    const text = response.text;
    if (!text) {
      throw new Error("Empty response from AI");
    }

    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini Error:", error);
    // Fallback logic
    if (score < 50 || attendance < 60) {
      return { status: 'Critical', color: 'red', message: 'Urgent attention required in both attendance and core subjects.' };
    }
    return { status: 'Good', color: 'green', message: 'Maintaining steady progress. Keep focusing on revisions.' };
  }
};

