            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">System Administrator</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-6 py-2 bg-slate-200 dark:bg-slate-800 rounded-2xl font-bold text-sm hover:bg-slate-300">Logout</button>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {[
          { id: 'overview', label: 'Overview' },
          { id: 'students', label: 'Students' },
          { id: 'teachers', label: 'Teachers' },
          { id: 'exams', label: 'Exams' },
          { id: 'pending', label: `Requests (${pendingStudents.length})` },
          { id: 'attendance', label: 'Attendance' },
          { id: 'settings', label: 'Site Config' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`pb-4 px-2 text-sm font-bold whitespace-nowrap transition-all border-b-2 ${activeTab === tab.id ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-700'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Enrolled Students</p>
             <p className="text-5xl font-black text-blue-600">{verifiedStudents.length}</p>
          </div>
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Exams Created</p>
             <p className="text-5xl font-black text-orange-500">{exams.length}</p>
          </div>
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Faculty Members</p>
             <p className="text-5xl font-black text-purple-600">{teachers.length}</p>
          </div>
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Growth Rate</p>
             <p className="text-5xl font-black text-green-500">+12%</p>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b dark:border-slate-700 flex justify-between items-center">
             <h3 className="font-bold">Student Directory</h3>
             <button onClick={() => setIsAddModalOpen(true)} className="text-sm font-bold text-blue-600 hover:underline">+ Register Student</button>
          </div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 rounded-2xl bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-blue-600 font-bold">{student.name.charAt(0)}</div>
                      <div>
                        <p className="font-bold">{student.name}</p>
                        <p className="text-xs text-slate-400">{student.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-xs font-medium text-slate-500">{student.class}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => setViewingStudent(student)} className="bg-slate-100 dark:bg-slate-700 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all">View Details</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'exams' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-2xl font-bold">Exam Center</h3>
            <button onClick={() => setIsExamModalOpen(true)} className="bg-orange-500 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-xl transition-transform hover:scale-105 active:scale-95">New Exam</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {exams.map(exam => (
              <div key={exam.id} className="p-8 bg-white dark:bg-slate-800 rounded-[32px] border dark:border-slate-700 shadow-sm space-y-6 group hover:shadow-xl transition-all">
                <div>
                  <h4 className="font-black text-xl mb-1">{exam.name}</h4>
                  <div className="flex items-center space-x-2">
                    <span className="text-[10px] font-black bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full uppercase">{exam.subject}</span>
                    <span className="text-[10px] font-bold text-slate-400">{exam.date}</span>
                  </div>
                </div>
                <div className="pt-4 flex items-center justify-between border-t dark:border-slate-700">
                  <div className="text-xs text-slate-400 font-bold">{Object.keys(exam.marks).length} Marks Entered</div>
                  <button 
                    onClick={() => setEnteringMarksFor(exam)}
                    className="p-3 bg-slate-100 dark:bg-slate-900 rounded-2xl text-xs font-bold hover:bg-orange-500 hover:text-white transition-all"
                  >
                    Enter Marks
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="space-y-12">
           {/* Logo Upload Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-10">
            <div className="flex flex-col md:flex-row justify-between md:items-center gap-6">
              <h3 className="text-3xl font-black">Branding & Logo</h3>
              <button 
                onClick={() => logoUploadRef.current?.click()}
                className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-lg"
              >
                Upload Device Logo
              </button>
              <input type="file" hidden ref={logoUploadRef} accept="image/*" onChange={(e) => handleFileUpload(e, setLogo)} />
            </div>

            <div className="flex items-center space-x-10 p-6 bg-slate-50 dark:bg-slate-900/50 rounded-[32px]">
               <div className="w-40 h-40 bg-orange-500 rounded-[32px] flex items-center justify-center text-white text-5xl font-black shadow-2xl overflow-hidden border-4 border-white dark:border-slate-700">
                 {isLogoBase64 ? (
                   <img src={logo} className="w-full h-full object-cover" alt="Preview" />
                 ) : (
                   logo
                 )}
               </div>
               <div className="flex-1 space-y-4">
                 <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Logo (Text Fallback)</label>
                 <input 
                   type="text" 
                   maxLength={15} 
                   className="w-full p-4 rounded-2xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-orange-500 font-bold" 
                   value={isLogoBase64 ? "Image Uploaded" : logo} 
                   disabled={isLogoBase64}
                   onChange={e => setLogo(e.target.value)} 
                 />
                 {isLogoBase64 && (
                   <button onClick={() => setLogo('P')} className="text-xs text-red-500 font-bold hover:underline">Remove Image & Use Text</button>
                 )}
                 <p className="text-[11px] text-slate-400 italic">Upload a PNG/JPG for your site logo. If no image is provided, the text fallback will be used.</p>
               </div>
            </div>
          </div>

          {/* Footer Management Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-3xl font-black">Footer Content Management</h3>
            <div className="grid md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Platform Description</label>
                <textarea 
                  className="w-full p-4 rounded-2xl border dark:bg-slate-900 min-h-[120px] outline-none"
                  value={tempFooter.description}
                  onChange={e => setTempFooter({...tempFooter, description: e.target.value})}
                />
              </div>
              <div className="space-y-4">
                 <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Physical Address</label>
                    <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" value={tempFooter.address} onChange={e => setTempFooter({...tempFooter, address: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                       <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Phone</label>
                       <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" value={tempFooter.phone} onChange={e => setTempFooter({...tempFooter, phone: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                       <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Email</label>
                       <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" value={tempFooter.email} onChange={e => setTempFooter({...tempFooter, email: e.target.value})} />
                    </div>
                 </div>
              </div>
            </div>

            <div className="pt-8 border-t dark:border-slate-700 flex justify-end">
              <button 
                onClick={handleSaveFooter}
                className="bg-green-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl hover:bg-green-700 transition-all"
              >
                Apply Footer Changes
              </button>
            </div>
          </div>
        </div>
      )}

      {/* --- MODALS (Rest of implementation remains unchanged) --- */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-3xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40">
              <div>
                <h2 className="text-3xl font-black">Entry Marks</h2>
                <p className="text-slate-400 font-bold text-sm uppercase mt-1 tracking-widest">{enteringMarksFor.name} | {enteringMarksFor.subject}</p>
              </div>
              <button onClick={() => setEnteringMarksFor(null)} className="w-12 h-12 bg-white dark:bg-slate-800 shadow-md rounded-2xl flex items-center justify-center hover:bg-red-50 hover:text-red-500 transition-all">✕</button>
            </div>
            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px] hover:shadow-md transition-all">
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-xl bg-white dark:bg-slate-800 flex items-center justify-center text-xs font-black shadow-sm">{s.name.charAt(0)}</div>
                    <span className="font-bold text-lg">{s.name}</span>
                  </div>
                  <div className="flex items-center space-x-3">
                    <input 
                      type="number" 
                      min="0" max="100"
                      className="w-24 p-4 rounded-2xl border dark:bg-slate-800 outline-none text-center font-black text-blue-600 focus:ring-2 ring-blue-500"
                      value={enteringMarksFor.marks[s.id] || ''}
                      onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))}
                    />
                    <span className="text-slate-400 font-bold">/ 100</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700 bg-white dark:bg-slate-800">
              <button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-2xl hover:bg-blue-700 transition-all">Save Marks Hub</button>
            </div>
          </div>
        </div>
      )}

      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
            <div className="flex-1 p-12 space-y-10 overflow-y-auto">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-4xl font-black tracking-tight">{viewingStudent.name}</h2>
                  <div className="flex items-center space-x-2 mt-2">
                    <span className="text-xs font-bold px-3 py-1 bg-blue-50 text-blue-600 rounded-full">{viewingStudent.class}</span>
                  </div>
                </div>
                <button onClick={() => setViewingStudent(null)} className="w-12 h-12 rounded-3xl bg-slate-100 flex items-center justify-center hover:bg-slate-200 transition-all">✕</button>
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div className="space-y-1">
                   <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Email Address</p>
                   <p className="text-lg font-bold">{viewingStudent.email}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Phone Number</p>
                   <p className="text-lg font-bold">{viewingStudent.phone}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-[32px] border dark:border-slate-800">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2">Attendance</p>
                  <p className="text-4xl font-black text-orange-500">{viewingStudent.attendance}%</p>
                </div>
                <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-[32px] border dark:border-slate-800 col-span-2 md:col-span-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2">Avg. Exam</p>
                  <p className="text-4xl font-black text-blue-600">{viewingStudent.averageScore}%</p>
                </div>
              </div>

              <div className="space-y-6">
                <h4 className="font-black text-sm uppercase tracking-widest text-slate-400">Academic History</h4>
                <div className="space-y-4">
                  {exams.filter(e => e.marks[viewingStudent.id] !== undefined).map(e => (
                    <div key={e.id} className="p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px] flex justify-between items-center">
                      <div>
                        <p className="font-bold">{e.name}</p>
                        <p className="text-[10px] font-bold text-slate-400">{e.subject} • {e.date}</p>
                      </div>
                      <div className="text-2xl font-black text-blue-600">{e.marks[viewingStudent.id]}<span className="text-sm font-bold text-slate-400">/100</span></div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Radar, RadarChart, PolarGrid, PolarAngleAxis } from 'recharts';

const growthData = [
  { name: 'Jan', students: 400 },
  { name: 'Feb', students: 520 },
  { name: 'Mar', students: 680 },
  { name: 'Apr', students: 750 },
  { name: 'May', students: 900 },
  { name: 'Jun', students: 850 },
];

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [attendanceToday, setAttendanceToday] = useState<Record<string, boolean>>({});
  const [lastMarkedId, setLastMarkedId] = useState<string | null>(null);

  // Admin Profile State
  const [editAdmin, setEditAdmin] = useState<AdminUser>({ ...adminProfile });

  // Footer Edit State
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });

  // Form States
  const [newStudent, setNewStudent] = useState({ name: '', email: '', phone: '', class: 'HSC 1st Year' as any });
  const [courseForm, setCourseForm] = useState({ name: '', icon: '📚', classesPerWeek: 3 });
  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ name: '', subject: subjects[0]?.name || '', date: new Date().toISOString().split('T')[0] });

  // Ref for file inputs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingCourse) setCourseForm({ name: editingCourse.name, icon: editingCourse.icon, classesPerWeek: editingCourse.classesPerWeek });
    else setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
  }, [editingCourse]);

  useEffect(() => {
    if (editingTeacher) setTeacherForm({ name: editingTeacher.name, subject: editingTeacher.subject, qualification: editingTeacher.qualification, experience: editingTeacher.experience, image: editingTeacher.image });
    else setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
  }, [editingTeacher]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        callback(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateAdminProfile = (e: React.FormEvent) => { 
    e.preventDefault(); 
    setAdminProfile(editAdmin); 
    alert("Admin Profile Updated!"); 
  };

  const handleSaveFooter = () => {
    setFooterData(tempFooter);
    alert("Footer configuration saved successfully!");
  };

  const verifyStudent = (id: string) => { 
    setStudents(prev => prev.map(s => s.id === id ? { ...s, isVerified: true } : s)); 
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.name || !newStudent.email) return;
    const studentToAdd: Student = {
      id: `s${Date.now()}`,
      name: newStudent.name,
      email: newStudent.email,
      phone: newStudent.phone,
      class: newStudent.class,
      attendance: 100,
      averageScore: 0,
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: true
    };
    setStudents([studentToAdd, ...students]);
    setIsAddModalOpen(false);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams([...exams, newExam]);
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => {
      if (exam.id === examId) {
        return { ...exam, marks: { ...exam.marks, [studentId]: mark } };
      }
      return exam;
    }));
  };

  const toggleAttendance = (id: string) => {
    const isCurrentlyPresent = attendanceToday[id];
    setLastMarkedId(id);
    setTimeout(() => setLastMarkedId(null), 1000);
    setAttendanceToday(prev => ({ ...prev, [id]: !isCurrentlyPresent }));
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        const newAttendance = !isCurrentlyPresent ? Math.min(100, s.attendance + 0.5) : Math.max(0, s.attendance - 0.5);
        return { ...s, attendance: parseFloat(newAttendance.toFixed(1)) };
      }
      return s;
    }));
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCourse) setSubjects(subjects.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
    else setSubjects([...subjects, { id: `sub-${Date.now()}`, ...courseForm }]);
    setIsCourseModalOpen(false);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    else setTeachers([...teachers, { id: `t-${Date.now()}`, ...teacherForm }]);
    setIsTeacherModalOpen(false);
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);

  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
            <button 
              onClick={() => adminAvatarRef.current?.click()}
              className="absolute inset-0 bg-black/40 text-white rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center text-[10px] font-bold"
            >
              Update
            </button>
            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">System Administrator</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-6 py-2 bg-slate-200 dark:bg-slate-800 rounded-2xl font-bold text-sm hover:bg-slate-300">Logout</button>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {[
          { id: 'overview', label: 'Overview' },
          { id: 'students', label: 'Students' },
          { id: 'teachers', label: 'Teachers' },
          { id: 'exams', label: 'Exams' },
          { id: 'pending', label: `Requests (${pendingStudents.length})` },
          { id: 'attendance', label: 'Attendance' },
          { id: 'settings', label: 'Site Config' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`pb-4 px-2 text-sm font-bold whitespace-nowrap transition-all border-b-2 ${activeTab === tab.id ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-700'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Enrolled Students</p>
             <p className="text-5xl font-black text-blue-600">{verifiedStudents.length}</p>
          </div>
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Exams Created</p>
             <p className="text-5xl font-black text-orange-500">{exams.length}</p>
          </div>
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Faculty Members</p>
             <p className="text-5xl font-black text-purple-600">{teachers.length}</p>
          </div>
          <div className="p-8 bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Growth Rate</p>
             <p className="text-5xl font-black text-green-500">+12%</p>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b dark:border-slate-700 flex justify-between items-center">
             <h3 className="font-bold">Student Directory</h3>
             <button onClick={() => setIsAddModalOpen(true)} className="text-sm font-bold text-blue-600 hover:underline">+ Register Student</button>
          </div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 rounded-2xl bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-blue-600 font-bold">{student.name.charAt(0)}</div>
                      <div>
                        <p className="font-bold">{student.name}</p>
                        <p className="text-xs text-slate-400">{student.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-xs font-medium text-slate-500">{student.class}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => setViewingStudent(student)} className="bg-slate-100 dark:bg-slate-700 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all">View Details</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="space-y-12 pb-20">
           {/* Logo Upload Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-10">
            <div className="flex flex-col md:flex-row justify-between md:items-center gap-6">
              <h3 className="text-3xl font-black">Branding & Logo</h3>
              <button 
                onClick={() => logoUploadRef.current?.click()}
                className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-lg"
              >
                Upload Device Logo
              </button>
              <input type="file" hidden ref={logoUploadRef} accept="image/*" onChange={(e) => handleFileUpload(e, setLogo)} />
            </div>

            <div className="flex items-center space-x-10 p-6 bg-slate-50 dark:bg-slate-900/50 rounded-[32px]">
               <div className="w-40 h-40 bg-orange-500 rounded-[32px] flex items-center justify-center text-white text-5xl font-black shadow-2xl overflow-hidden border-4 border-white dark:border-slate-700">
                 {isLogoBase64 ? (
                   <img src={logo} className="w-full h-full object-cover" alt="Preview" />
                 ) : (
                   logo
                 )}
               </div>
               <div className="flex-1 space-y-4">
                 <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Logo (Text Fallback)</label>
                 <input 
                   type="text" 
                   maxLength={15} 
                   className="w-full p-4 rounded-2xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-orange-500 font-bold" 
                   value={isLogoBase64 ? "Image Uploaded" : logo} 
                   disabled={isLogoBase64}
                   onChange={e => setLogo(e.target.value)} 
                 />
                 {isLogoBase64 && (
                   <button onClick={() => setLogo('P')} className="text-xs text-red-500 font-bold hover:underline">Remove Image & Use Text</button>
                 )}
                 <p className="text-[11px] text-slate-400 italic">Upload a PNG/JPG for your site logo. If no image is provided, the text fallback will be used.</p>
               </div>
            </div>
          </div>

          {/* Footer Management Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-3xl font-black">Footer Content Management</h3>
            <div className="grid md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Platform Description</label>
                <textarea 
                  className="w-full p-4 rounded-2xl border dark:bg-slate-900 min-h-[120px] outline-none"
                  value={tempFooter.description}
                  onChange={e => setTempFooter({...tempFooter, description: e.target.value})}
                />
              </div>
              <div className="space-y-4">
                 <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Physical Address</label>
                    <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" value={tempFooter.address} onChange={e => setTempFooter({...tempFooter, address: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                       <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Phone</label>
                       <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" value={tempFooter.phone} onChange={e => setTempFooter({...tempFooter, phone: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                       <label className="text-sm font-bold text-slate-400 uppercase tracking-widest">Email</label>
                       <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" value={tempFooter.email} onChange={e => setTempFooter({...tempFooter, email: e.target.value})} />
                    </div>
                 </div>
              </div>
            </div>

            <div className="pt-8 border-t dark:border-slate-700 flex justify-end">
              <button 
                onClick={handleSaveFooter}
                className="bg-green-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl hover:bg-green-700 transition-all"
              >
                Apply Footer Changes
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Marks Entry Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-3xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40">
              <div>
                <h2 className="text-3xl font-black">Entry Marks</h2>
                <p className="text-slate-400 font-bold text-sm uppercase mt-1 tracking-widest">{enteringMarksFor.name} | {enteringMarksFor.subject}</p>
              </div>
              <button onClick={() => setEnteringMarksFor(null)} className="w-12 h-12 bg-white dark:bg-slate-800 shadow-md rounded-2xl flex items-center justify-center hover:bg-red-50 hover:text-red-500 transition-all">✕</button>
            </div>
            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px] hover:shadow-md transition-all">
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-xl bg-white dark:bg-slate-800 flex items-center justify-center text-xs font-black shadow-sm">{s.name.charAt(0)}</div>
                    <span className="font-bold text-lg">{s.name}</span>
                  </div>
                  <div className="flex items-center space-x-3">
                    <input 
                      type="number" 
                      min="0" max="100"
                      className="w-24 p-4 rounded-2xl border dark:bg-slate-800 outline-none text-center font-black text-blue-600 focus:ring-2 ring-blue-500"
                      value={enteringMarksFor.marks[s.id] || ''}
                      onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))}
                    />
                    <span className="text-slate-400 font-bold">/ 100</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700 bg-white dark:bg-slate-800">
              <button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-2xl hover:bg-blue-700 transition-all">Save Marks Hub</button>
            </div>
          </div>
        </div>
      )}

      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
            <div className="flex-1 p-12 space-y-10 overflow-y-auto">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-4xl font-black tracking-tight">{viewingStudent.name}</h2>
                  <div className="flex items-center space-x-2 mt-2">
                    <span className="text-xs font-bold px-3 py-1 bg-blue-50 text-blue-600 rounded-full">{viewingStudent.class}</span>
                  </div>
                </div>
                <button onClick={() => setViewingStudent(null)} className="w-12 h-12 rounded-3xl bg-slate-100 flex items-center justify-center hover:bg-slate-200 transition-all">✕</button>
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div className="space-y-1">
                   <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Email Address</p>
                   <p className="text-lg font-bold">{viewingStudent.email}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Phone Number</p>
                   <p className="text-lg font-bold">{viewingStudent.phone}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-[32px] border dark:border-slate-800">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2">Attendance</p>
                  <p className="text-4xl font-black text-orange-500">{viewingStudent.attendance}%</p>
                </div>
                <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-[32px] border dark:border-slate-800 col-span-2 md:col-span-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2">Avg. Exam</p>
                  <p className="text-4xl font-black text-blue-600">{viewingStudent.averageScore}%</p>
                </div>
              </div>

              <div className="space-y-6">
                <h4 className="font-black text-sm uppercase tracking-widest text-slate-400">Academic History</h4>
                <div className="space-y-4">
                  {exams.filter(e => e.marks[viewingStudent.id] !== undefined).map(e => (
                    <div key={e.id} className="p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px] flex justify-between items-center">
                      <div>
                        <p className="font-bold">{e.name}</p>
                        <p className="text-[10px] font-bold text-slate-400">{e.subject} • {e.date}</p>
                      </div>
                      <div className="text-2xl font-black text-blue-600">{e.marks[viewingStudent.id]}<span className="text-sm font-bold text-slate-400">/100</span></div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Teacher Modal (Add/Edit) */}
      {isTeacherModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8">
            <h2 className="text-3xl font-black">{editingTeacher ? 'Edit Faculty' : 'Add Faculty'}</h2>
            <form onSubmit={handleTeacherSubmit} className="space-y-5">
              <div className="flex flex-col items-center space-y-4">
                 <div className="relative group cursor-pointer" onClick={() => teacherPicRef.current?.click()}>
                   <img src={teacherForm.image || 'https://via.placeholder.com/150'} className="w-24 h-24 rounded-3xl object-cover border-2 border-blue-500 shadow-xl" />
                   <div className="absolute inset-0 bg-black/40 rounded-3xl opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-[10px] font-bold">Upload</div>
                   <input type="file" hidden ref={teacherPicRef} accept="image/*" onChange={(e) => handleFileUpload(e, (b) => setTeacherForm({...teacherForm, image: b}))} />
                 </div>
                 <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Profile Picture</p>
              </div>
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Full Name" value={teacherForm.name} onChange={e => setTeacherForm({...teacherForm, name: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Subject" value={teacherForm.subject} onChange={e => setTeacherForm({...teacherForm, subject: e.target.value})} />
              <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Qualification" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} />
              <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Experience" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-2xl hover:bg-blue-700">{editingTeacher ? 'Update Faculty' : 'Add Faculty'}</button>
              <button type="button" onClick={() => setIsTeacherModalOpen(false)} className="w-full py-2 text-slate-400 font-bold uppercase text-[10px] tracking-widest">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {/* Exam Modal */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8">
            <h2 className="text-3xl font-black">Create New Exam</h2>
            <form onSubmit={handleExamSubmit} className="space-y-5">
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Exam Name" value={examForm.name} onChange={e => setExamForm({...examForm, name: e.target.value})} />
              <select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={examForm.subject} onChange={e => setExamForm({...examForm, subject: e.target.value})}>
                {subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
              </select>
              <input type="date" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={examForm.date} onChange={e => setExamForm({...examForm, date: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-3xl shadow-2xl hover:bg-orange-600">Publish Exam</button>
              <button type="button" onClick={() => setIsExamModalOpen(false)} className="w-full py-2 text-slate-400 font-bold uppercase text-[10px] tracking-widest">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {/* Registration Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8">
            <h2 className="text-3xl font-black">Register Student</h2>
            <form onSubmit={handleAddStudent} className="space-y-4">
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Full Name" value={newStudent.name} onChange={e => setNewStudent({...newStudent, name: e.target.value})} />
              <input required type="email" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Email Address" value={newStudent.email} onChange={e => setNewStudent({...newStudent, email: e.target.value})} />
              <input required type="tel" className="w-full p-4 rounded-2xl border dark:bg-slate-900" placeholder="Phone Number" value={newStudent.phone} onChange={e => setNewStudent({...newStudent, phone: e.target.value})} />
              <select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={newStudent.class} onChange={e => setNewStudent({...newStudent, class: e.target.value})}>
                <option value="HSC 1st Year">HSC 1st Year</option>
                <option value="HSC 2nd Year">HSC 2nd Year</option>
              </select>
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-2xl hover:bg-blue-700">Save Student</button>
              <button type="button" onClick={() => setIsAddModalOpen(false)} className="w-full py-2 text-slate-400 font-bold uppercase text-[10px] tracking-widest">Cancel</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

