            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px]">
                  <span className="font-bold text-lg">{s.name}</span>
                  <input type="number" className="w-24 p-4 rounded-2xl border dark:bg-slate-800 text-center font-black text-blue-600" value={enteringMarksFor.marks[s.id] || ''} onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))} />
                </div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700">
              <button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-xl">Save & Close</button>
            </div>
          </div>
        </div>
      )}

      {/* Existing Student Directory Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl p-12 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-8">
               <h2 className="text-4xl font-black">{viewingStudent.name}</h2>
               <button onClick={() => setViewingStudent(null)} className="p-4 bg-slate-100 rounded-full">✕</button>
            </div>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Contact Info</p>
                  <p className="font-bold">{viewingStudent.email}</p>
                  <p className="font-bold">{viewingStudent.phone}</p>
               </div>
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Class Details</p>
                  <p className="font-bold text-blue-600">{viewingStudent.class}</p>
                  <p className={`font-bold ${viewingStudent.feesPaid ? 'text-green-500' : 'text-red-500'}`}>
                    {viewingStudent.feesPaid ? 'Fees Paid' : 'Payment Pending'}
                  </p>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Radar, RadarChart, PolarGrid, PolarAngleAxis } from 'recharts';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [attendanceToday, setAttendanceToday] = useState<Record<string, boolean>>({});

  // Site Config states
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });

  // Form States
  const [newStudent, setNewStudent] = useState({ name: '', email: '', phone: '', class: 'HSC 1st Year' as any });
  const [courseForm, setCourseForm] = useState({ name: '', icon: '📚', classesPerWeek: 3 });
  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ name: '', subject: subjects[0]?.name || '', date: new Date().toISOString().split('T')[0] });

  // Refs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingCourse) setCourseForm({ name: editingCourse.name, icon: editingCourse.icon, classesPerWeek: editingCourse.classesPerWeek });
    else setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
  }, [editingCourse]);

  useEffect(() => {
    if (editingTeacher) {
      setTeacherForm({ 
        name: editingTeacher.name, 
        subject: editingTeacher.subject, 
        qualification: editingTeacher.qualification, 
        experience: editingTeacher.experience, 
        image: editingTeacher.image 
      });
    } else {
      setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
    }
  }, [editingTeacher]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    alert("Site configuration updated successfully!");
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    const studentToAdd: Student = {
      id: `s${Date.now()}`,
      ...newStudent,
      attendance: 100,
      averageScore: 0,
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: true
    };
    setStudents([studentToAdd, ...students]);
    setIsAddModalOpen(false);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    } else {
      setTeachers([...teachers, { id: `t-${Date.now()}`, ...teacherForm }]);
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams([...exams, newExam]);
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

