  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
            <button 
              onClick={() => adminAvatarRef.current?.click()}
              className="absolute inset-0 bg-black/40 text-white rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center text-[10px] font-bold"
            >
              Update
            </button>
            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">System Administrator</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-6 py-2 bg-slate-200 dark:bg-slate-800 rounded-2xl font-bold text-sm hover:bg-slate-300 transition-colors">Logout</button>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {['overview', 'students', 'teachers', 'exams', 'pending', 'settings'].map(t => (
          <button 
            key={t}
            onClick={() => setActiveTab(t)}
            className={`pb-4 px-2 text-sm font-bold capitalize transition-all border-b-2 ${activeTab === t ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-700'}`}
          >
            {t} {t === 'pending' ? `(${pendingStudents.length})` : ''}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Active Students</p>
             <p className="text-5xl font-black text-blue-600">{verifiedStudents.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Academic Exams</p>
             <p className="text-5xl font-black text-orange-500">{exams.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Faculty Members</p>
             <p className="text-5xl font-black text-purple-600">{teachers.length}</p>
          </div>
        </div>
      )}

      {activeTab === 'teachers' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-2xl font-bold">Faculty Management</h3>
            <button onClick={() => { setEditingTeacher(null); setIsTeacherModalOpen(true); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-lg hover:bg-blue-700 transition-all">+ New Faculty</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {teachers.map(teacher => (
              <div key={teacher.id} className="bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm flex items-center space-x-6 hover:shadow-md transition-shadow">
                <img src={teacher.image || 'https://via.placeholder.com/150'} className="w-20 h-20 rounded-3xl object-cover shadow-md" alt={teacher.name} />
                <div className="flex-grow">
                  <h4 className="font-bold text-lg leading-tight">{teacher.name}</h4>
                  <p className="text-xs font-black text-orange-500 uppercase tracking-widest mt-1">{teacher.subject}</p>
                  <div className="mt-4 flex gap-4">
                    <button onClick={() => { setEditingTeacher(teacher); setIsTeacherModalOpen(true); }} className="text-[10px] font-bold text-blue-600 uppercase hover:underline">Edit</button>
                    <button onClick={() => setTeachers(teachers.filter(t => t.id !== teacher.id))} className="text-[10px] font-bold text-red-500 uppercase hover:underline">Delete</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
          {teachers.length === 0 && (
            <div className="text-center py-20 bg-white dark:bg-slate-800 rounded-[40px] border dark:border-slate-700">
              <p className="text-slate-400 font-medium">No faculty members found. Start by adding a new teacher.</p>
            </div>
          )}
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="space-y-12 pb-20">
          {/* Logo Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-black">Platform Branding</h3>
              <button onClick={() => logoUploadRef.current?.click()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-xs font-bold shadow-lg">Upload Logo</button>
              <input type="file" hidden ref={logoUploadRef} accept="image/*" onChange={(e) => handleFileUpload(e, setLogo)} />
            </div>
            <div className="flex items-center space-x-10 p-8 bg-slate-50 dark:bg-slate-900/50 rounded-[32px]">
               <div className="w-32 h-32 bg-orange-500 rounded-[32px] flex items-center justify-center text-white text-5xl font-black shadow-2xl overflow-hidden">
