                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Experience</label>
                  <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 focus:ring-2 ring-blue-500 outline-none font-medium" placeholder="e.g. 10+ Years" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
                </div>
              </div>

              <button type="submit" className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[24px] shadow-2xl transition-all hover:-translate-y-1 active:scale-95">
                {editingTeacher ? 'Update Profile' : 'Add to Faculty'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Marks Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40">
              <h2 className="text-3xl font-black">Enter Marks</h2>
              <button onClick={() => setEnteringMarksFor(null)} className="p-3 bg-slate-100 rounded-2xl">✕</button>
            </div>
            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px]">
                  <span className="font-bold text-lg">{s.name}</span>
                  <input type="number" className="w-24 p-4 rounded-2xl border dark:bg-slate-800 text-center font-black text-blue-600" value={enteringMarksFor.marks[s.id] || ''} onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))} />
                </div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700">
              <button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-xl">Save & Close</button>
            </div>
          </div>
        </div>
      )}

      {/* Existing Student Directory Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl p-12 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-8">
               <h2 className="text-4xl font-black">{viewingStudent.name}</h2>
               <button onClick={() => setViewingStudent(null)} className="p-4 bg-slate-100 rounded-full">✕</button>
            </div>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Contact Info</p>
                  <p className="font-bold">{viewingStudent.email}</p>
                  <p className="font-bold">{viewingStudent.phone}</p>
               </div>
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-2">Class Details</p>
                  <p className="font-bold text-blue-600">{viewingStudent.class}</p>
                  <p className={`font-bold ${viewingStudent.feesPaid ? 'text-green-500' : 'text-red-500'}`}>
                    {viewingStudent.feesPaid ? 'Fees Paid' : 'Payment Pending'}
                  </p>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Radar, RadarChart, PolarGrid, PolarAngleAxis } from 'recharts';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);

  // Site Config states
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });

  // Form States
  const [newStudent, setNewStudent] = useState({ name: '', email: '', phone: '', class: 'HSC 1st Year' as any });
  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ 
    name: '', 
    subject: subjects[0]?.name || 'Physics', 
    date: new Date().toISOString().split('T')[0] 
  });

  // Refs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingTeacher) {
      setTeacherForm({ 
        name: editingTeacher.name, 
        subject: editingTeacher.subject, 
        qualification: editingTeacher.qualification, 
        experience: editingTeacher.experience, 
        image: editingTeacher.image 
      });
    } else {
      setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
    }
  }, [editingTeacher]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    alert("Site configuration updated successfully!");
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    const studentToAdd: Student = {
      id: `s${Date.now()}`,
      ...newStudent,
      attendance: 100,
      averageScore: 0,
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: true
    };
    setStudents([studentToAdd, ...students]);
    setIsAddModalOpen(false);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    } else {
      setTeachers([...teachers, { id: `t-${Date.now()}`, ...teacherForm }]);
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams([...exams, newExam]);
    setIsExamModalOpen(false);
    setExamForm({ 
      name: '', 
      subject: subjects[0]?.name || 'Physics', 
      date: new Date().toISOString().split('T')[0] 
    });
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);
  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
            <button 
              onClick={() => adminAvatarRef.current?.click()}
              className="absolute inset-0 bg-black/40 text-white rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center text-[10px] font-bold"
            >
              Update
            </button>
            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">System Administrator</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-6 py-2 bg-slate-200 dark:bg-slate-800 rounded-2xl font-bold text-sm hover:bg-slate-300 transition-colors">Logout</button>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {['overview', 'students', 'teachers', 'exams', 'pending', 'settings'].map(t => (
          <button 
            key={t}
            onClick={() => setActiveTab(t)}
            className={`pb-4 px-2 text-sm font-bold capitalize transition-all border-b-2 ${activeTab === t ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-700'}`}
          >
            {t} {t === 'pending' ? `(${pendingStudents.length})` : ''}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Active Students</p>
             <p className="text-5xl font-black text-blue-600">{verifiedStudents.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Academic Exams</p>
             <p className="text-5xl font-black text-orange-500">{exams.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Faculty Members</p>
             <p className="text-5xl font-black text-purple-600">{teachers.length}</p>
          </div>
        </div>
      )}

      {activeTab === 'teachers' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-2xl font-bold">Faculty Management</h3>
            <button onClick={() => { setEditingTeacher(null); setIsTeacherModalOpen(true); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-lg hover:bg-blue-700 transition-all">+ New Faculty</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {teachers.map(teacher => (
              <div key={teacher.id} className="bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm flex items-center space-x-6 hover:shadow-md transition-shadow">
                <img src={teacher.image || 'https://via.placeholder.com/150'} className="w-20 h-20 rounded-3xl object-cover shadow-md" alt={teacher.name} />
                <div className="flex-grow">
                  <h4 className="font-bold text-lg leading-tight">{teacher.name}</h4>
                  <p className="text-xs font-black text-orange-500 uppercase tracking-widest mt-1">{teacher.subject}</p>
                  <div className="mt-4 flex gap-4">
                    <button onClick={() => { setEditingTeacher(teacher); setIsTeacherModalOpen(true); }} className="text-[10px] font-bold text-blue-600 uppercase hover:underline">Edit</button>
                    <button onClick={() => setTeachers(teachers.filter(t => t.id !== teacher.id))} className="text-[10px] font-bold text-red-500 uppercase hover:underline">Delete</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'exams' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-2xl font-bold">Exam Hub</h3>
            <button 
              onClick={() => setIsExamModalOpen(true)} 
              className="bg-orange-500 text-white px-8 py-3 rounded-2xl text-sm font-bold shadow-xl transition-all hover:bg-orange-600 hover:-translate-y-1"
            >
              + Create New Exam
            </button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {exams.map(exam => (
              <div key={exam.id} className="bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm space-y-4 hover:shadow-lg transition-all">
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-bold text-xl">{exam.name}</h4>
                    <span className="text-xs font-black text-blue-500 uppercase tracking-widest">{exam.subject}</span>
                  </div>
                  <span className="text-xs font-bold text-slate-400">{exam.date}</span>
                </div>
                <div className="pt-4 border-t dark:border-slate-700 flex justify-between items-center">
                  <span className="text-[10px] font-bold text-slate-500 uppercase">{Object.keys(exam.marks).length} Marks Entered</span>
                  <button 
                    onClick={() => setEnteringMarksFor(exam)}
                    className="bg-slate-100 dark:bg-slate-900 px-4 py-2 rounded-xl text-xs font-bold hover:bg-orange-500 hover:text-white transition-all"
                  >
                    Enter Marks
                  </button>
                </div>
              </div>
            ))}
          </div>
          {exams.length === 0 && (
            <div className="text-center py-20 bg-white dark:bg-slate-800 rounded-[40px] border dark:border-slate-700">
              <p className="text-slate-400 font-medium">No exams scheduled yet. Click the button above to add one.</p>
            </div>
          )}
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="space-y-12 pb-20">
          {/* Logo Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-black">Platform Branding</h3>
              <button onClick={() => logoUploadRef.current?.click()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-xs font-bold shadow-lg">Upload Logo</button>
              <input type="file" hidden ref={logoUploadRef} accept="image/*" onChange={(e) => handleFileUpload(e, setLogo)} />
            </div>
            <div className="flex items-center space-x-10 p-8 bg-slate-50 dark:bg-slate-900/50 rounded-[32px]">
               <div className="w-32 h-32 bg-orange-500 rounded-[32px] flex items-center justify-center text-white text-5xl font-black shadow-2xl overflow-hidden">
                 {isLogoBase64 ? <img src={logo} className="w-full h-full object-cover" /> : logo}
               </div>
               <div className="flex-1 space-y-4">
                 <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Fallback Text</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={isLogoBase64 ? "Image Uploaded" : logo} disabled={isLogoBase64} onChange={e => setLogo(e.target.value)} />
                 {isLogoBase64 && <button onClick={() => setLogo('P')} className="text-xs text-red-500 font-bold">Remove Image</button>}
               </div>
            </div>
          </div>

          {/* Home Page Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-2xl font-black">Home Page Content</h3>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="space-y-2 md:col-span-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Hero Main Title</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.heroTitle} onChange={e => setTempHome({...tempHome, heroTitle: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Enroll Button Text</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.heroEnrollText} onChange={e => setTempHome({...tempHome, heroEnrollText: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Explore Button Text</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.heroExploreText} onChange={e => setTempHome({...tempHome, heroExploreText: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Stat: Years Experience</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.statExperience} onChange={e => setTempHome({...tempHome, statExperience: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Stat: Total Students</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.statStudents} onChange={e => setTempHome({...tempHome, statStudents: e.target.value})} />
               </div>
            </div>
          </div>

          {/* Footer Section */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-2xl font-black">Footer Details</h3>
            <div className="space-y-6">
              <textarea className="w-full p-4 rounded-2xl border dark:bg-slate-900 min-h-[100px]" value={tempFooter.description} onChange={e => setTempFooter({...tempFooter, description: e.target.value})} />
              <div className="grid md:grid-cols-2 gap-4">
                <input type="text" className="p-4 rounded-2xl border dark:bg-slate-900" placeholder="Address" value={tempFooter.address} onChange={e => setTempFooter({...tempFooter, address: e.target.value})} />
                <input type="text" className="p-4 rounded-2xl border dark:bg-slate-900" placeholder="Phone" value={tempFooter.phone} onChange={e => setTempFooter({...tempFooter, phone: e.target.value})} />
              </div>
            </div>
            <div className="pt-6 border-t dark:border-slate-700 flex justify-end">
              <button onClick={handleSaveSiteConfig} className="bg-green-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl hover:bg-green-700">Apply All Site Changes</button>
            </div>
          </div>
        </div>
      )}

      {/* Exam Modal */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8 animate-in fade-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h2 className="text-3xl font-black">Schedule Exam</h2>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-400 hover:text-red-500 font-bold transition-colors">✕</button>
            </div>

            <form onSubmit={handleExamSubmit} className="space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Exam Title</label>
                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-medium outline-none focus:ring-2 ring-orange-500" placeholder="e.g. Monthly Term Test" value={examForm.name} onChange={e => setExamForm({...examForm, name: e.target.value})} />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Select Subject</label>
                <select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.subject} onChange={e => setExamForm({...examForm, subject: e.target.value})}>
                  {subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Exam Date</label>
                <input required type="date" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.date} onChange={e => setExamForm({...examForm, date: e.target.value})} />
              </div>

              <button type="submit" className="w-full py-5 bg-orange-500 hover:bg-orange-600 text-white font-black rounded-[24px] shadow-2xl transition-all hover:-translate-y-1">
                Publish Exam
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Teacher Modal (Add/Edit) */}
      {isTeacherModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8">
            <div className="flex justify-between items-center">
              <h2 className="text-3xl font-black">{editingTeacher ? 'Edit Teacher' : 'Add Teacher'}</h2>
              <button onClick={() => setIsTeacherModalOpen(false)} className="text-slate-400 hover:text-red-500 font-bold transition-colors">✕</button>
            </div>

            <form onSubmit={handleTeacherSubmit} className="space-y-6">
              <div className="flex flex-col items-center space-y-4">
                 <div className="relative group cursor-pointer" onClick={() => teacherPicRef.current?.click()}>
                   <div className="w-32 h-32 rounded-[32px] overflow-hidden border-4 border-blue-500 shadow-2xl bg-slate-100 dark:bg-slate-900 flex items-center justify-center">
                     {teacherForm.image ? (
                       <img src={teacherForm.image} className="w-full h-full object-cover" alt="Teacher Preview" />
                     ) : (
                       <span className="text-4xl text-slate-300 font-black">?</span>
                     )}
                   </div>
                   <input type="file" hidden ref={teacherPicRef} accept="image/*" onChange={(e) => handleFileUpload(e, (b) => setTeacherForm({...teacherForm, image: b}))} />
                 </div>
              </div>

              <div className="space-y-4">
                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Full Name" value={teacherForm.name} onChange={e => setTeacherForm({...teacherForm, name: e.target.value})} />
                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Subject" value={teacherForm.subject} onChange={e => setTeacherForm({...teacherForm, subject: e.target.value})} />
                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Qualification" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} />
                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Experience" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
              </div>

              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-xl">
                {editingTeacher ? 'Update Profile' : 'Add to Faculty'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Marks Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40">
              <h2 className="text-3xl font-black">Enter Marks</h2>
              <button onClick={() => setEnteringMarksFor(null)} className="p-3 bg-slate-100 rounded-2xl">✕</button>
            </div>
            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px]">
                  <span className="font-bold text-lg">{s.name}</span>
                  <input type="number" className="w-24 p-4 rounded-2xl border dark:bg-slate-800 text-center font-black text-blue-600" value={enteringMarksFor.marks[s.id] || ''} onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))} />
                </div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700">
              <button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-xl">Save & Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

