interface NavbarProps {
  currentPage: string;
  navigate: (p: string) => void;
  role: UserRole;
  onLogout: () => void;
  darkMode: boolean;
  toggleDarkMode: () => void;
  logoImage: string;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, navigate, role, onLogout, darkMode, toggleDarkMode, logoImage }) => {
  const [isOpen, setIsOpen] = useState(false);

  // Dynamically filter links: Hide 'Admission' if the user is already logged in
  const navLinks = [
    { name: 'Home', id: 'home' },
    { name: 'Courses', id: 'courses' },
    { name: 'Teachers', id: 'teachers' },
    ...(role === UserRole.GUEST ? [{ name: 'Admission', id: 'admission' }] : []),
    { name: 'Contact', id: 'contact' },
  ];

  const isActive = (id: string) => currentPage === id;

  const isBase64 = logoImage.startsWith('data:image');

  return (
    <nav className="fixed w-full z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          <div className="flex items-center cursor-pointer" onClick={() => navigate('home')}>
            <div className="w-10 h-10 bg-orange-500 rounded-lg flex items-center justify-center text-white font-bold text-xl mr-2 shadow-lg animate-pulse overflow-hidden">
              {isBase64 ? (
                <img src={logoImage} className="w-full h-full object-cover" alt="Logo" />
              ) : (
                logoImage.length > 2 ? <span className="text-xs truncate">{logoImage}</span> : logoImage
              )}
            </div>
            <span className="text-xl font-bold bg-gradient-to-r from-blue-700 to-orange-500 bg-clip-text text-transparent">
              Phoenix Edu Care
            </span>
          </div>

          <div className="hidden md:flex items-center space-x-8">
            {navLinks.map(link => (
              <button
                key={link.id}
                onClick={() => navigate(link.id)}
                className={`text-sm font-medium transition-colors ${isActive(link.id) ? 'text-orange-500 underline decoration-2 underline-offset-4' : 'hover:text-orange-500'}`}
              >
                {link.name}
              </button>
            ))}

            <button onClick={toggleDarkMode} className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800">
              {darkMode ? '🌞' : '🌙'}
            </button>

            {role === UserRole.GUEST ? (
              <button 
                onClick={() => navigate('login')}
                className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-full text-sm font-semibold transition-all shadow-md hover:shadow-lg"
              >
                Login
              </button>
            ) : (
              <div className="flex items-center space-x-4">
                <button 
                  onClick={() => navigate(role === UserRole.ADMIN ? 'admin-dashboard' : 'student-dashboard')}
                  className="text-sm font-bold text-blue-600 dark:text-blue-400"
                >
                  Dashboard
                </button>
                <button 
                  onClick={onLogout}
                  className="bg-slate-200 dark:bg-slate-800 px-4 py-2 rounded-full text-sm font-bold"
                >
                  Logout
                </button>
              </div>
            )}
          </div>

          <div className="md:hidden flex items-center space-x-4">
            <button onClick={toggleDarkMode}>{darkMode ? '🌞' : '🌙'}</button>
            <button onClick={() => setIsOpen(!isOpen)} className="text-2xl">☰</button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white dark:bg-slate-900 border-t dark:border-slate-800 p-4 space-y-4 shadow-xl">
          {navLinks.map(link => (
            <button
              key={link.id}
              onClick={() => { navigate(link.id); setIsOpen(false); }}
              className="block w-full text-left py-2 font-medium"
            >
              {link.name}
            </button>
          ))}
          {role === UserRole.GUEST ? (
            <button onClick={() => navigate('login')} className="block w-full text-left py-2 text-blue-600 font-bold">Login</button>
          ) : (
            <button onClick={onLogout} className="block w-full text-left py-2 text-red-500 font-bold">Logout</button>
          )}
        </div>
      )}
    </nav>
  );
};

