            <div className="p-10 border-t dark:border-slate-700">
              <button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-xl">Save & Close</button>
            </div>
          </div>
        </div>
      )}

      {/* Student View Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl p-12 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-8">
               <h2 className="text-4xl font-black">{viewingStudent.name}</h2>
               <button onClick={() => setViewingStudent(null)} className="p-4 bg-slate-100 rounded-full font-bold">✕</button>
            </div>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Contact Information</p>
                  <p className="font-bold text-lg">{viewingStudent.email}</p>
                  <p className="font-bold text-lg">{viewingStudent.phone}</p>
               </div>
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Enrollment Details</p>
                  <p className="font-bold text-blue-600 text-lg">{viewingStudent.class}</p>
                  <p className={`font-bold text-lg ${viewingStudent.feesPaid ? 'text-green-500' : 'text-red-500'}`}>
                    {viewingStudent.feesPaid ? 'Fees Paid' : 'Payment Pending'}
                  </p>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

