                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Qualification" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} />
                <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Experience" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
