import React, { useState, useEffect } from 'react';
import { Student, PerformanceInsight, Exam } from '../types';
import { getPerformanceInsight } from '../services/geminiService';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';

interface Props {
  student: Student;
  exams: Exam[];
  onLogout: () => void;
}

const StudentDashboard: React.FC<Props> = ({ student, exams, onLogout }) => {
  const [insight, setInsight] = useState<PerformanceInsight | null>(null);
  const [loading, setLoading] = useState(true);

  // Filter exams for this student
  const studentResults = exams.map(exam => ({
    name: exam.name,
    subject: exam.subject,
    score: exam.marks[student.id],
    date: exam.date
  }));

  useEffect(() => {
    const fetchInsight = async () => {
      const data = await getPerformanceInsight(student.attendance, student.averageScore, student.assignments);
      setInsight(data);
      setLoading(false);
    };
    fetchInsight();
  }, [student]);

  const statsData = [
    { subject: 'Attendance', value: student.attendance, full: 100 },
    { subject: 'Exam Score', value: student.averageScore, full: 100 },
    { subject: 'Assignments', value: student.assignments, full: 100 },
  ];

  // Get last 7 days of attendance or whatever is available
  const sortedAttendanceDates = Object.keys(student.dailyAttendance || {}).sort().reverse().slice(0, 10);

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold">Welcome, {student.name}</h1>
          <p className="text-slate-500">Class: {student.class}</p>
        </div>
        <div className={`px-4 py-2 rounded-lg font-bold shadow-sm ${student.feesPaid ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
          Fee Status: {student.feesPaid ? 'Paid' : 'Payment Due'}
        </div>
      </header>

      {/* Heatmap Section */}
      <section className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl p-8 border border-slate-100 dark:border-slate-700">
        <div className="flex flex-col md:flex-row gap-8 items-center">
          <div className="flex-1 w-full text-center md:text-left space-y-4">
            <h2 className="text-2xl font-bold flex items-center justify-center md:justify-start">
              🔥 Performance Heatmap
            </h2>
            <div className="flex items-center space-x-4 justify-center md:justify-start">
              <div className="w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg" style={{ backgroundColor: insight?.color || '#ccc' }}>
                {loading ? '...' : (insight?.status === 'Excellent' ? '🌟' : '💡')}
              </div>
              <div>
                <p className="text-sm font-bold uppercase text-slate-400">Analysis Status</p>
                <p className="text-xl font-extrabold" style={{ color: insight?.color }}>
                  {loading ? 'Analyzing...' : insight?.status}
                </p>
              </div>
            </div>
            <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl italic text-slate-600 dark:text-slate-400 border-l-4 border-orange-500">
              "{loading ? 'Summoning AI mentor insights...' : insight?.message}"
            </div>
          </div>

          <div className="w-full md:w-1/3 h-[250px]">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={statsData}>
                <PolarGrid stroke="#e2e8f0" />
                <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12 }} />
                <Radar name="Student" dataKey="value" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.6} />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </section>

      {/* Attendance Log Section */}
      <section className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
          <h3 className="text-xl font-bold">Attendance Tracking</h3>
          <div className="flex items-center space-x-4">
             <div className="text-right">
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Attendance</p>
               <p className="text-2xl font-black text-blue-600">{student.attendance}%</p>
             </div>
             <div className="w-32 h-3 bg-slate-100 dark:bg-slate-900 rounded-full overflow-hidden border dark:border-slate-700">
               <div className="h-full bg-blue-500" style={{ width: `${student.attendance}%` }}></div>
             </div>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-5 md:grid-cols-10 gap-3">
          {sortedAttendanceDates.length > 0 ? sortedAttendanceDates.map(date => (
            <div key={date} className="flex flex-col items-center space-y-2 p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50 border dark:border-slate-700">
              <span className="text-[10px] font-bold text-slate-500">{date.split('-').slice(1).join('/')}</span>
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${student.dailyAttendance?.[date] ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                {student.dailyAttendance?.[date] ? 'P' : 'A'}
              </div>
            </div>
          )) : (
            <div className="col-span-full py-4 text-center text-slate-400 font-medium italic">No attendance marked yet.</div>
          )}
        </div>
      </section>

      {/* Main Grid */}
      <div className="grid md:grid-cols-3 gap-8">
        <div className="md:col-span-2 space-y-8">
           {/* Recent Results Table */}
           <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
             <h3 className="text-xl font-bold mb-6">Academic Results</h3>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                 <thead className="text-xs font-bold text-slate-400 uppercase">
                   <tr>
                     <th className="pb-4">Exam Name</th>
                     <th className="pb-4">Subject</th>
                     <th className="pb-4">Date</th>
                     <th className="pb-4 text-right">Marks</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y dark:divide-slate-700">
                   {studentResults.length > 0 ? studentResults.map((res, i) => (
                     <tr key={i} className="group hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                       <td className="py-4 font-medium">{res.name}</td>
                       <td className="py-4 text-slate-500">{res.subject}</td>
                       <td className="py-4 text-slate-500 text-sm">{res.date}</td>
                       <td className="py-4 text-right">
                         {res.score !== undefined ? (
                           <span className="font-bold text-blue-600">{res.score}/100</span>
                         ) : (
                           <span className="text-xs font-bold text-slate-400 uppercase italic">Result Pending</span>
                         )}
                       </td>
                     </tr>
                   )) : (
                     <tr><td colSpan={4} className="py-8 text-center text-slate-400">No exams scheduled yet.</td></tr>
                   )}
                 </tbody>
               </table>
             </div>
           </div>
        </div>

        <div className="space-y-8">
           <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
             <h3 className="text-xl font-bold mb-4">Class Routine</h3>
             <div className="space-y-3">
               {['Monday: Physics', 'Tuesday: Math', 'Wednesday: Bio'].map((day, i) => (
                 <div key={i} className="p-3 bg-slate-50 dark:bg-slate-900 rounded-xl text-sm flex justify-between">
                   <span>{day.split(':')[0]}</span>
                   <span className="font-bold text-blue-500">{day.split(':')[1]}</span>
                 </div>
               ))}
             </div>
           </div>

           <div className="bg-orange-500 p-6 rounded-3xl shadow-lg text-white space-y-4">
             <h3 className="text-xl font-bold">Study Materials</h3>
             <p className="text-sm opacity-90">Access lecture notes and PDFs.</p>
             <button className="w-full py-3 bg-white text-orange-600 font-bold rounded-xl shadow-md">
               Download Hub
             </button>
           </div>
        </div>
      </div>
    </div>
  );
};

