            <div className="grid md:grid-cols-2 gap-8">
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-6">
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Basic Info</p>
                    <p className="font-bold text-lg">Class: {viewingStudent.class}</p>
                    <p className="font-bold text-lg">DOB: {viewingStudent.dob || 'Not Provided'}</p>
                    <p className="font-bold text-lg">Address: {viewingStudent.address || 'Not Provided'}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Contact</p>
                    <p className="font-bold text-lg">Email: {viewingStudent.email}</p>
                    <p className="font-bold text-lg">Own Phone: {viewingStudent.ownPhone || viewingStudent.phone}</p>
                    <p className="font-bold text-lg">Guardian Phone: {viewingStudent.guardianPhone || viewingStudent.phone}</p>
                  </div>
               </div>
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-6">
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Academic Record (SSC)</p>
                    <p className="font-bold text-lg">SSC Roll: {viewingStudent.sscRoll || 'N/A'}</p>
                    <p className="font-bold text-lg">SSC Reg: {viewingStudent.sscReg || 'N/A'}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Platform Status</p>
                    <p className={`font-bold text-lg ${viewingStudent.isVerified ? 'text-blue-500' : 'text-orange-500'}`}>
                      {viewingStudent.isVerified ? 'Verified' : 'Pending Verification'}
                    </p>
                    <p className={`font-bold text-lg ${viewingStudent.feesPaid ? 'text-green-500' : 'text-red-500'}`}>
                      {viewingStudent.feesPaid ? 'Fees Paid' : 'Payment Pending'}
                    </p>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { UserRole } from '../types';

interface LoginProps {
  onLogin: (role: UserRole, email: string, password?: string) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole>(UserRole.STUDENT);
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onLogin(selectedRole, identifier, password);
  };

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4">
      <div className="w-full max-w-md space-y-8 bg-white dark:bg-slate-800 p-10 rounded-3xl shadow-2xl border border-slate-100 dark:border-slate-700">
        <div className="text-center">
          <h2 className="text-3xl font-bold tracking-tight">Welcome Back</h2>
          <p className="text-slate-500 mt-2">Access your secure Phoenix Edu Care dashboard</p>
        </div>

        <div className="flex bg-slate-100 dark:bg-slate-900 p-1.5 rounded-2xl">
          <button 
            type="button"
            onClick={() => setSelectedRole(UserRole.STUDENT)}
            className={`flex-1 py-2.5 text-sm font-bold rounded-xl transition-all ${selectedRole === UserRole.STUDENT ? 'bg-white dark:bg-slate-800 shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
          >
            Student
          </button>
          <button 
            type="button"
            onClick={() => setSelectedRole(UserRole.ADMIN)}
            className={`flex-1 py-2.5 text-sm font-bold rounded-xl transition-all ${selectedRole === UserRole.ADMIN ? 'bg-white dark:bg-slate-800 shadow-md text-orange-600' : 'text-slate-500 hover:text-slate-700'}`}
          >
            Admin
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold ml-1">
              {selectedRole === UserRole.STUDENT ? "Email or Mobile Number" : "Admin Email"}
            </label>
            <input 
              required
              type="text" 
              value={identifier}
              onChange={(e) => setIdentifier(e.target.value)}
              className="w-full p-4 rounded-2xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-blue-500 transition-all"
              placeholder={selectedRole === UserRole.STUDENT ? "e.g. 01700000000 or email" : "admin@phoenix.com"}
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold ml-1">Password</label>
            <input 
              required
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-4 rounded-2xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none focus:ring-2 ring-blue-500 transition-all"
              placeholder="••••••••"
            />
          </div>
          <button 
            type="submit" 
            className={`w-full py-4 text-white font-black rounded-2xl shadow-xl transition-all hover:-translate-y-1 active:scale-95 ${selectedRole === UserRole.STUDENT ? 'bg-blue-600 hover:bg-blue-700' : 'bg-orange-600 hover:bg-orange-700'}`}
          >
            Login as {selectedRole === UserRole.STUDENT ? 'Student' : 'Admin'}
          </button>
        </form>

        <div className="text-center pt-4">
