              <div className="space-y-1"><label className="text-xs font-bold">Full Name</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.name} onChange={e => setStudentForm({...studentForm, name: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">SSC Roll</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.sscRoll} onChange={e => setStudentForm({...studentForm, sscRoll: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">SSC Reg</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.sscReg} onChange={e => setStudentForm({...studentForm, sscReg: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Own Phone</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.ownPhone} onChange={e => setStudentForm({...studentForm, ownPhone: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Guardian Phone</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.guardianPhone} onChange={e => setStudentForm({...studentForm, guardianPhone: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Class</label><select className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.class} onChange={e => setStudentForm({...studentForm, class: e.target.value as any})}><option value="HSC 1st Year">HSC 1st Year</option><option value="HSC 2nd Year">HSC 2nd Year</option></select></div>
            </div>
            <div className="space-y-1"><label className="text-xs font-bold">Address</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.address} onChange={e => setStudentForm({...studentForm, address: e.target.value})} /></div>
            <button type="submit" className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl">Update Student Data</button>
          </form>
        </div>
      )}

      {/* Course Modal */}
      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8 animate-in fade-in zoom-in duration-300">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingCourse ? 'Edit Course' : 'Add Course'}</h2><button onClick={() => setIsCourseModalOpen(false)} className="text-slate-400 hover:text-red-500 font-bold">✕</button></div>
            <form onSubmit={handleCourseSubmit} className="space-y-5">
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Course Name</label><input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" value={courseForm.name} onChange={e => setCourseForm({...courseForm, name: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Icon (Emoji)</label><input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" value={courseForm.icon} onChange={e => setCourseForm({...courseForm, icon: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase ml-2">Classes Per Week</label><input required type="number" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" value={courseForm.classesPerWeek} onChange={e => setCourseForm({...courseForm, classesPerWeek: parseInt(e.target.value)})} /></div>
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-2xl">{editingCourse ? 'Update Course' : 'Create Course'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Exam Modal */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Schedule Exam</h2><button onClick={() => setIsExamModalOpen(false)} className="text-slate-400 hover:text-red-500 font-bold">✕</button></div>
            <form onSubmit={handleExamSubmit} className="space-y-5">
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-medium outline-none focus:ring-2 ring-orange-500" placeholder="Exam Title" value={examForm.name} onChange={e => setExamForm({...examForm, name: e.target.value})} />
              <select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.subject} onChange={e => setExamForm({...examForm, subject: e.target.value})}>{subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}</select>
              <input required type="date" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.date} onChange={e => setExamForm({...examForm, date: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-[24px] shadow-2xl">Publish Exam</button>
            </form>
          </div>
        </div>
      )}

      {/* Teacher Modal */}
      {isTeacherModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingTeacher ? 'Edit Teacher' : 'Add Teacher'}</h2><button onClick={() => setIsTeacherModalOpen(false)} className="text-slate-400">✕</button></div>
            <form onSubmit={handleTeacherSubmit} className="space-y-6">
              <div className="flex flex-col items-center space-y-4">
                 <div className="relative group cursor-pointer" onClick={() => teacherPicRef.current?.click()}>
                   <div className="w-32 h-32 rounded-[32px] overflow-hidden border-4 border-blue-500 bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-slate-300 font-black">{teacherForm.image ? <img src={teacherForm.image} className="w-full h-full object-cover" /> : '?'}</div>
                   <input type="file" hidden ref={teacherPicRef} accept="image/*" onChange={(e) => handleFileUpload(e, (b) => setTeacherForm({...teacherForm, image: b}))} />
                 </div>
              </div>
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Full Name" value={teacherForm.name} onChange={e => setTeacherForm({...teacherForm, name: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Subject" value={teacherForm.subject} onChange={e => setTeacherForm({...teacherForm, subject: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Qualification" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Experience" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-xl">{editingTeacher ? 'Update Profile' : 'Add to Faculty'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Marks Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40"><h2 className="text-3xl font-black">Enter Marks</h2><button onClick={() => setEnteringMarksFor(null)} className="p-3 bg-slate-100 rounded-2xl font-bold">✕</button></div>
            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px]"><span className="font-bold text-lg">{s.name}</span><input type="number" className="w-24 p-4 rounded-2xl border dark:bg-slate-800 text-center font-black text-blue-600" value={enteringMarksFor.marks[s.id] || ''} onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))} /></div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700"><button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-xl">Save & Close</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Student, PerformanceInsight, Exam } from '../types';
import { getPerformanceInsight } from '../services/geminiService';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';

interface Props {
  student: Student;
  exams: Exam[];
  onLogout: () => void;
}

const StudentDashboard: React.FC<Props> = ({ student, exams, onLogout }) => {
  const [insight, setInsight] = useState<PerformanceInsight | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<'dashboard' | 'profile'>('dashboard');

  const studentResults = exams.map(exam => ({
    name: exam.name,
    subject: exam.subject,
    score: exam.marks[student.id],
    date: exam.date
  }));

  useEffect(() => {
    const fetchInsight = async () => {
      const data = await getPerformanceInsight(student.attendance, student.averageScore, student.assignments);
      setInsight(data);
      setLoading(false);
    };
    fetchInsight();
  }, [student]);

  const statsData = [
    { subject: 'Attendance', value: student.attendance, full: 100 },
    { subject: 'Exam Score', value: student.averageScore, full: 100 },
    { subject: 'Assignments', value: student.assignments, full: 100 },
  ];

  const sortedAttendanceDates = Object.keys(student.dailyAttendance || {}).sort().reverse().slice(0, 10);

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold">Welcome, {student.name}</h1>
          <p className="text-slate-500">{student.class} • Science</p>
        </div>
        <div className="flex items-center gap-4">
           <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
              <button onClick={() => setActiveView('dashboard')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${activeView === 'dashboard' ? 'bg-white dark:bg-slate-700 shadow-sm text-blue-600' : 'text-slate-500'}`}>Stats</button>
              <button onClick={() => setActiveView('profile')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${activeView === 'profile' ? 'bg-white dark:bg-slate-700 shadow-sm text-blue-600' : 'text-slate-500'}`}>Profile</button>
           </div>
           <div className={`px-4 py-2 rounded-lg font-bold shadow-sm ${student.feesPaid ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
             Fee: {student.feesPaid ? 'Paid' : 'Payment Due'}
           </div>
        </div>
      </header>

      {activeView === 'dashboard' ? (
        <>
          {/* Heatmap Section */}
          <section className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl p-8 border border-slate-100 dark:border-slate-700">
            <div className="flex flex-col md:flex-row gap-8 items-center">
              <div className="flex-1 w-full text-center md:text-left space-y-4">
                <h2 className="text-2xl font-bold flex items-center justify-center md:justify-start">🔥 Performance Insight</h2>
                <div className="flex items-center space-x-4 justify-center md:justify-start">
                  <div className="w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg" style={{ backgroundColor: insight?.color || '#ccc' }}>
                    {loading ? '...' : (insight?.status === 'Excellent' ? '🌟' : '💡')}
                  </div>
                  <div>
                    <p className="text-sm font-bold uppercase text-slate-400">AI Mentor Status</p>
                    <p className="text-xl font-extrabold" style={{ color: insight?.color }}>{loading ? 'Analyzing...' : insight?.status}</p>
                  </div>
                </div>
                <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl italic text-slate-600 dark:text-slate-400 border-l-4 border-orange-500">"{loading ? 'Summoning AI insights...' : insight?.message}"</div>
              </div>
              <div className="w-full md:w-1/3 h-[250px]">
                <ResponsiveContainer width="100%" height="100%">
                  <RadarChart cx="50%" cy="50%" outerRadius="80%" data={statsData}>
                    <PolarGrid stroke="#e2e8f0" />
                    <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12 }} />
                    <Radar name="Student" dataKey="value" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.6} />
                  </RadarChart>
                </ResponsiveContainer>
              </div>
            </div>
          </section>

          {/* Attendance Tracker */}
          <section className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
            <div className="flex justify-between items-center mb-8"><h3 className="text-xl font-bold">Recent Attendance</h3><p className="font-black text-blue-600">{student.attendance}% Rate</p></div>
            <div className="grid grid-cols-2 sm:grid-cols-5 md:grid-cols-10 gap-3">
              {sortedAttendanceDates.map(date => (
                <div key={date} className="flex flex-col items-center p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50">
                  <span className="text-[10px] font-bold text-slate-500">{date.split('-').slice(1).join('/')}</span>
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold mt-2 ${student.dailyAttendance?.[date] ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{student.dailyAttendance?.[date] ? 'P' : 'A'}</div>
                </div>
              ))}
            </div>
          </section>

          {/* Results Grid */}
          <div className="grid md:grid-cols-3 gap-8">
            <div className="md:col-span-2 bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
               <h3 className="text-xl font-bold mb-6">Exam Results</h3>
               <table className="w-full text-left"><tbody className="divide-y dark:divide-slate-700">{studentResults.map((res, i) => (
                 <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors"><td className="py-4 font-bold">{res.name}</td><td className="py-4 text-slate-500">{res.subject}</td><td className="py-4 text-right font-black text-blue-600">{res.score}/100</td></tr>
               ))}</tbody></table>
            </div>
            <div className="bg-orange-500 p-8 rounded-3xl shadow-lg text-white space-y-4">
               <h3 className="text-xl font-bold">Study Resources</h3>
               <p className="text-sm opacity-90">Download latest lecture sheets and PDF notes for HSC Science subjects.</p>
               <button className="w-full py-4 bg-white text-orange-600 font-black rounded-2xl shadow-xl">Go to Library</button>
            </div>
          </div>
        </>
      ) : (
        <section className="bg-white dark:bg-slate-800 p-10 rounded-[40px] shadow-xl border border-slate-100 dark:border-slate-700 space-y-12">
           <div className="grid md:grid-cols-2 gap-12">
              <div className="space-y-6">
                 <h3 className="text-xl font-black text-blue-600 uppercase tracking-widest">Personal Details</h3>
                 <div className="space-y-4 text-lg">
                    <p><b>Full Name:</b> {student.name}</p>
                    <p><b>Date of Birth:</b> {student.dob || 'N/A'}</p>
                    <p><b>Address:</b> {student.address || 'N/A'}</p>
                    <p><b>My Phone:</b> {student.ownPhone || student.phone}</p>
                    <p><b>Guardian Phone:</b> {student.guardianPhone || student.phone}</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <h3 className="text-xl font-black text-orange-500 uppercase tracking-widest">Academic Records</h3>
                 <div className="space-y-4 text-lg p-6 bg-slate-50 dark:bg-slate-900 rounded-3xl">
                    <p><b>HSC Class:</b> {student.class}</p>
                    <p><b>SSC Roll:</b> {student.sscRoll || 'N/A'}</p>
                    <p><b>SSC Reg:</b> {student.sscReg || 'N/A'}</p>
                    <p><b>Portal Email:</b> {student.email}</p>
                 </div>
              </div>
           </div>
           <div className="p-6 bg-blue-50 dark:bg-blue-900/20 rounded-2xl border border-blue-100 dark:border-blue-800">
              <p className="text-sm italic text-blue-800 dark:text-blue-300">If any of the above information is incorrect, please contact the Phoenix Edu Care administrative office for corrections.</p>
           </div>
        </section>
      )}
    </div>
  );
};

export default StudentDashboard;

