import { UserRole, Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from './types';
import { MOCK_STUDENTS, SUBJECT_INFO, TEACHERS } from './constants';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Courses from './pages/Courses';
import TeachersPage from './pages/Teachers';
import Admission from './pages/Admission';
import Contact from './pages/Contact';
import Login from './pages/Login';
import StudentDashboard from './pages/StudentDashboard';
import AdminDashboard from './pages/AdminDashboard';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('home');
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [user, setUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);

  const [logo, setLogo] = useState<string>('P');
  const [adminProfile, setAdminProfile] = useState<AdminUser>({
    name: 'Headmaster Admin',
    email: 'admin@phoenix.com',
    password: 'admin', // Default password
    avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=admin'
  });

  const [footerData, setFooterData] = useState<FooterData>({
    description: 'Igniting Academic Excellence for HSC Science Students in Kulaura since 2015.',
    address: 'Main Road, Kulaura, Moulvibazar',
    phone: '+880 1700-000000',
    email: 'info@phoenix-edu.com',
    quickLinks: [
      { name: 'About Us', url: '#' },
      { name: 'Admissions', url: '#' },
      { name: 'Success Stories', url: '#' },
      { name: 'Resources', url: '#' }
    ],
    supportLinks: [
      { name: 'Contact Support', url: '#' },
      { name: 'Terms & Conditions', url: '#' },
      { name: 'Privacy Policy', url: '#' }
    ]
  });

  const [homeData, setHomeData] = useState<HomeData>({
    heroTitle: 'Igniting Academic Excellence for HSC Science',
    heroEnrollText: 'Enroll Now',
    heroExploreText: 'Explore Courses',
    statExperience: '10+',
    statStudents: '2500+'
  });

  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [teachers, setTeachers] = useState<Teacher[]>(TEACHERS);
  const [exams, setExams] = useState<Exam[]>([
    {
      id: 'e1',
      name: 'Initial Term Test',
      subject: 'Physics',
      date: '2024-03-10',
      marks: { 's1': 82, 's2': 45 }
    }
  ]);

  const [subjects, setSubjects] = useState<Subject[]>(
    Object.entries(SUBJECT_INFO).map(([name, info], idx) => ({
      id: `sub-${idx}`,
      name,
      icon: info.icon,
      classesPerWeek: info.classesPerWeek
    }))
  );

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const navigate = (page: string) => {
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogin = (selectedRole: UserRole, identifier: string, password?: string) => {
    if (selectedRole === UserRole.STUDENT) {
      // Find student by email, own phone, or guardian phone
      const found = students.find(s => 
        (s.email && s.email.toLowerCase() === identifier.toLowerCase()) || 
        (s.ownPhone && s.ownPhone === identifier) || 
        (s.phone && s.phone === identifier) || 
        (s.guardianPhone && s.guardianPhone === identifier)
      );

      if (found) {
        if (!found.isVerified) {
          alert("Your account is pending admin verification. Please try again after approval.");
          return;
        }

        if (password && found.password === password) {
          setRole(selectedRole);
          setUser(found);
          navigate('student-dashboard');
        } else {
          alert("Invalid password. Please try again.");
        }
      } else {
        alert("No student account found with the provided credentials.");
      }
    } else {
      // Admin Login
      if (identifier.toLowerCase() === adminProfile.email.toLowerCase()) {
        if (password === adminProfile.password) {
           setRole(selectedRole);
           setUser(adminProfile);
           navigate('admin-dashboard');
        } else {
          alert("Invalid Admin password.");
        }
      } else {
        alert("Invalid Admin credentials.");
      }
    }
  };

  const handleLogout = () => {
    setRole(UserRole.GUEST);
    setUser(null);
    navigate('home');
  };

  const handleAdmissionSubmit = (newAppData: any) => {
    const newStudent: Student = {
      id: `s-${Date.now()}`,
      name: newAppData.name,
      email: `${newAppData.name.toLowerCase().replace(/\s/g, '')}${Math.floor(Math.random() * 100)}@student.com`,
      phone: newAppData.ownPhone || newAppData.guardianPhone,
      password: newAppData.password,
      class: newAppData.class,
      attendance: 0,
      averageScore: 0,
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: false,
      address: newAppData.address,
      dob: newAppData.dob,
      sscRoll: newAppData.sscRoll,
      sscReg: newAppData.sscReg,
      ownPhone: newAppData.ownPhone,
      guardianPhone: newAppData.guardianPhone,
      dailyAttendance: {}
    };
    setStudents(prev => [newStudent, ...prev]);
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home': return <Home navigate={navigate} homeData={homeData} role={role} />;
      case 'courses': return <Courses subjects={subjects} />;
      case 'teachers': return <TeachersPage teachers={teachers} />;
      case 'admission': return <Admission onSubmit={handleAdmissionSubmit} />;
      case 'contact': return <Contact />;
      case 'login': return <Login onLogin={handleLogin} />;
      case 'student-dashboard': 
        if (!user || role !== UserRole.STUDENT) {
          navigate('login');
          return null;
        }
        return <StudentDashboard student={user} exams={exams} onLogout={handleLogout} />;
      case 'admin-dashboard': 
        if (!user || role !== UserRole.ADMIN) {
          navigate('login');
          return null;
        }
        return (
          <AdminDashboard 
            onLogout={handleLogout} 
            logo={logo} 
            setLogo={setLogo} 
            subjects={subjects} 
            setSubjects={setSubjects}
            students={students}
            setStudents={setStudents}
            teachers={teachers}
            setTeachers={setTeachers}
            exams={exams}
            setExams={setExams}
            adminProfile={adminProfile}
            setAdminProfile={setAdminProfile}
            footerData={footerData}
            setFooterData={setFooterData}
            homeData={homeData}
            setHomeData={setHomeData}
          />
        );
      default: return <Home navigate={navigate} homeData={homeData} role={role} />;
    }
  };

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <Navbar 
        currentPage={currentPage} 
        navigate={navigate} 
        role={role} 
        onLogout={handleLogout}
        darkMode={darkMode}
        toggleDarkMode={() => setDarkMode(!darkMode)}
        logoImage={logo}
      />
      <main className="flex-grow pt-16">
        {renderPage()}
      </main>
      <Footer 
        data={footerData} 
        onAdminClick={() => {
          navigate('login');
        }}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);

  // Attendance State
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
  const [attendanceMap, setAttendanceMap] = useState<Record<string, boolean>>({});

  // Site Config states
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });
  const [tempAdmin, setTempAdmin] = useState<AdminUser>({ ...adminProfile });

  // Form States
  const [courseForm, setCourseForm] = useState({ name: '', icon: '📚', classesPerWeek: 3 });
  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ 
    name: '', 
    subject: subjects[0]?.name || 'Physics', 
    date: new Date().toISOString().split('T')[0] 
  });

  // Student Edit Form State
  const [studentForm, setStudentForm] = useState<Partial<Student>>({});

  // Refs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const newMap: Record<string, boolean> = {};
    students.forEach(s => {
      if (s.dailyAttendance && s.dailyAttendance[attendanceDate] !== undefined) {
        newMap[s.id] = s.dailyAttendance[attendanceDate];
      } else {
        newMap[s.id] = false;
      }
    });
    setAttendanceMap(newMap);
  }, [attendanceDate, students]);

  useEffect(() => {
    if (editingCourse) {
      setCourseForm({ name: editingCourse.name, icon: editingCourse.icon, classesPerWeek: editingCourse.classesPerWeek });
    } else {
      setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
    }
  }, [editingCourse]);

  useEffect(() => {
    if (editingTeacher) {
      setTeacherForm({ name: editingTeacher.name, subject: editingTeacher.subject, qualification: editingTeacher.qualification, experience: editingTeacher.experience, image: editingTeacher.image });
    } else {
      setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
    }
  }, [editingTeacher]);

  useEffect(() => {
    if (editingStudent) {
      setStudentForm(editingStudent);
    }
  }, [editingStudent]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    setAdminProfile(tempAdmin);
    alert("Site and Security configuration updated successfully!");
  };

  const handleStudentUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingStudent) return;
    setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...studentForm } as Student : s));
    setEditingStudent(null);
    alert("Student record updated successfully.");
  };

  const handleVerifyStudent = (studentId: string) => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isVerified: true } : s));
    alert("Student verified and access granted.");
  };

  const toggleAttendance = (studentId: string) => {
    setAttendanceMap(prev => ({ ...prev, [studentId]: !prev[studentId] }));
  };

  const submitAttendance = () => {
    setStudents(prev => prev.map(s => {
      const newDailyAttendance = { ...(s.dailyAttendance || {}), [attendanceDate]: attendanceMap[s.id] };
      const totalDays = Object.keys(newDailyAttendance).length;
      const presentDays = Object.values(newDailyAttendance).filter(val => val === true).length;
      const newPercentage = totalDays > 0 ? (presentDays / totalDays) * 100 : 0;
      return { ...s, dailyAttendance: newDailyAttendance, attendance: parseFloat(newPercentage.toFixed(1)) };
    }));
    alert("Attendance submitted for " + attendanceDate);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    } else {
      setTeachers([...teachers, { id: `t-${Date.now()}`, ...teacherForm }]);
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCourse) {
      setSubjects(subjects.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
    } else {
      setSubjects([...subjects, { id: `sub-${Date.now()}`, ...courseForm }]);
    }
    setIsCourseModalOpen(false);
    setEditingCourse(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams([...exams, newExam]);
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);
  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      {/* Header */}
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
            <button onClick={() => adminAvatarRef.current?.click()} className="absolute inset-0 bg-black/40 text-white rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center text-[10px] font-bold">Update</button>
            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">Administrator</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-6 py-2 bg-slate-200 dark:bg-slate-800 rounded-2xl font-bold text-sm hover:bg-slate-300 transition-colors">Logout</button>
      </header>

      {/* Tabs */}
      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {['overview', 'students', 'teachers', 'courses', 'exams', 'attendance', 'pending', 'settings'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`pb-4 px-2 text-sm font-bold capitalize transition-all border-b-2 ${activeTab === t ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-700'}`}>
            {t} {t === 'pending' ? `(${pendingStudents.length})` : ''}
          </button>
        ))}
      </div>

      {/* Content Sections */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Verified Students</p>
             <p className="text-5xl font-black text-blue-600">{verifiedStudents.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Faculty</p>
             <p className="text-5xl font-black text-purple-600">{teachers.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Active Exams</p>
             <p className="text-5xl font-black text-orange-500">{exams.length}</p>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b dark:border-slate-700 flex justify-between items-center">
             <h3 className="font-bold">Verified Student List</h3>
          </div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 rounded-2xl bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-blue-600 font-bold">{student.name.charAt(0)}</div>
                      <div>
                        <p className="font-bold">{student.name}</p>
                        <p className="text-xs text-slate-400">{student.phone}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-xs font-medium text-slate-500">{student.class}</td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button onClick={() => setViewingStudent(student)} className="bg-slate-100 dark:bg-slate-700 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all">View</button>
                    <button onClick={() => setEditingStudent(student)} className="bg-blue-100 dark:bg-blue-900/30 text-blue-600 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all">Edit</button>
                  </td>
                </tr>
              ))}
              {verifiedStudents.length === 0 && <tr><td colSpan={3} className="p-10 text-center text-slate-400">No verified students found.</td></tr>}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'pending' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl border dark:border-slate-700 shadow-sm overflow-hidden">
          <div className="p-8 border-b dark:border-slate-700"><h3 className="text-xl font-bold">Admission Requests</h3></div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {pendingStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900">
                  <td className="px-8 py-6"><div className="flex items-center space-x-4"><div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center font-bold">{student.name.charAt(0)}</div><div><p className="font-bold">{student.name}</p><p className="text-xs text-slate-400">{student.phone}</p></div></div></td>
                  <td className="px-8 py-6 text-sm font-medium">{student.class}</td>
                  <td className="px-8 py-6 text-right space-x-4">
                    <button onClick={() => setViewingStudent(student)} className="text-xs font-bold text-slate-400 hover:text-blue-600">Details</button>
                    <button onClick={() => handleVerifyStudent(student.id)} className="bg-blue-600 text-white px-6 py-2 rounded-xl text-xs font-bold shadow-md hover:bg-blue-700">Verify</button>
                  </td>
                </tr>
              ))}
              {pendingStudents.length === 0 && <tr><td colSpan={3} className="p-10 text-center text-slate-400">No pending admission requests.</td></tr>}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'attendance' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm">
            <div><h3 className="text-2xl font-bold">Daily Attendance</h3><p className="text-slate-500">Record presence for {attendanceDate}.</p></div>
            <div className="flex items-center gap-4">
              <input type="date" value={attendanceDate} onChange={(e) => setAttendanceDate(e.target.value)} className="p-3 rounded-xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none font-bold" />
              <button onClick={submitAttendance} className="bg-green-600 text-white px-8 py-3 rounded-2xl font-black shadow-lg hover:bg-green-700 transition-all">Submit Records</button>
            </div>
          </div>
          <div className="bg-white dark:bg-slate-800 rounded-[32px] border dark:border-slate-700 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 dark:bg-slate-900/50">
                <tr><th className="px-8 py-4 text-xs font-black text-slate-400 uppercase tracking-widest">Student</th><th className="px-8 py-4 text-xs font-black text-slate-400 uppercase tracking-widest">Status</th><th className="px-8 py-4 text-right text-xs font-black text-slate-400 uppercase tracking-widest">Actions</th></tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-700">
                {verifiedStudents.map(student => (
                  <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                    <td className="px-8 py-5"><p className="font-bold">{student.name}</p></td>
                    <td className="px-8 py-5"><div className="flex items-center gap-2"><div className={`w-3 h-3 rounded-full ${attendanceMap[student.id] ? 'bg-green-500' : 'bg-red-500'}`}></div><span className={`text-xs font-black uppercase ${attendanceMap[student.id] ? 'text-green-500' : 'text-red-500'}`}>{attendanceMap[student.id] ? 'Present' : 'Absent'}</span></div></td>
                    <td className="px-8 py-5 text-right"><button onClick={() => toggleAttendance(student.id)} className={`px-4 py-2 rounded-xl text-xs font-black uppercase transition-all ${attendanceMap[student.id] ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>{attendanceMap[student.id] ? 'Mark Absent' : 'Mark Present'}</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'teachers' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center"><h3 className="text-2xl font-bold">Faculty Management</h3><button onClick={() => { setEditingTeacher(null); setIsTeacherModalOpen(true); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-lg">+ New Teacher</button></div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {teachers.map(t => (
              <div key={t.id} className="bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm flex items-center space-x-6">
                <img src={t.image} className="w-20 h-20 rounded-3xl object-cover" alt={t.name} />
                <div className="flex-grow">
                  <h4 className="font-bold">{t.name}</h4>
                  <p className="text-xs text-orange-500 font-black uppercase">{t.subject}</p>
                  <div className="mt-4 flex gap-4"><button onClick={() => { setEditingTeacher(t); setIsTeacherModalOpen(true); }} className="text-xs text-blue-600 font-bold hover:underline">Edit</button><button onClick={() => setTeachers(teachers.filter(x => x.id !== t.id))} className="text-xs text-red-500 font-bold hover:underline">Delete</button></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'courses' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center"><h3 className="text-2xl font-bold">Course Curriculum</h3><button onClick={() => { setEditingCourse(null); setIsCourseModalOpen(true); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-sm font-bold shadow-lg">+ Add Course</button></div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {subjects.map(s => (
              <div key={s.id} className="bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm flex items-center justify-between">
                <div className="flex items-center space-x-4"><span className="text-3xl">{s.icon}</span><div><h4 className="font-bold">{s.name}</h4><p className="text-xs text-slate-400 font-bold uppercase">{s.classesPerWeek} Classes/Week</p></div></div>
                <div className="flex gap-2"><button onClick={() => { setEditingCourse(s); setIsCourseModalOpen(true); }} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg">✏️</button><button onClick={() => setSubjects(subjects.filter(x => x.id !== s.id))} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button></div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'exams' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center"><h3 className="text-2xl font-bold">Exam Center</h3><button onClick={() => setIsExamModalOpen(true)} className="bg-orange-500 text-white px-8 py-3 rounded-2xl text-sm font-bold shadow-xl hover:bg-orange-600 transition-all">+ Schedule Exam</button></div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {exams.map(e => (
              <div key={e.id} className="bg-white dark:bg-slate-800 p-8 rounded-[32px] border dark:border-slate-700 shadow-sm space-y-4">
                <div className="flex justify-between items-start"><div><h4 className="font-bold text-xl">{e.name}</h4><span className="text-xs font-black text-blue-500 uppercase">{e.subject}</span></div><span className="text-xs font-bold text-slate-400">{e.date}</span></div>
                <div className="pt-4 border-t dark:border-slate-700 flex justify-between items-center"><span className="text-[10px] font-bold text-slate-500 uppercase">{Object.keys(e.marks).length} Marks Entered</span><button onClick={() => setEnteringMarksFor(e)} className="bg-slate-100 dark:bg-slate-900 px-4 py-2 rounded-xl text-xs font-bold hover:bg-orange-500 hover:text-white transition-all">Enter Marks</button></div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="space-y-12 pb-20">
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-2xl font-black">Admin Security & Profile</h3>
            <div className="grid md:grid-cols-2 gap-8">
              <div className="space-y-2"><label className="text-xs font-bold text-slate-400 uppercase">Admin Email</label><input type="email" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempAdmin.email} onChange={e => setTempAdmin({...tempAdmin, email: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-xs font-bold text-slate-400 uppercase">Admin Password</label><input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempAdmin.password} onChange={e => setTempAdmin({...tempAdmin, password: e.target.value})} /></div>
            </div>
            <div className="pt-6 border-t dark:border-slate-700 flex justify-end"><button onClick={handleSaveSiteConfig} className="bg-green-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl">Apply Settings</button></div>
          </div>
        </div>
      )}

      {/* --- Modals --- */}

      {/* Viewing Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl p-12 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-8"><h2 className="text-4xl font-black">{viewingStudent.name}</h2><button onClick={() => setViewingStudent(null)} className="p-4 bg-slate-100 dark:bg-slate-700 rounded-full font-bold">✕</button></div>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Personal Info</p>
                  <p><b>Class:</b> {viewingStudent.class}</p>
                  <p><b>DOB:</b> {viewingStudent.dob}</p>
                  <p><b>Address:</b> {viewingStudent.address}</p>
                  <p><b>Own Phone:</b> {viewingStudent.ownPhone}</p>
                  <p><b>Guardian:</b> {viewingStudent.guardianPhone}</p>
               </div>
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">SSC Record</p>
                  <p><b>SSC Roll:</b> {viewingStudent.sscRoll}</p>
                  <p><b>SSC Reg:</b> {viewingStudent.sscReg}</p>
                  <p className="pt-4 font-bold text-blue-600">Portal Email: {viewingStudent.email}</p>
                  <p className={`font-black uppercase tracking-widest text-xs ${viewingStudent.isVerified ? 'text-green-500' : 'text-orange-500'}`}>{viewingStudent.isVerified ? 'Verified' : 'Pending Approval'}</p>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Editing Modal */}
      {editingStudent && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <form onSubmit={handleStudentUpdate} className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl p-10 space-y-6 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Update Admission Data</h2><button type="button" onClick={() => setEditingStudent(null)} className="text-slate-400 font-bold">✕</button></div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1"><label className="text-xs font-bold">Full Name</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.name} onChange={e => setStudentForm({...studentForm, name: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">SSC Roll</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.sscRoll} onChange={e => setStudentForm({...studentForm, sscRoll: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">SSC Reg</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.sscReg} onChange={e => setStudentForm({...studentForm, sscReg: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Own Phone</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.ownPhone} onChange={e => setStudentForm({...studentForm, ownPhone: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Guardian Phone</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.guardianPhone} onChange={e => setStudentForm({...studentForm, guardianPhone: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Class</label><select className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.class} onChange={e => setStudentForm({...studentForm, class: e.target.value as any})}><option value="HSC 1st Year">HSC 1st Year</option><option value="HSC 2nd Year">HSC 2nd Year</option></select></div>
            </div>
            <div className="space-y-1"><label className="text-xs font-bold">Password</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.password} onChange={e => setStudentForm({...studentForm, password: e.target.value})} /></div>
            <button type="submit" className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl transition-all hover:bg-blue-700">Update Student Data</button>
          </form>
        </div>
      )}

      {/* Marks Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40"><h2 className="text-3xl font-black">Enter Marks</h2><button onClick={() => setEnteringMarksFor(null)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-2xl font-bold">✕</button></div>
            <div className="flex-grow overflow-y-auto p-10 space-y-4">
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-900 rounded-[24px]"><span className="font-bold text-lg">{s.name}</span><input type="number" className="w-24 p-4 rounded-2xl border dark:bg-slate-800 text-center font-black text-blue-600" value={enteringMarksFor.marks[s.id] || ''} onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))} /></div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700"><button onClick={() => setEnteringMarksFor(null)} className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl shadow-xl hover:bg-blue-700">Save & Close</button></div>
          </div>
        </div>
      )}

      {/* Teacher Modal */}
      {isTeacherModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8 animate-in zoom-in duration-300">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingTeacher ? 'Edit Teacher' : 'Add Teacher'}</h2><button onClick={() => setIsTeacherModalOpen(false)} className="text-slate-400 font-bold">✕</button></div>
            <form onSubmit={handleTeacherSubmit} className="space-y-6">
              <div className="flex flex-col items-center space-y-4">
                 <div className="relative group cursor-pointer" onClick={() => teacherPicRef.current?.click()}>
                   <div className="w-32 h-32 rounded-[32px] overflow-hidden border-4 border-blue-500 bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-slate-300 font-black">{teacherForm.image ? <img src={teacherForm.image} className="w-full h-full object-cover" /> : '?'}</div>
                   <input type="file" hidden ref={teacherPicRef} accept="image/*" onChange={(e) => handleFileUpload(e, (b) => setTeacherForm({...teacherForm, image: b}))} />
                 </div>
              </div>
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Full Name" value={teacherForm.name} onChange={e => setTeacherForm({...teacherForm, name: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Subject" value={teacherForm.subject} onChange={e => setTeacherForm({...teacherForm, subject: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Qualification" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Experience" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-xl hover:bg-blue-700 transition-all">{editingTeacher ? 'Update Teacher' : 'Register Faculty'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Course Modal */}
      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8 animate-in zoom-in duration-300">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingCourse ? 'Edit Course' : 'Add Course'}</h2><button onClick={() => setIsCourseModalOpen(false)} className="text-slate-400 font-bold">✕</button></div>
            <form onSubmit={handleCourseSubmit} className="space-y-5">
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Course Name" value={courseForm.name} onChange={e => setCourseForm({...courseForm, name: e.target.value})} />
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Icon (Emoji)" value={courseForm.icon} onChange={e => setCourseForm({...courseForm, icon: e.target.value})} />
              <input required type="number" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Classes/Week" value={courseForm.classesPerWeek} onChange={e => setCourseForm({...courseForm, classesPerWeek: parseInt(e.target.value)})} />
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-2xl hover:bg-blue-700 transition-all">{editingCourse ? 'Update Course' : 'Create Course'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Exam Schedule Modal */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8 animate-in zoom-in duration-300">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Schedule Exam</h2><button onClick={() => setIsExamModalOpen(false)} className="text-slate-400 font-bold">✕</button></div>
            <form onSubmit={handleExamSubmit} className="space-y-5">
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-medium outline-none focus:ring-2 ring-orange-500" placeholder="Exam Title" value={examForm.name} onChange={e => setExamForm({...examForm, name: e.target.value})} />
              <select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.subject} onChange={e => setExamForm({...examForm, subject: e.target.value})}>{subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}</select>
              <input required type="date" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.date} onChange={e => setExamForm({...examForm, date: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-[24px] shadow-2xl hover:bg-orange-600 transition-all">Publish Schedule</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);

  // Attendance State
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
  const [attendanceMap, setAttendanceMap] = useState<Record<string, boolean>>({});

  // Site Config states
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });
  const [tempAdmin, setTempAdmin] = useState<AdminUser>({ ...adminProfile });

  // Form States
  const [courseForm, setCourseForm] = useState({ name: '', icon: '📚', classesPerWeek: 3 });
  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ 
    name: '', 
    subject: subjects[0]?.name || 'Physics', 
    date: new Date().toISOString().split('T')[0] 
  });

  // Student Edit Form State
  const [studentForm, setStudentForm] = useState<Partial<Student>>({});

  // Refs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const newMap: Record<string, boolean> = {};
    students.forEach(s => {
      if (s.dailyAttendance && s.dailyAttendance[attendanceDate] !== undefined) {
        newMap[s.id] = s.dailyAttendance[attendanceDate];
      } else {
        newMap[s.id] = false;
      }
    });
    setAttendanceMap(newMap);
  }, [attendanceDate, students]);

  useEffect(() => {
    if (editingCourse) {
      setCourseForm({ name: editingCourse.name, icon: editingCourse.icon, classesPerWeek: editingCourse.classesPerWeek });
    } else {
      setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
    }
  }, [editingCourse]);

  useEffect(() => {
    if (editingTeacher) {
      setTeacherForm({ name: editingTeacher.name, subject: editingTeacher.subject, qualification: editingTeacher.qualification, experience: editingTeacher.experience, image: editingTeacher.image });
    } else {
      setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
    }
  }, [editingTeacher]);

  useEffect(() => {
    if (editingStudent) {
      setStudentForm(editingStudent);
    }
  }, [editingStudent]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    setAdminProfile(tempAdmin);
    alert("Site configuration and account settings updated successfully!");
  };

  // Link management helpers for Footer
  const handleAddLink = (type: 'quick' | 'support') => {
    const newLink = { name: 'New Link', url: '#' };
    if (type === 'quick') {
      setTempFooter({ ...tempFooter, quickLinks: [...tempFooter.quickLinks, newLink] });
    } else {
      setTempFooter({ ...tempFooter, supportLinks: [...tempFooter.supportLinks, newLink] });
    }
  };

  const handleRemoveLink = (type: 'quick' | 'support', index: number) => {
    if (type === 'quick') {
      const newList = [...tempFooter.quickLinks];
      newList.splice(index, 1);
      setTempFooter({ ...tempFooter, quickLinks: newList });
    } else {
      const newList = [...tempFooter.supportLinks];
      newList.splice(index, 1);
      setTempFooter({ ...tempFooter, supportLinks: newList });
    }
  };

  const handleUpdateLink = (type: 'quick' | 'support', index: number, field: 'name' | 'url', value: string) => {
    if (type === 'quick') {
      const newList = [...tempFooter.quickLinks];
      newList[index] = { ...newList[index], [field]: value };
      setTempFooter({ ...tempFooter, quickLinks: newList });
    } else {
      const newList = [...tempFooter.supportLinks];
      newList[index] = { ...newList[index], [field]: value };
      setTempFooter({ ...tempFooter, supportLinks: newList });
    }
  };

  const handleStudentUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingStudent) return;
    setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...studentForm } as Student : s));
    setEditingStudent(null);
    alert("Student record updated successfully.");
  };

  const handleVerifyStudent = (studentId: string) => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isVerified: true } : s));
    alert("Student verified and access granted.");
  };

  const toggleAttendance = (studentId: string) => {
    setAttendanceMap(prev => ({ ...prev, [studentId]: !prev[studentId] }));
  };

  const submitAttendance = () => {
    setStudents(prev => prev.map(s => {
      const newDailyAttendance = { ...(s.dailyAttendance || {}), [attendanceDate]: attendanceMap[s.id] };
      const totalDays = Object.keys(newDailyAttendance).length;
      const presentDays = Object.values(newDailyAttendance).filter(val => val === true).length;
      const newPercentage = totalDays > 0 ? (presentDays / totalDays) * 100 : 0;
      return { ...s, dailyAttendance: newDailyAttendance, attendance: parseFloat(newPercentage.toFixed(1)) };
    }));
    alert("Attendance submitted for " + attendanceDate);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    } else {
      setTeachers([...teachers, { id: `t-${Date.now()}`, ...teacherForm }]);
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCourse) {
      setSubjects(subjects.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
    } else {
      setSubjects([...subjects, { id: `sub-${Date.now()}`, ...courseForm }]);
    }
    setIsCourseModalOpen(false);
    setEditingCourse(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams([...exams, newExam]);
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);
  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
            <button onClick={() => adminAvatarRef.current?.click()} className="absolute inset-0 bg-black/40 text-white rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center text-[10px] font-bold">Update</button>
            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">Administrator</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-6 py-2 bg-slate-200 dark:bg-slate-800 rounded-2xl font-bold text-sm hover:bg-slate-300 transition-colors">Logout</button>
      </header>

      <div className="flex space-x-4 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {['overview', 'students', 'teachers', 'courses', 'exams', 'attendance', 'pending', 'settings'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`pb-4 px-2 text-sm font-bold capitalize transition-all border-b-2 ${activeTab === t ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-700'}`}>
            {t} {t === 'pending' ? `(${pendingStudents.length})` : ''}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Verified Students</p>
             <p className="text-5xl font-black text-blue-600">{verifiedStudents.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Faculty</p>
             <p className="text-5xl font-black text-purple-600">{teachers.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700">
             <p className="text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Active Exams</p>
             <p className="text-5xl font-black text-orange-500">{exams.length}</p>
          </div>
        </div>
      )}

      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b dark:border-slate-700 flex justify-between items-center">
             <h3 className="font-bold">Verified Student List</h3>
          </div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 group">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 rounded-2xl bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-blue-600 font-bold">{student.name.charAt(0)}</div>
                      <div>
                        <p className="font-bold">{student.name}</p>
                        <p className="text-xs text-slate-400">{student.phone}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-xs font-medium text-slate-500">{student.class}</td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button onClick={() => setViewingStudent(student)} className="bg-slate-100 dark:bg-slate-700 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all">View</button>
                    <button onClick={() => setEditingStudent(student)} className="bg-blue-100 dark:bg-blue-900/30 text-blue-600 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all">Edit</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'pending' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl border dark:border-slate-700 shadow-sm overflow-hidden">
          <div className="p-8 border-b dark:border-slate-700"><h3 className="text-xl font-bold">Admission Requests</h3></div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {pendingStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900">
                  <td className="px-8 py-6"><div className="flex items-center space-x-4"><div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center font-bold">{student.name.charAt(0)}</div><div><p className="font-bold">{student.name}</p><p className="text-xs text-slate-400">{student.phone}</p></div></div></td>
                  <td className="px-8 py-6 text-sm font-medium">{student.class}</td>
                  <td className="px-8 py-6 text-right space-x-4">
                    <button onClick={() => setViewingStudent(student)} className="text-xs font-bold text-slate-400 hover:text-blue-600">Details</button>
                    <button onClick={() => handleVerifyStudent(student.id)} className="bg-blue-600 text-white px-6 py-2 rounded-xl text-xs font-bold shadow-md hover:bg-blue-700">Verify</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'settings' && (
        <div className="space-y-12 pb-20">
          {/* Platform Branding */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-black">Platform Branding</h3>
              <button onClick={() => logoUploadRef.current?.click()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl text-xs font-bold shadow-lg">Upload Logo</button>
