                  className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" 
                  value={tempAdmin.email} 
                  onChange={e => setTempAdmin({...tempAdmin, email: e.target.value})} 
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase">Admin Password</label>
                <input 
                  type="text" 
                  className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" 
                  value={tempAdmin.password} 
                  onChange={e => setTempAdmin({...tempAdmin, password: e.target.value})} 
                />
              </div>
            </div>
          </div>

          {/* Home Page Content */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-2xl font-black">Home Page Content</h3>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="space-y-2 md:col-span-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Hero Main Title</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.heroTitle} onChange={e => setTempHome({...tempHome, heroTitle: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Enroll Button Text</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.heroEnrollText} onChange={e => setTempHome({...tempHome, heroEnrollText: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Explore Button Text</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.heroExploreText} onChange={e => setTempHome({...tempHome, heroExploreText: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Stat: Experience</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.statExperience} onChange={e => setTempHome({...tempHome, statExperience: e.target.value})} />
               </div>
               <div className="space-y-2">
                 <label className="text-xs font-bold text-slate-400 uppercase">Stat: Students</label>
                 <input type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={tempHome.statStudents} onChange={e => setTempHome({...tempHome, statStudents: e.target.value})} />
               </div>
            </div>
          </div>

          {/* Footer Details */}
          <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] border dark:border-slate-700 shadow-sm space-y-8">
            <h3 className="text-2xl font-black">Footer Details</h3>
            <div className="space-y-6">
              <textarea className="w-full p-4 rounded-2xl border dark:bg-slate-900 min-h-[100px]" placeholder="Description" value={tempFooter.description} onChange={e => setTempFooter({...tempFooter, description: e.target.value})} />
              <div className="grid md:grid-cols-2 gap-4">
                <input type="text" className="p-4 rounded-2xl border dark:bg-slate-900" placeholder="Address" value={tempFooter.address} onChange={e => setTempFooter({...tempFooter, address: e.target.value})} />
                <input type="text" className="p-4 rounded-2xl border dark:bg-slate-900" placeholder="Phone" value={tempFooter.phone} onChange={e => setTempFooter({...tempFooter, phone: e.target.value})} />
                <input type="text" className="p-4 rounded-2xl border dark:bg-slate-900 md:col-span-2" placeholder="Email" value={tempFooter.email} onChange={e => setTempFooter({...tempFooter, email: e.target.value})} />
              </div>

              {/* Quick Links */}
              <div className="space-y-4 pt-6">
                <div className="flex justify-between items-center">
                  <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">Quick Links</h4>
                  <button onClick={() => handleAddLink('quick')} className="text-xs font-bold text-blue-600 hover:underline">+ Add Link</button>
                </div>
                <div className="space-y-3">
                  {tempFooter.quickLinks.map((link, idx) => (
                    <div key={idx} className="flex gap-4 items-center">
                      <input type="text" className="flex-1 p-3 rounded-xl border dark:bg-slate-900 text-sm" placeholder="Name" value={link.name} onChange={e => handleUpdateLink('quick', idx, 'name', e.target.value)} />
                      <input type="text" className="flex-1 p-3 rounded-xl border dark:bg-slate-900 text-sm" placeholder="URL" value={link.url} onChange={e => handleUpdateLink('quick', idx, 'url', e.target.value)} />
                      <button onClick={() => handleRemoveLink('quick', idx)} className="text-red-500 p-2">🗑️</button>
                    </div>
                  ))}
                </div>
              </div>

              {/* Support Links */}
              <div className="space-y-4 pt-6">
                <div className="flex justify-between items-center">
                  <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">Support Links</h4>
                  <button onClick={() => handleAddLink('support')} className="text-xs font-bold text-blue-600 hover:underline">+ Add Link</button>
                </div>
                <div className="space-y-3">
                  {tempFooter.supportLinks.map((link, idx) => (
                    <div key={idx} className="flex gap-4 items-center">
                      <input type="text" className="flex-1 p-3 rounded-xl border dark:bg-slate-900 text-sm" placeholder="Name" value={link.name} onChange={e => handleUpdateLink('support', idx, 'name', e.target.value)} />
                      <input type="text" className="flex-1 p-3 rounded-xl border dark:bg-slate-900 text-sm" placeholder="URL" value={link.url} onChange={e => handleUpdateLink('support', idx, 'url', e.target.value)} />
                      <button onClick={() => handleRemoveLink('support', idx)} className="text-red-500 p-2">🗑️</button>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="pt-6 border-t dark:border-slate-700 flex justify-end">
              <button onClick={handleSaveSiteConfig} className="bg-green-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl hover:bg-green-700 transition-all">Apply All Changes</button>
            </div>
          </div>
        </div>
      )}

      {/* --- Existing Feature Modals Kept Intact --- */}

      {/* Viewing Modal */}
      {viewingStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl p-12 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-8"><h2 className="text-4xl font-black">{viewingStudent.name}</h2><button onClick={() => setViewingStudent(null)} className="p-4 bg-slate-100 dark:bg-slate-700 rounded-full font-bold">✕</button></div>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Personal Info</p>
                  <p><b>Class:</b> {viewingStudent.class}</p>
                  <p><b>DOB:</b> {viewingStudent.dob}</p>
                  <p><b>Address:</b> {viewingStudent.address}</p>
                  <p><b>Own Phone:</b> {viewingStudent.ownPhone}</p>
                  <p><b>Guardian:</b> {viewingStudent.guardianPhone}</p>
               </div>
               <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-3xl space-y-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">SSC Record</p>
                  <p><b>SSC Roll:</b> {viewingStudent.sscRoll}</p>
                  <p><b>SSC Reg:</b> {viewingStudent.sscReg}</p>
                  <p className="pt-4 font-bold text-blue-600">Portal Email: {viewingStudent.email}</p>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Editing Modal */}
      {editingStudent && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <form onSubmit={handleStudentUpdate} className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl p-10 space-y-6 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Update Admission Data</h2><button type="button" onClick={() => setEditingStudent(null)} className="text-slate-400 font-bold">✕</button></div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1"><label className="text-xs font-bold">Full Name</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.name} onChange={e => setStudentForm({...studentForm, name: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">SSC Roll</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.sscRoll} onChange={e => setStudentForm({...studentForm, sscRoll: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">SSC Reg</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.sscReg} onChange={e => setStudentForm({...studentForm, sscReg: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Own Phone</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.ownPhone} onChange={e => setStudentForm({...studentForm, ownPhone: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Guardian Phone</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.guardianPhone} onChange={e => setStudentForm({...studentForm, guardianPhone: e.target.value})} /></div>
              <div className="space-y-1"><label className="text-xs font-bold">Class</label><select className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.class} onChange={e => setStudentForm({...studentForm, class: e.target.value as any})}><option value="HSC 1st Year">HSC 1st Year</option><option value="HSC 2nd Year">HSC 2nd Year</option></select></div>
            </div>
            <div className="space-y-1"><label className="text-xs font-bold">Password</label><input className="w-full p-3 border rounded-xl dark:bg-slate-900" value={studentForm.password} onChange={e => setStudentForm({...studentForm, password: e.target.value})} /></div>
            <button type="submit" className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl transition-all hover:bg-blue-700">Update Student Data</button>
          </form>
        </div>
      )}

      {/* Marks Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[40px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40"><h2 className="text-3xl font-black">Enter Marks</h2><button onClick={() => setEnteringMarksFor(null)} className="p-3 bg-slate-100 dark:bg-slate-700 rounded-2xl font-bold">✕</button></div>
