            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingTeacher ? 'Edit Teacher' : 'Add Teacher'}</h2><button onClick={() => setIsTeacherModalOpen(false)} className="text-slate-400 font-bold">✕</button></div>
