              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Icon (Emoji)" value={courseForm.icon} onChange={e => setCourseForm({...courseForm, icon: e.target.value})} />
              <input required type="number" className="w-full p-4 rounded-2xl border dark:bg-slate-900 outline-none" placeholder="Classes/Week" value={courseForm.classesPerWeek} onChange={e => setCourseForm({...courseForm, classesPerWeek: parseInt(e.target.value)})} />
              <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-2xl hover:bg-blue-700 transition-all">{editingCourse ? 'Update Course' : 'Create Course'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Exam Schedule Modal */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[40px] shadow-2xl p-10 space-y-8 animate-in zoom-in duration-300">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Schedule Exam</h2><button onClick={() => setIsExamModalOpen(false)} className="text-slate-400 font-bold">✕</button></div>
            <form onSubmit={handleExamSubmit} className="space-y-5">
              <input required type="text" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-medium outline-none focus:ring-2 ring-orange-500" placeholder="Exam Title" value={examForm.name} onChange={e => setExamForm({...examForm, name: e.target.value})} />
              <select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.subject} onChange={e => setExamForm({...examForm, subject: e.target.value})}>{subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}</select>
              <input required type="date" className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold outline-none focus:ring-2 ring-orange-500" value={examForm.date} onChange={e => setExamForm({...examForm, date: e.target.value})} />
              <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-[24px] shadow-2xl hover:bg-orange-600 transition-all">Publish Schedule</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: (subs: Subject[]) => void;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');

  // Modal states
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  // Edit states
  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);

  // Attendance State
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
  const [attendanceMap, setAttendanceMap] = useState<Record<string, boolean>>({});

  // Site Configuration states (Buffered for saving)
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });
  const [tempAdmin, setTempAdmin] = useState<AdminUser>({ ...adminProfile });

  // Form Field states
  const [courseForm, setCourseForm] = useState({ name: '', icon: '📚', classesPerWeek: 3 });
  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ 
    name: '', 
    subject: subjects[0]?.name || 'Physics', 
    date: new Date().toISOString().split('T')[0] 
  });
  const [studentForm, setStudentForm] = useState<Partial<Student>>({});

  // Input Refs for Uploads
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  // Sync Attendance Map when date or student list changes
  useEffect(() => {
    const newMap: Record<string, boolean> = {};
    students.forEach(s => {
      if (s.dailyAttendance && s.dailyAttendance[attendanceDate] !== undefined) {
        newMap[s.id] = s.dailyAttendance[attendanceDate];
      } else {
        newMap[s.id] = false;
      }
    });
    setAttendanceMap(newMap);
  }, [attendanceDate, students]);

  // Sync forms with editing targets
  useEffect(() => {
    if (editingCourse) setCourseForm({ name: editingCourse.name, icon: editingCourse.icon, classesPerWeek: editingCourse.classesPerWeek });
    else setCourseForm({ name: '', icon: '📚', classesPerWeek: 3 });
  }, [editingCourse, isCourseModalOpen]);

  useEffect(() => {
    if (editingTeacher) setTeacherForm({ name: editingTeacher.name, subject: editingTeacher.subject, qualification: editingTeacher.qualification, experience: editingTeacher.experience, image: editingTeacher.image });
    else setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
  }, [editingTeacher, isTeacherModalOpen]);

  useEffect(() => {
    if (editingStudent) setStudentForm(editingStudent);
  }, [editingStudent]);

  // Base64 File Uploader
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  // --- Handlers for Students ---
  const handleStudentUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingStudent) return;
    setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...studentForm } as Student : s));
    setEditingStudent(null);
    alert("Student data successfully updated.");
  };

  const handleVerifyStudent = (studentId: string) => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isVerified: true } : s));
  };

  const toggleAttendance = (studentId: string) => {
    setAttendanceMap(prev => ({ ...prev, [studentId]: !prev[studentId] }));
  };

  const submitAttendance = () => {
    setStudents(prev => prev.map(s => {
      const newDailyAttendance = { ...(s.dailyAttendance || {}), [attendanceDate]: attendanceMap[s.id] };
      const totalDays = Object.keys(newDailyAttendance).length;
      const presentDays = Object.values(newDailyAttendance).filter(val => val === true).length;
      const newPercentage = totalDays > 0 ? (presentDays / totalDays) * 100 : 0;
      return { ...s, dailyAttendance: newDailyAttendance, attendance: parseFloat(newPercentage.toFixed(1)) };
    }));
    alert("Attendance successfully submitted for " + attendanceDate);
  };

  // --- Handlers for Teachers / Courses / Exams ---
  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(teachers.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
    } else {
      setTeachers([...teachers, { id: `t-${Date.now()}`, ...teacherForm }]);
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCourse) {
      setSubjects(subjects.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
    } else {
      setSubjects([...subjects, { id: `sub-${Date.now()}`, ...courseForm }]);
    }
    setIsCourseModalOpen(false);
    setEditingCourse(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams([...exams, newExam]);
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

  // --- Handlers for Site Config (Footer/Home/Admin) ---
  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    setAdminProfile(tempAdmin);
    alert("All site and configuration changes have been applied.");
  };

  const handleAddLink = (type: 'quick' | 'support') => {
    const newLink = { name: 'New Link', url: '#' };
    if (type === 'quick') setTempFooter({ ...tempFooter, quickLinks: [...tempFooter.quickLinks, newLink] });
    else setTempFooter({ ...tempFooter, supportLinks: [...tempFooter.supportLinks, newLink] });
  };

  const handleRemoveLink = (type: 'quick' | 'support', index: number) => {
    if (type === 'quick') {
      const newList = [...tempFooter.quickLinks];
      newList.splice(index, 1);
      setTempFooter({ ...tempFooter, quickLinks: newList });
    } else {
      const newList = [...tempFooter.supportLinks];
      newList.splice(index, 1);
      setTempFooter({ ...tempFooter, supportLinks: newList });
    }
  };

  const handleUpdateLink = (type: 'quick' | 'support', index: number, field: 'name' | 'url', value: string) => {
    if (type === 'quick') {
      const newList = [...tempFooter.quickLinks];
      newList[index] = { ...newList[index], [field]: value };
      setTempFooter({ ...tempFooter, quickLinks: newList });
    } else {
      const newList = [...tempFooter.supportLinks];
      newList[index] = { ...newList[index], [field]: value };
      setTempFooter({ ...tempFooter, supportLinks: newList });
    }
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);
  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      {/* Header Section */}
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group cursor-pointer">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
            <button onClick={() => adminAvatarRef.current?.click()} className="absolute inset-0 bg-black/40 text-white rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center text-[10px] font-bold">Change</button>
            <input type="file" hidden ref={adminAvatarRef} onChange={(e) => handleFileUpload(e, (b) => setAdminProfile({...adminProfile, avatar: b}))} />
          </div>
          <div>
            <h1 className="text-3xl font-bold">{adminProfile.name}</h1>
            <p className="text-slate-500">Phoenix Administrative Center</p>
          </div>
        </div>
        <button onClick={onLogout} className="px-8 py-3 bg-slate-200 dark:bg-slate-800 rounded-2xl font-black text-sm hover:bg-slate-300 transition-all active:scale-95 shadow-sm">Logout Session</button>
      </header>

      {/* Primary Navigation Tabs */}
      <div className="flex space-x-6 border-b dark:border-slate-800 pb-px overflow-x-auto no-scrollbar">
        {['overview', 'students', 'teachers', 'courses', 'exams', 'attendance', 'pending', 'settings'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`pb-4 px-2 text-sm font-black capitalize transition-all border-b-2 ${activeTab === t ? 'border-orange-500 text-orange-500' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
            {t} {t === 'pending' ? `(${pendingStudents.length})` : ''}
          </button>
        ))}
      </div>

      {/* TAB: Overview */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700 animate-in fade-in slide-in-from-bottom-2">
             <p className="text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">Active Students</p>
             <p className="text-6xl font-black text-blue-600 tracking-tighter">{verifiedStudents.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700 animate-in fade-in slide-in-from-bottom-2 delay-75">
             <p className="text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">Faculty Members</p>
             <p className="text-6xl font-black text-purple-600 tracking-tighter">{teachers.length}</p>
          </div>
          <div className="p-10 bg-white dark:bg-slate-800 rounded-[40px] shadow-sm border dark:border-slate-700 animate-in fade-in slide-in-from-bottom-2 delay-150">
             <p className="text-xs font-black text-slate-400 mb-2 uppercase tracking-widest">Ongoing Exams</p>
             <p className="text-6xl font-black text-orange-500 tracking-tighter">{exams.length}</p>
          </div>
        </div>
      )}

      {/* TAB: Verified Students */}
      {activeTab === 'students' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl border dark:border-slate-700 overflow-hidden">
          <div className="p-8 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40">
             <h3 className="text-xl font-black">Student Directory</h3>
          </div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {verifiedStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 group transition-colors">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <div className="w-12 h-12 rounded-2xl bg-blue-50 dark:bg-blue-900/30 flex items-center justify-center text-blue-600 font-black text-lg">{student.name.charAt(0)}</div>
                      <div>
                        <p className="font-black text-lg">{student.name}</p>
                        <p className="text-xs text-slate-400 font-bold">{student.phone}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5"><span className="text-sm font-black text-slate-500 bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-lg">{student.class}</span></td>
                  <td className="px-8 py-5 text-right space-x-3">
                    <button onClick={() => setViewingStudent(student)} className="px-5 py-2.5 bg-slate-100 dark:bg-slate-700 rounded-xl text-xs font-black hover:bg-blue-600 hover:text-white transition-all">View Profile</button>
                    <button onClick={() => setEditingStudent(student)} className="px-5 py-2.5 bg-blue-100 dark:bg-blue-900/30 text-blue-600 rounded-xl text-xs font-black hover:bg-blue-600 hover:text-white transition-all">Edit Admission</button>
                  </td>
                </tr>
              ))}
              {verifiedStudents.length === 0 && <tr><td colSpan={3} className="p-20 text-center font-bold text-slate-400">No students are currently verified.</td></tr>}
            </tbody>
          </table>
        </div>
      )}

      {/* TAB: Pending Admissions */}
      {activeTab === 'pending' && (
        <div className="bg-white dark:bg-slate-800 rounded-3xl border dark:border-slate-700 shadow-xl overflow-hidden">
          <div className="p-8 border-b dark:border-slate-700 bg-orange-50 dark:bg-orange-900/10"><h3 className="text-xl font-black text-orange-600">Pending Approvals</h3></div>
          <table className="w-full text-left">
            <tbody className="divide-y dark:divide-slate-700">
              {pendingStudents.map(student => (
                <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                  <td className="px-8 py-6"><div className="flex items-center space-x-4"><div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center font-black">{student.name.charAt(0)}</div><div><p className="font-black">{student.name}</p><p className="text-xs text-slate-400 font-bold">{student.phone}</p></div></div></td>
                  <td className="px-8 py-6 text-sm font-black text-slate-500">{student.class}</td>
                  <td className="px-8 py-6 text-right space-x-4">
                    <button onClick={() => setViewingStudent(student)} className="text-xs font-black text-slate-400 hover:text-blue-600 transition-colors">Details</button>
                    <button onClick={() => handleVerifyStudent(student.id)} className="bg-green-600 text-white px-8 py-3 rounded-xl text-xs font-black shadow-lg hover:bg-green-700 transition-all active:scale-95">Verify Admission</button>
                  </td>
                </tr>
              ))}
              {pendingStudents.length === 0 && <tr><td colSpan={3} className="p-20 text-center font-bold text-slate-400">No pending admission requests found.</td></tr>}
            </tbody>
          </table>
        </div>
      )}

      {/* TAB: Attendance Management */}
      {activeTab === 'attendance' && (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white dark:bg-slate-800 p-8 rounded-[40px] border dark:border-slate-700 shadow-xl">
            <div><h3 className="text-2xl font-black">Daily Attendance System</h3><p className="text-slate-500 font-medium">Updating logs for {attendanceDate}.</p></div>
            <div className="flex items-center gap-4">
              <input type="date" value={attendanceDate} onChange={(e) => setAttendanceDate(e.target.value)} className="p-4 rounded-2xl border dark:bg-slate-900 border-slate-200 dark:border-slate-700 outline-none font-black text-blue-600 shadow-inner" />
              <button onClick={submitAttendance} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl hover:bg-blue-700 transition-all active:scale-95">Commit Records</button>
            </div>
          </div>
          <div className="bg-white dark:bg-slate-800 rounded-[40px] border dark:border-slate-700 shadow-xl overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 dark:bg-slate-900/50">
                <tr><th className="px-10 py-5 text-xs font-black text-slate-400 uppercase tracking-widest">Student Name</th><th className="px-10 py-5 text-xs font-black text-slate-400 uppercase tracking-widest">Presence</th><th className="px-10 py-5 text-right text-xs font-black text-slate-400 uppercase tracking-widest">Action</th></tr>
              </thead>
              <tbody className="divide-y dark:divide-slate-700">
                {verifiedStudents.map(student => (
                  <tr key={student.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                    <td className="px-10 py-6 font-black text-lg">{student.name}</td>
                    <td className="px-10 py-6"><div className="flex items-center gap-3"><div className={`w-3.5 h-3.5 rounded-full ring-4 ${attendanceMap[student.id] ? 'bg-green-500 ring-green-100 dark:ring-green-900/30' : 'bg-red-500 ring-red-100 dark:ring-red-900/30'}`}></div><span className={`text-xs font-black uppercase tracking-widest ${attendanceMap[student.id] ? 'text-green-600' : 'text-red-600'}`}>{attendanceMap[student.id] ? 'Present' : 'Absent'}</span></div></td>
                    <td className="px-10 py-6 text-right"><button onClick={() => toggleAttendance(student.id)} className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all shadow-sm ${attendanceMap[student.id] ? 'bg-red-100 text-red-600 hover:bg-red-600 hover:text-white' : 'bg-green-100 text-green-600 hover:bg-green-600 hover:text-white'}`}>{attendanceMap[student.id] ? 'Mark Absent' : 'Mark Present'}</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* TAB: Teachers / Faculty */}
      {activeTab === 'teachers' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white dark:bg-slate-800 p-8 rounded-[40px] shadow-sm border dark:border-slate-700">
            <h3 className="text-2xl font-black">Faculty Management</h3>
            <button onClick={() => { setEditingTeacher(null); setIsTeacherModalOpen(true); }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-sm shadow-xl hover:bg-blue-700 transition-all active:scale-95">+ Register Teacher</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {teachers.map(t => (
              <div key={t.id} className="bg-white dark:bg-slate-800 p-8 rounded-[40px] border dark:border-slate-700 shadow-xl flex items-center space-x-6 hover:translate-y-[-4px] transition-all">
                <img src={t.image} className="w-24 h-24 rounded-[32px] object-cover border-4 border-slate-50 dark:border-slate-900 shadow-md" alt={t.name} />
                <div className="flex-grow">
                  <h4 className="font-black text-xl">{t.name}</h4>
                  <p className="text-xs text-orange-500 font-black uppercase tracking-widest">{t.subject}</p>
                  <div className="mt-5 flex gap-4"><button onClick={() => { setEditingTeacher(t); setIsTeacherModalOpen(true); }} className="text-xs text-blue-600 font-black hover:underline">Edit Info</button><button onClick={() => setTeachers(teachers.filter(x => x.id !== t.id))} className="text-xs text-red-500 font-black hover:underline">Revoke Access</button></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* TAB: Courses */}
      {activeTab === 'courses' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white dark:bg-slate-800 p-8 rounded-[40px] shadow-sm border dark:border-slate-700">
            <h3 className="text-2xl font-black">Curriculum Control</h3>
            <button onClick={() => { setEditingCourse(null); setIsCourseModalOpen(true); }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-sm shadow-xl hover:bg-blue-700 transition-all">+ New Course</button>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {subjects.map(s => (
              <div key={s.id} className="bg-white dark:bg-slate-800 p-8 rounded-[40px] border dark:border-slate-700 shadow-xl flex items-center justify-between group transition-all">
                <div className="flex items-center space-x-5"><span className="text-4xl group-hover:scale-110 transition-transform">{s.icon}</span><div><h4 className="font-black text-lg">{s.name}</h4><p className="text-xs text-slate-400 font-black uppercase">{s.classesPerWeek} Classes/Week</p></div></div>
                <div className="flex gap-2"><button onClick={() => { setEditingCourse(s); setIsCourseModalOpen(true); }} className="p-3 bg-blue-50 dark:bg-blue-900/30 text-blue-500 rounded-2xl font-bold hover:bg-blue-600 hover:text-white transition-all">✏️</button><button onClick={() => setSubjects(subjects.filter(x => x.id !== s.id))} className="p-3 bg-red-50 dark:bg-red-900/30 text-red-500 rounded-2xl font-bold hover:bg-red-600 hover:text-white transition-all">🗑️</button></div>
              </div>
