};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Student, PerformanceInsight, Exam } from '../types';
import { getPerformanceInsight } from '../services/geminiService';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';

interface Props {
  student: Student;
  exams: Exam[];
  onLogout: () => void;
}

const StudentDashboard: React.FC<Props> = ({ student, exams, onLogout }) => {
  const [insight, setInsight] = useState<PerformanceInsight | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<'dashboard' | 'profile'>('dashboard');

  const studentResults = exams.map(exam => ({
    name: exam.name,
    subject: exam.subject,
    score: exam.marks[student.id],
    date: exam.date
  }));

  useEffect(() => {
    const fetchInsight = async () => {
      const data = await getPerformanceInsight(student.attendance, student.averageScore, student.assignments);
      setInsight(data);
      setLoading(false);
    };
    fetchInsight();
  }, [student]);

  const statsData = [
    { subject: 'Attendance', value: student.attendance, full: 100 },
    { subject: 'Exam Score', value: student.averageScore, full: 100 },
    { subject: 'Assignments', value: student.assignments, full: 100 },
  ];

  const sortedAttendanceDates = Object.keys(student.dailyAttendance || {}).sort().reverse().slice(0, 10);

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold">Welcome, {student.name}</h1>
          <p className="text-slate-500">{student.class} • Science</p>
        </div>
        <div className="flex items-center gap-4">
           <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
              <button onClick={() => setActiveView('dashboard')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${activeView === 'dashboard' ? 'bg-white dark:bg-slate-700 shadow-sm text-blue-600' : 'text-slate-500'}`}>Stats</button>
              <button onClick={() => setActiveView('profile')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${activeView === 'profile' ? 'bg-white dark:bg-slate-700 shadow-sm text-blue-600' : 'text-slate-500'}`}>Profile</button>
           </div>

           {/* Detailed Payment Badges */}
           <div className="flex flex-col sm:flex-row gap-2">
             <div className={`px-4 py-1.5 rounded-lg text-xs font-black uppercase tracking-widest shadow-sm border ${student.monthlyFeeStatus === 'Paid' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
               Monthly: {student.monthlyFeeStatus || 'Due'}
             </div>
             <div className={`px-4 py-1.5 rounded-lg text-xs font-black uppercase tracking-widest shadow-sm border ${student.courseFeeStatus === 'Paid' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
               Course: {student.courseFeeStatus || 'Due'}
             </div>
           </div>
        </div>
      </header>

      {activeView === 'dashboard' ? (
        <>
          {/* Heatmap Section */}
          <section className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl p-8 border border-slate-100 dark:border-slate-700">
            <div className="flex flex-col md:flex-row gap-8 items-center">
              <div className="flex-1 w-full text-center md:text-left space-y-4">
                <h2 className="text-2xl font-bold flex items-center justify-center md:justify-start">🔥 Performance Insight</h2>
                <div className="flex items-center space-x-4 justify-center md:justify-start">
                  <div className="w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg" style={{ backgroundColor: insight?.color || '#ccc' }}>
                    {loading ? '...' : (insight?.status === 'Excellent' ? '🌟' : '💡')}
                  </div>
                  <div>
                    <p className="text-sm font-bold uppercase text-slate-400">AI Mentor Status</p>
                    <p className="text-xl font-extrabold" style={{ color: insight?.color }}>{loading ? 'Analyzing...' : insight?.status}</p>
                  </div>
                </div>
                <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl italic text-slate-600 dark:text-slate-400 border-l-4 border-orange-500">"{loading ? 'Summoning AI insights...' : insight?.message}"</div>
              </div>
              <div className="w-full md:w-1/3 h-[250px]">
                <ResponsiveContainer width="100%" height="100%">
                  <RadarChart cx="50%" cy="50%" outerRadius="80%" data={statsData}>
                    <PolarGrid stroke="#e2e8f0" />
                    <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12 }} />
                    <Radar name="Student" dataKey="value" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.6} />
                  </RadarChart>
                </ResponsiveContainer>
              </div>
            </div>
          </section>

          {/* Attendance Tracker */}
          <section className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
            <div className="flex justify-between items-center mb-8"><h3 className="text-xl font-bold">Recent Attendance</h3><p className="font-black text-blue-600">{student.attendance}% Rate</p></div>
            <div className="grid grid-cols-2 sm:grid-cols-5 md:grid-cols-10 gap-3">
              {sortedAttendanceDates.map(date => (
                <div key={date} className="flex flex-col items-center p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50">
                  <span className="text-[10px] font-bold text-slate-500">{date.split('-').slice(1).join('/')}</span>
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold mt-2 ${student.dailyAttendance?.[date] ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{student.dailyAttendance?.[date] ? 'P' : 'A'}</div>
                </div>
              ))}
            </div>
          </section>

          {/* Results Grid */}
          <div className="grid md:grid-cols-3 gap-8">
            <div className="md:col-span-2 bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700">
               <h3 className="text-xl font-bold mb-6">Exam Results</h3>
               <table className="w-full text-left"><tbody className="divide-y dark:divide-slate-700">{studentResults.map((res, i) => (
                 <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors"><td className="py-4 font-bold">{res.name}</td><td className="py-4 text-slate-500">{res.subject}</td><td className="py-4 text-right font-black text-blue-600">{res.score}/100</td></tr>
               ))}</tbody></table>
            </div>
            <div className="bg-orange-500 p-8 rounded-3xl shadow-lg text-white space-y-4">
