             <div className="p-8 bg-slate-50 dark:bg-slate-900 rounded-[32px] border border-slate-100 dark:border-slate-700 text-center space-y-2">
                <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Course Enrollment</p>
