    </div>
  );
};

export default StudentDashboard;

export enum UserRole {
  ADMIN = 'ADMIN',
  STUDENT = 'STUDENT',
  GUEST = 'GUEST'
}

export interface Teacher {
  id: string;
  name: string;
  subject: string;
  qualification: string;
  experience: string;
  image: string;
}

export interface Subject {
  id: string;
  name: string;
  icon: string;
  classesPerWeek: number;
  fee?: number;
  paymentType?: 'Monthly' | 'One-time';
}

export interface Exam {
  id: string;
  name: string;
  subject: string;
  date: string;
  marks: Record<string, number>; // studentId -> marks
}

export interface Student {
  id: string;
  name: string;
  email: string;
  phone: string; // Acts as primary contact
  password?: string;
  class: 'HSC 1st Year' | 'HSC 2nd Year';
  attendance: number;
  averageScore: number;
  assignments: number; // percentage
  feesPaid: boolean; // Legacy summary field
  subjects: string[];
  isVerified: boolean;
  dailyAttendance?: Record<string, boolean>; // date (YYYY-MM-DD) -> present (true/false)

  // New Admission Fields
  address?: string;
  dob?: string;
  sscRoll?: string;
  sscReg?: string;
  ownPhone?: string;
  guardianPhone?: string;

  // Granular Payment Statuses
  monthlyFeeStatus?: 'Paid' | 'Due';
  courseFeeStatus?: 'Paid' | 'Due';

  // Course-wise Payment Tracking
  subjectPayments?: Record<string, 'Paid' | 'Due'>; // subjectId -> status
}

export interface PerformanceInsight {
  status: 'Critical' | 'Warning' | 'Good' | 'Excellent';
  color: string;
  message: string;
}

export interface AdminUser {
  name: string;
  email: string;
  password?: string; // New field for dynamic admin login
  avatar?: string;
}

export interface FooterData {
  description: string;
  address: string;
  phone: string;
  email: string;
  quickLinks: { name: string; url: string }[];
  supportLinks: { name: string; url: string }[];
}

export interface HomeData {
  heroTitle: string;
  heroEnrollText: string;
  heroExploreText: string;
  statExperience: string;
  statStudents: string;
}

import React, { useState, useEffect } from 'react';
import { UserRole, Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from './types';
import { MOCK_STUDENTS, SUBJECT_INFO, TEACHERS } from './constants';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Courses from './pages/Courses';
import TeachersPage from './pages/Teachers';
import Admission from './pages/Admission';
import Contact from './pages/Contact';
import Login from './pages/Login';
import StudentDashboard from './pages/StudentDashboard';
import AdminDashboard from './pages/AdminDashboard';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('home');
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [user, setUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);

  const [logo, setLogo] = useState<string>('P');
  const [adminProfile, setAdminProfile] = useState<AdminUser>({
    name: 'Headmaster Admin',
    email: 'admin@phoenix.com',
    password: 'admin', 
    avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=admin'
  });

  const [footerData, setFooterData] = useState<FooterData>({
    description: 'Igniting Academic Excellence for HSC Science Students in Kulaura since 2015.',
    address: 'Main Road, Kulaura, Moulvibazar',
    phone: '+880 1700-000000',
    email: 'info@phoenix-edu.com',
    quickLinks: [
      { name: 'About Us', url: '#' },
      { name: 'Admissions', url: '#' },
      { name: 'Success Stories', url: '#' },
      { name: 'Resources', url: '#' }
    ],
    supportLinks: [
      { name: 'Contact Support', url: '#' },
      { name: 'Terms & Conditions', url: '#' },
      { name: 'Privacy Policy', url: '#' }
    ]
  });

  const [homeData, setHomeData] = useState<HomeData>({
    heroTitle: 'Igniting Academic Excellence for HSC Science',
    heroEnrollText: 'Enroll Now',
    heroExploreText: 'Explore Courses',
    statExperience: '10+',
    statStudents: '2500+'
  });

  const [subjects, setSubjects] = useState<Subject[]>(
    Object.entries(SUBJECT_INFO).map(([name, info], idx) => ({
      id: `sub-${idx}`,
      name,
      icon: (info as any).icon,
      classesPerWeek: (info as any).classesPerWeek,
      fee: 2000 + (idx * 500),
      paymentType: idx % 2 === 0 ? 'Monthly' : 'One-time'
    }))
  );

  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS.map(s => ({
    ...s,
    monthlyFeeStatus: s.monthlyFeeStatus || 'Due',
    courseFeeStatus: s.courseFeeStatus || 'Due',
    subjectPayments: s.subjectPayments || {}
  })));
  const [teachers, setTeachers] = useState<Teacher[]>(TEACHERS);
  const [exams, setExams] = useState<Exam[]>([
    {
      id: 'e1',
      name: 'Initial Term Test',
      subject: 'Physics',
      date: '2024-03-10',
      marks: { 's1': 82, 's2': 45 }
    }
  ]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const navigate = (page: string) => {
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogin = (selectedRole: UserRole, identifier: string, password?: string) => {
    if (selectedRole === UserRole.STUDENT) {
      const found = students.find(s => 
        (s.email && s.email.toLowerCase() === identifier.toLowerCase()) || 
        (s.ownPhone && s.ownPhone === identifier) || 
        (s.phone && s.phone === identifier) || 
        (s.guardianPhone && s.guardianPhone === identifier)
      );

      if (found) {
        if (!found.isVerified) {
          alert("Your admission is still pending admin approval. Please wait for verification.");
          return;
        }

        if (password && found.password === password) {
          setRole(selectedRole);
          setUser(found);
          navigate('student-dashboard');
        } else {
          alert("Incorrect password. Please try again.");
        }
      } else {
        alert("No student account found with that email or phone number.");
      }
    } else {
      if (identifier.toLowerCase() === adminProfile.email.toLowerCase() && password === adminProfile.password) {
         setRole(selectedRole);
         setUser(adminProfile);
         navigate('admin-dashboard');
      } else {
        alert("Invalid admin credentials.");
      }
    }
  };

  const handleLogout = () => {
    setRole(UserRole.GUEST);
    setUser(null);
    navigate('home');
  };

  const handleAdmissionSubmit = (newAppData: any) => {
    const newStudent: Student = {
      id: `s-${Date.now()}`,
      name: newAppData.name,
      email: `${newAppData.name.toLowerCase().replace(/\s/g, '')}${Math.floor(Math.random() * 100)}@student.com`,
      phone: newAppData.ownPhone || newAppData.guardianPhone,
      password: newAppData.password,
      class: newAppData.class,
      attendance: 0,
      averageScore: 0,
      assignments: 0,
      feesPaid: false,
      subjects: subjects.slice(0, 3).map(s => s.name),
      isVerified: false,
      address: newAppData.address,
      dob: newAppData.dob,
      sscRoll: newAppData.sscRoll,
      sscReg: newAppData.sscReg,
      ownPhone: newAppData.ownPhone,
      guardianPhone: newAppData.guardianPhone,
      dailyAttendance: {},
      monthlyFeeStatus: 'Due',
      courseFeeStatus: 'Due',
      subjectPayments: {}
    };
    setStudents(prev => [newStudent, ...prev]);
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home': return <Home navigate={navigate} homeData={homeData} role={role} />;
      case 'courses': return <Courses subjects={subjects} />;
      case 'teachers': return <TeachersPage teachers={teachers} />;
      case 'admission': return <Admission onSubmit={handleAdmissionSubmit} />;
      case 'contact': return <Contact />;
      case 'login': return <Login onLogin={handleLogin} />;
      case 'student-dashboard': 
        if (!user || role !== UserRole.STUDENT) {
          navigate('login');
          return null;
        }
        const currentStudent = students.find(s => s.id === user.id) || user;
        return <StudentDashboard student={currentStudent} exams={exams} onLogout={handleLogout} subjects={subjects} />;
      case 'admin-dashboard': 
        if (!user || role !== UserRole.ADMIN) {
          navigate('login');
          return null;
        }
        return (
          <AdminDashboard 
            onLogout={handleLogout} 
            logo={logo} 
            setLogo={setLogo} 
            subjects={subjects} 
            setSubjects={setSubjects}
            students={students}
            setStudents={setStudents}
            teachers={teachers}
            setTeachers={setTeachers}
            exams={exams}
            setExams={setExams}
            adminProfile={adminProfile}
            setAdminProfile={setAdminProfile}
            footerData={footerData}
            setFooterData={setFooterData}
            homeData={homeData}
            setHomeData={setHomeData}
          />
        );
      default: return <Home navigate={navigate} homeData={homeData} role={role} />;
    }
  };

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <Navbar 
        currentPage={currentPage} 
        navigate={navigate} 
        role={role} 
        onLogout={handleLogout}
        darkMode={darkMode}
        toggleDarkMode={() => setDarkMode(!darkMode)}
        logoImage={logo}
      />
      <main className="flex-grow pt-16">
        {renderPage()}
      </main>
      <Footer 
        data={footerData} 
        onAdminClick={() => navigate('login')}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');

  // Modal visibility states
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  // Selection/Editing states
  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);

  // Attendance Management
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
  const [attendanceMap, setAttendanceMap] = useState<Record<string, boolean>>({});

  // Buffered settings for the Settings Tab
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });
  const [tempAdmin, setTempAdmin] = useState<AdminUser>({ ...adminProfile });

  // Form Field logic
  const [courseForm, setCourseForm] = useState<{
    name: string;
    icon: string;
    classesPerWeek: number;
    fee: number;
    paymentType: 'Monthly' | 'One-time';
  }>({ name: '', icon: '📚', classesPerWeek: 3, fee: 0, paymentType: 'Monthly' });

  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ 
    name: '', 
    subject: subjects[0]?.name || 'Physics', 
    date: new Date().toISOString().split('T')[0] 
  });
  const [studentForm, setStudentForm] = useState<Partial<Student>>({});

  // Input Refs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  // Sync Attendance list based on date selection
  useEffect(() => {
    const newMap: Record<string, boolean> = {};
    students.forEach(s => {
      if (s.dailyAttendance && s.dailyAttendance[attendanceDate] !== undefined) {
        newMap[s.id] = s.dailyAttendance[attendanceDate];
      } else {
        newMap[s.id] = false;
      }
    });
    setAttendanceMap(newMap);
  }, [attendanceDate, students]);

  // Modal form population effects
  useEffect(() => {
    if (editingCourse) setCourseForm({ 
      name: editingCourse.name, 
      icon: editingCourse.icon, 
      classesPerWeek: editingCourse.classesPerWeek,
      fee: editingCourse.fee || 0,
      paymentType: editingCourse.paymentType || 'Monthly'
    });
    else setCourseForm({ name: '', icon: '📚', classesPerWeek: 3, fee: 0, paymentType: 'Monthly' });
  }, [editingCourse, isCourseModalOpen]);

  useEffect(() => {
    if (editingTeacher) setTeacherForm({ name: editingTeacher.name, subject: editingTeacher.subject, qualification: editingTeacher.qualification, experience: editingTeacher.experience, image: editingTeacher.image });
    else setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
  }, [editingTeacher, isTeacherModalOpen]);

  useEffect(() => {
    if (editingStudent) setStudentForm(editingStudent);
  }, [editingStudent]);

  // Sync temp settings when entering tab
  useEffect(() => {
    if (activeTab === 'settings') {
      setTempFooter({ ...footerData });
      setTempHome({ ...homeData });
      setTempAdmin({ ...adminProfile });
    }
  }, [activeTab]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  // --- FUNCTIONAL STATE UPDATERS ---

  const handleStudentUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingStudent) return;
    setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...studentForm } as Student : s));
    setEditingStudent(null);
    alert("Student profile updated successfully.");
  };

  const handleVerifyStudent = (studentId: string) => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isVerified: true } : s));
    alert("Student verified. They can now log in to their dashboard.");
  };

  const toggleAttendance = (studentId: string) => {
    setAttendanceMap(prev => ({ ...prev, [studentId]: !prev[studentId] }));
  };

  const submitAttendance = () => {
    setStudents(prev => prev.map(s => {
      const newDailyAttendance = { ...(s.dailyAttendance || {}), [attendanceDate]: attendanceMap[s.id] };
      const totalDays = Object.keys(newDailyAttendance).length;
      const presentDays = Object.values(newDailyAttendance).filter(val => val === true).length;
      const newPercentage = totalDays > 0 ? (presentDays / totalDays) * 100 : 0;
      return { ...s, dailyAttendance: newDailyAttendance, attendance: parseFloat(newPercentage.toFixed(1)) };
    }));
    alert("Attendance records saved for " + attendanceDate);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(prev => prev.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
      alert("Faculty information updated.");
    } else {
      setTeachers(prev => [...prev, { id: `t-${Date.now()}`, ...teacherForm }]);
      alert("New teacher registered successfully.");
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCourse) {
      setSubjects(prev => prev.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
      alert("Course details updated.");
    } else {
      setSubjects(prev => [...prev, { id: `sub-${Date.now()}`, ...courseForm }]);
      alert("New course added to curriculum.");
    }
    setIsCourseModalOpen(false);
    setEditingCourse(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams(prev => [...prev, newExam]);
    alert("Exam scheduled and published.");
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    setAdminProfile(tempAdmin);
    alert("Global site configuration saved and deployed.");
  };

  // Payment Management Handlers
  const toggleFeeStatus = (studentId: string, type: 'monthly' | 'course') => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const field = type === 'monthly' ? 'monthlyFeeStatus' : 'courseFeeStatus';
        const current = s[field] || 'Due';
        const next = current === 'Paid' ? 'Due' : 'Paid';
        return { ...s, [field]: next, feesPaid: next === 'Paid' };
      }
      return s;
    }));
  };

  const toggleSubjectPayment = (studentId: string, subjectId: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const payments = s.subjectPayments || {};
        const current = payments[subjectId] || 'Due';
        const next = current === 'Paid' ? 'Due' : 'Paid';
        return { ...s, subjectPayments: { ...payments, [subjectId]: next } };
      }
      return s;
    }));
  };

  // Link Management
  const handleAddLink = (type: 'quick' | 'support') => {
    const newLink = { name: 'New Link', url: '#' };
    if (type === 'quick') setTempFooter(p => ({ ...p, quickLinks: [...p.quickLinks, newLink] }));
    else setTempFooter(p => ({ ...p, supportLinks: [...p.supportLinks, newLink] }));
  };

  const handleRemoveLink = (type: 'quick' | 'support', index: number) => {
    if (type === 'quick') {
      setTempFooter(p => {
        const newList = [...p.quickLinks];
        newList.splice(index, 1);
        return { ...p, quickLinks: newList };
      });
    } else {
      setTempFooter(p => {
        const newList = [...p.supportLinks];
        newList.splice(index, 1);
        return { ...p, supportLinks: newList };
      });
    }
  };

  const handleUpdateLink = (type: 'quick' | 'support', index: number, field: 'name' | 'url', value: string) => {
    if (type === 'quick') {
      setTempFooter(p => {
        const newList = [...p.quickLinks];
        newList[index] = { ...newList[index], [field]: value };
        return { ...p, quickLinks: newList };
      });
    } else {
      setTempFooter(p => {
        const newList = [...p.supportLinks];
        newList[index] = { ...newList[index], [field]: value };
        return { ...p, supportLinks: newList };
      });
    }
  };

  const pendingStudents = students.filter(s => !s.isVerified);
  const verifiedStudents = students.filter(s => s.isVerified);
  const isLogoBase64 = logo.startsWith('data:image');

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8 relative">
      {/* Admin Branding Header */}
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-center space-x-4">
          <div className="relative group cursor-pointer">
            <img src={adminProfile.avatar} className="w-16 h-16 rounded-full border-2 border-orange-500 shadow-lg object-cover" alt="Admin" />
