        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-4xl rounded-[48px] shadow-2xl p-12 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-10"><h2 className="text-4xl font-black">{viewingStudent.name}</h2><button onClick={() => setViewingStudent(null)} className="p-4 bg-slate-100 dark:bg-slate-700 rounded-full font-black text-xl hover:bg-red-500 hover:text-white transition-all">✕</button></div>
            <div className="grid md:grid-cols-2 gap-10">
               <div className="p-10 bg-slate-50 dark:bg-slate-900/50 rounded-[40px] space-y-5 border border-slate-100 dark:border-slate-700">
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Personal Data</p>
                  <p className="text-lg"><b>Class:</b> {viewingStudent.class}</p>
                  <p className="text-lg"><b>DOB:</b> {viewingStudent.dob}</p>
                  <p className="text-lg"><b>Mobile:</b> {viewingStudent.ownPhone}</p>
                  <p className="text-lg"><b>Guardian:</b> {viewingStudent.guardianPhone}</p>
                  <p className="text-lg pt-4 text-slate-500 italic"><b>Address:</b> {viewingStudent.address}</p>
               </div>
               <div className="p-10 bg-slate-50 dark:bg-slate-900/50 rounded-[40px] space-y-5 border border-slate-100 dark:border-slate-700">
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Academic Credentials</p>
                  <p className="text-lg"><b>SSC Roll:</b> {viewingStudent.sscRoll}</p>
                  <p className="text-lg"><b>SSC Registration:</b> {viewingStudent.sscReg}</p>
                  <p className="pt-6 font-black text-2xl text-blue-600">Portal Email: {viewingStudent.email}</p>
                  <div className={`mt-4 px-6 py-3 rounded-2xl font-black text-center text-xs tracking-widest uppercase ${viewingStudent.isVerified ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                    {viewingStudent.isVerified ? 'System Verified' : 'Approval Required'}
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Edit Admission Modal */}
      {editingStudent && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <form onSubmit={handleStudentUpdate} className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[48px] shadow-2xl p-12 space-y-8 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Edit Admission Record</h2><button type="button" onClick={() => { setEditingStudent(null); setStudentForm({}); }} className="text-slate-400 font-black text-2xl hover:text-red-500">✕</button></div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">Student Name</label><input className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={studentForm.name || ''} onChange={e => setStudentForm({...studentForm, name: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">Class</label><select className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-black" value={studentForm.class || 'HSC 1st Year'} onChange={e => setStudentForm({...studentForm, class: e.target.value as any})}><option value="HSC 1st Year">HSC 1st Year</option><option value="HSC 2nd Year">HSC 2nd Year</option></select></div>
              <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">SSC Roll</label><input className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={studentForm.sscRoll || ''} onChange={e => setStudentForm({...studentForm, sscRoll: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">SSC Reg</label><input className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={studentForm.sscReg || ''} onChange={e => setStudentForm({...studentForm, sscReg: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">Own Mobile</label><input className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={studentForm.ownPhone || ''} onChange={e => setStudentForm({...studentForm, ownPhone: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">Guardian Mobile</label><input className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-bold" value={studentForm.guardianPhone || ''} onChange={e => setStudentForm({...studentForm, guardianPhone: e.target.value})} /></div>
            </div>
            <div className="space-y-2"><label className="text-xs font-black text-slate-400 uppercase ml-2">Dashboard Password</label><input className="w-full p-4 rounded-2xl border dark:bg-slate-900 font-black" value={studentForm.password || ''} onChange={e => setStudentForm({...studentForm, password: e.target.value})} /></div>
            <button type="submit" className="w-full py-5 bg-blue-600 text-white font-black rounded-[24px] shadow-2xl transition-all hover:bg-blue-700 active:scale-95 mt-4">Save Profile Changes</button>
          </form>
        </div>
      )}

      {/* Exam Marks Entry Modal */}
      {enteringMarksFor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-[48px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900/40"><h2 className="text-3xl font-black">Performance Entry</h2><button onClick={() => setEnteringMarksFor(null)} className="p-4 bg-white dark:bg-slate-700 rounded-[20px] font-black text-xl hover:text-red-500 shadow-sm transition-all">✕</button></div>
            <div className="flex-grow overflow-y-auto p-10 space-y-6">
              <div className="p-4 bg-blue-50 dark:bg-blue-900/20 text-blue-800 dark:text-blue-300 rounded-2xl text-xs font-black uppercase tracking-widest text-center">Entering scores for {enteringMarksFor.name}</div>
              {verifiedStudents.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-slate-50 dark:bg-slate-900/50 rounded-[32px] border border-transparent hover:border-slate-200 transition-all shadow-sm">
                  <span className="font-black text-xl">{s.name}</span>
                  <input type="number" className="w-28 p-5 rounded-[24px] border dark:bg-slate-800 text-center font-black text-2xl text-blue-600 focus:ring-4 ring-blue-500/20 shadow-inner" value={enteringMarksFor.marks[s.id] || ''} onChange={(e) => updateStudentMark(enteringMarksFor.id, s.id, Number(e.target.value))} />
                </div>
              ))}
            </div>
            <div className="p-10 border-t dark:border-slate-700"><button onClick={() => { setEnteringMarksFor(null); alert("Exam marks submitted successfully."); }} className="w-full py-6 bg-blue-600 text-white font-black rounded-[28px] shadow-2xl hover:bg-blue-700 transition-all active:scale-95 text-lg">Save Results Batch</button></div>
          </div>
        </div>
      )}

      {/* Teacher Add/Edit Modal */}
      {isTeacherModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[48px] shadow-2xl p-12 space-y-8">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingTeacher ? 'Edit Teacher' : 'Register Faculty'}</h2><button onClick={() => setIsTeacherModalOpen(false)} className="text-slate-400 font-black text-2xl hover:text-red-500">✕</button></div>
            <form onSubmit={handleTeacherSubmit} className="space-y-6">
              <div className="flex flex-col items-center space-y-4">
                 <div className="relative group cursor-pointer" onClick={() => teacherPicRef.current?.click()}>
                   <div className="w-36 h-36 rounded-[40px] overflow-hidden border-8 border-blue-100 dark:border-blue-900/30 bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-slate-300 font-black shadow-2xl">{teacherForm.image ? <img src={teacherForm.image} className="w-full h-full object-cover" /> : <span className="text-4xl">📸</span>}</div>
                   <input type="file" hidden ref={teacherPicRef} accept="image/*" onChange={(e) => handleFileUpload(e, (b) => setTeacherForm({...teacherForm, image: b}))} />
                 </div>
              </div>
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black outline-none focus:ring-4 ring-blue-500/10" placeholder="Teacher Full Name" value={teacherForm.name} onChange={e => setTeacherForm({...teacherForm, name: e.target.value})} />
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black outline-none focus:ring-4 ring-blue-500/10" placeholder="Subject Specialization" value={teacherForm.subject} onChange={e => setTeacherForm({...teacherForm, subject: e.target.value})} />
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black outline-none focus:ring-4 ring-blue-500/10" placeholder="Qualifications" value={teacherForm.qualification} onChange={e => setTeacherForm({...teacherForm, qualification: e.target.value})} />
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black outline-none focus:ring-4 ring-blue-500/10" placeholder="Teaching Experience" value={teacherForm.experience} onChange={e => setTeacherForm({...teacherForm, experience: e.target.value})} />
              <button type="submit" className="w-full py-6 bg-blue-600 text-white font-black rounded-[28px] shadow-2xl hover:bg-blue-700 transition-all active:scale-95">{editingTeacher ? 'Update Instructor' : 'Save Instructor'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Course Add/Edit Modal */}
      {isCourseModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[48px] shadow-2xl p-12 space-y-8">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">{editingCourse ? 'Edit Program' : 'New Program'}</h2><button onClick={() => setIsCourseModalOpen(false)} className="text-slate-400 font-black text-2xl hover:text-red-500">✕</button></div>
            <form onSubmit={handleCourseSubmit} className="space-y-6">
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black" placeholder="Program Title" value={courseForm.name} onChange={e => setCourseForm({...courseForm, name: e.target.value})} />
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black" placeholder="Subject Icon (Emoji)" value={courseForm.icon} onChange={e => setCourseForm({...courseForm, icon: e.target.value})} />

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-3">Classes/Week</label>
                  <input required type="number" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black" value={courseForm.classesPerWeek} onChange={e => setCourseForm({...courseForm, classesPerWeek: parseInt(e.target.value)})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-3">Tuition Fee (BDT)</label>
                  <input required type="number" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black" value={courseForm.fee} onChange={e => setCourseForm({...courseForm, fee: parseInt(e.target.value)})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase ml-3">Billing Cycle</label>
                <select className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black" value={courseForm.paymentType} onChange={e => setCourseForm({...courseForm, paymentType: e.target.value as any})}>
                  <option value="Monthly">Monthly Cycle</option>
                  <option value="One-time">One-time Enrollment</option>
                </select>
              </div>

              <button type="submit" className="w-full py-6 bg-blue-600 text-white font-black rounded-[28px] shadow-2xl hover:bg-blue-700 transition-all active:scale-95">{editingCourse ? 'Save Changes' : 'Initialize Program'}</button>
            </form>
          </div>
        </div>
      )}

      {/* Exam Scheduling Modal */}
      {isExamModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-[48px] shadow-2xl p-12 space-y-8">
            <div className="flex justify-between items-center"><h2 className="text-3xl font-black">Exam Scheduler</h2><button onClick={() => setIsExamModalOpen(false)} className="text-slate-400 font-black text-2xl hover:text-red-500">✕</button></div>
            <form onSubmit={handleExamSubmit} className="space-y-6">
              <input required type="text" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black focus:ring-4 ring-orange-500/20" placeholder="Exam Session Label" value={examForm.name} onChange={e => setExamForm({...examForm, name: e.target.value})} />
              <select className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black focus:ring-4 ring-orange-500/20" value={examForm.subject} onChange={e => setExamForm({...examForm, subject: e.target.value})}>{subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}</select>
              <input required type="date" className="w-full p-5 rounded-3xl border dark:bg-slate-900 font-black focus:ring-4 ring-orange-500/20" value={examForm.date} onChange={e => setExamForm({...examForm, date: e.target.value})} />
              <button type="submit" className="w-full py-6 bg-orange-500 text-white font-black rounded-[28px] shadow-2xl hover:bg-orange-600 transition-all active:scale-95">Publish Board Schedule</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from '../types';

interface AdminDashboardProps {
  onLogout: () => void;
  logo: string;
  setLogo: (val: string) => void;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exams: Exam[];
  setExams: React.Dispatch<React.SetStateAction<Exam[]>>;
  adminProfile: AdminUser;
  setAdminProfile: (profile: AdminUser) => void;
  footerData: FooterData;
  setFooterData: (data: FooterData) => void;
  homeData: HomeData;
  setHomeData: (data: HomeData) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  onLogout, logo, setLogo, subjects, setSubjects, students, setStudents, teachers, setTeachers, exams, setExams, adminProfile, setAdminProfile, footerData, setFooterData, homeData, setHomeData 
}) => {
  const [activeTab, setActiveTab] = useState('overview');

  // Modal visibility states
  const [isCourseModalOpen, setIsCourseModalOpen] = useState(false);
  const [isTeacherModalOpen, setIsTeacherModalOpen] = useState(false);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [enteringMarksFor, setEnteringMarksFor] = useState<Exam | null>(null);

  // Selection/Editing states
  const [editingCourse, setEditingCourse] = useState<Subject | null>(null);
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null);
  const [viewingStudent, setViewingStudent] = useState<Student | null>(null);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);

  // Attendance Management
  const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
  const [attendanceMap, setAttendanceMap] = useState<Record<string, boolean>>({});

  // Buffered settings for the Settings Tab
  const [tempFooter, setTempFooter] = useState<FooterData>({ ...footerData });
  const [tempHome, setTempHome] = useState<HomeData>({ ...homeData });
  const [tempAdmin, setTempAdmin] = useState<AdminUser>({ ...adminProfile });

  // Form Field logic
  const [courseForm, setCourseForm] = useState<{
    name: string;
    icon: string;
    classesPerWeek: number;
    fee: number;
    paymentType: 'Monthly' | 'One-time';
  }>({ name: '', icon: '📚', classesPerWeek: 3, fee: 0, paymentType: 'Monthly' });

  const [teacherForm, setTeacherForm] = useState({ name: '', subject: '', qualification: '', experience: '', image: '' });
  const [examForm, setExamForm] = useState({ 
    name: '', 
    subject: subjects[0]?.name || 'Physics', 
    date: new Date().toISOString().split('T')[0] 
  });
  const [studentForm, setStudentForm] = useState<Partial<Student>>({});

  // Input Refs
  const teacherPicRef = useRef<HTMLInputElement>(null);
  const adminAvatarRef = useRef<HTMLInputElement>(null);
  const logoUploadRef = useRef<HTMLInputElement>(null);

  // Sync Attendance list based on date selection
  useEffect(() => {
    const newMap: Record<string, boolean> = {};
    students.forEach(s => {
      if (s.dailyAttendance && s.dailyAttendance[attendanceDate] !== undefined) {
        newMap[s.id] = s.dailyAttendance[attendanceDate];
      } else {
        newMap[s.id] = false;
      }
    });
    setAttendanceMap(newMap);
  }, [attendanceDate, students]);

  // Modal form population effects
  useEffect(() => {
    if (editingCourse) setCourseForm({ 
      name: editingCourse.name, 
      icon: editingCourse.icon, 
      classesPerWeek: editingCourse.classesPerWeek,
      fee: editingCourse.fee || 0,
      paymentType: editingCourse.paymentType || 'Monthly'
    });
    else setCourseForm({ name: '', icon: '📚', classesPerWeek: 3, fee: 0, paymentType: 'Monthly' });
  }, [editingCourse, isCourseModalOpen]);

  useEffect(() => {
    if (editingTeacher) setTeacherForm({ name: editingTeacher.name, subject: editingTeacher.subject, qualification: editingTeacher.qualification, experience: editingTeacher.experience, image: editingTeacher.image });
    else setTeacherForm({ name: '', subject: '', qualification: '', experience: '', image: '' });
  }, [editingTeacher, isTeacherModalOpen]);

  // Sync temp settings when entering tab
  useEffect(() => {
    if (activeTab === 'settings') {
      setTempFooter({ ...footerData });
      setTempHome({ ...homeData });
      setTempAdmin({ ...adminProfile });
    }
  }, [activeTab, footerData, homeData, adminProfile]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (base64: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  // --- FUNCTIONAL STATE UPDATERS ---

  const handleStudentUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingStudent) return;
    setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...studentForm } as Student : s));
    setEditingStudent(null);
    setStudentForm({});
    alert("Student profile updated successfully.");
  };

  const handleVerifyStudent = (studentId: string) => {
    setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isVerified: true } : s));
    alert("Student verified. They can now log in to their dashboard.");
  };

  const toggleAttendance = (studentId: string) => {
    setAttendanceMap(prev => ({ ...prev, [studentId]: !prev[studentId] }));
  };

  const submitAttendance = () => {
    setStudents(prev => prev.map(s => {
      const newDailyAttendance = { ...(s.dailyAttendance || {}), [attendanceDate]: attendanceMap[s.id] };
      const totalDays = Object.keys(newDailyAttendance).length;
      const presentDays = Object.values(newDailyAttendance).filter(val => val === true).length;
      const newPercentage = totalDays > 0 ? (presentDays / totalDays) * 100 : 0;
      return { ...s, dailyAttendance: newDailyAttendance, attendance: parseFloat(newPercentage.toFixed(1)) };
    }));
    alert("Attendance records saved for " + attendanceDate);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      setTeachers(prev => prev.map(t => t.id === editingTeacher.id ? { ...t, ...teacherForm } : t));
      alert("Faculty information updated.");
    } else {
      setTeachers(prev => [...prev, { id: `t-${Date.now()}`, ...teacherForm }]);
      alert("New teacher registered successfully.");
    }
    setIsTeacherModalOpen(false);
    setEditingTeacher(null);
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCourse) {
      setSubjects(prev => prev.map(s => s.id === editingCourse.id ? { ...s, ...courseForm } : s));
      alert("Course details updated.");
    } else {
      setSubjects(prev => [...prev, { id: `sub-${Date.now()}`, ...courseForm }]);
      alert("New course added to curriculum.");
    }
    setIsCourseModalOpen(false);
    setEditingCourse(null);
  };

  const handleExamSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newExam: Exam = { id: `e${Date.now()}`, ...examForm, marks: {} };
    setExams(prev => [...prev, newExam]);
    alert("Exam scheduled and published.");
    setIsExamModalOpen(false);
  };

  const updateStudentMark = (examId: string, studentId: string, mark: number) => {
    setExams(prev => prev.map(exam => exam.id === examId ? { ...exam, marks: { ...exam.marks, [studentId]: mark } } : exam));
  };

  const handleSaveSiteConfig = () => {
    setFooterData(tempFooter);
    setHomeData(tempHome);
    setAdminProfile(tempAdmin);
    alert("Global site configuration saved and deployed.");
  };

  // Payment Management Handlers
  const toggleFeeStatus = (studentId: string, type: 'monthly' | 'course') => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const field = type === 'monthly' ? 'monthlyFeeStatus' : 'courseFeeStatus';
        const current = s[field] || 'Due';
        const next = current === 'Paid' ? 'Due' : 'Paid';
        return { ...s, [field]: next, feesPaid: next === 'Paid' };
      }
      return s;
    }));
  };

  const toggleSubjectPayment = (studentId: string, subjectId: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === studentId) {
        const payments = s.subjectPayments || {};
        const current = payments[subjectId] || 'Due';
        const next = current === 'Paid' ? 'Due' : 'Paid';
        return { ...s, subjectPayments: { ...payments, [subjectId]: next } };
      }
      return s;
    }));
  };

  // Link Management
  const handleAddLink = (type: 'quick' | 'support') => {
    const newLink = { name: 'New Link', url: '#' };
    if (type === 'quick') setTempFooter(p => ({ ...p, quickLinks: [...p.quickLinks, newLink] }));
    else setTempFooter(p => ({ ...p, supportLinks: [...p.supportLinks, newLink] }));
  };

  const handleRemoveLink = (type: 'quick' | 'support', index: number) => {
    if (type === 'quick') {
      setTempFooter(p => {
        const newList = [...p.quickLinks];
        newList.splice(index, 1);
        return { ...p, quickLinks: newList };
      });
    } else {
      setTempFooter(p => {
        const newList = [...p.supportLinks];
        newList.splice(index, 1);
        return { ...p, supportLinks: newList };
      });
    }
  };

  const handleUpdateLink = (type: 'quick' | 'support', index: number, field: 'name' | 'url', value: string) => {
    if (type === 'quick') {
      setTempFooter(p => {
        const newList = [...p.quickLinks];
