```typescript
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = 'YOUR_SUPABASE_URL'; // Replace with your Supabase URL
const supabaseKey = 'YOUR_SUPABASE_ANON_KEY'; // Replace with your Supabase anonymous key
const supabase = createClient(supabaseUrl, supabaseKey);

// Define your Supabase table names
const STUDENTS_TABLE = 'students';
const SITE_CONFIG_TABLE = 'site_config';

// Function to fetch all students
async function getStudents() {
  try {
    const { data, error } = await supabase
      .from(STUDENTS_TABLE)
      .select('*');

    if (error) {
      console.error('Error fetching students:', error);
      return [];
    }

    return data || [];
  } catch (error) {
    console.error('Unexpected error fetching students:', error);
    return [];
  }
}

// Function to add or update a student
async function upsertStudent(studentData) {
  try {
    const { data, error } = await supabase
      .from(STUDENTS_TABLE)
      .upsert([studentData])
      .select();

    if (error) {
      console.error('Error upserting student:', error);
      return null;
    }

    return data && data.length > 0 ? data[0] : null;
  } catch (error) {
    console.error('Unexpected error upserting student:', error);
    return null;
  }
}

// Function to fetch the site configuration
async function getSiteConfig() {
    try {
        const { data, error } = await supabase
            .from(SITE_CONFIG_TABLE)
            .select('*')
            .limit(1);

        if (error) {
            console.error('Error fetching site config:', error);
            return {};
        }

        return data && data.length > 0 ? data[0] : {};
    } catch (error) {
        console.error('Unexpected error fetching site config:', error);
        return {};
    }
}

// Function to update the site configuration
async function updateSiteConfig(configData) {
    try {
        const { data, error } = await supabase
            .from(SITE_CONFIG_TABLE)
            .upsert([configData])
            .select();

        if (error) {
            console.error('Error updating site config:', error);
            return null;
        }

        return data && data.length > 0 ? data[0] : null;
    } catch (error) {
        console.error('Unexpected error updating site config:', error);
        return null;
    }
}

export { getStudents, upsertStudent, getSiteConfig, updateSiteConfig };
```

