/**
 * Signs up a new user in Supabase Auth and returns the user data.
 */
export const signUpUser = async (email: string, password: string, metadata: any) => {
  const { data, error } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: metadata
    }
  });
  if (error) throw error;
  return data;
};

/**
 * Signs in a user using Supabase Auth.
 */
export const signInUser = async (email: string, password: string) => {
  const { data, error } = await supabase.auth.signInWithPassword({
    email,
    password,
  });
  if (error) throw error;
  return data;
};

/**
 * Persists data to Supabase using upsert.
 */
export const syncData = async (table: string, data: any | any[]) => {
  try {
    const { error } = await supabase.from(table).upsert(data);
    if (error) console.error(`Error syncing ${table}:`, error);
  } catch (err) {
    console.error(`Supabase connection failed for ${table}:`, err);
  }
};

/**
 * Deletes data from Supabase.
 */
export const deleteData = async (table: string, id: string) => {
  try {
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) console.error(`Error deleting from ${table}:`, error);
  } catch (err) {
    console.error(`Supabase deletion failed for ${table}:`, err);
  }
};

/**
 * Fetches initial application state.
 */
export const fetchAllData = async () => {
  try {
    const [students, subjects, teachers, exams, config] = await Promise.all([
      supabase.from('students').select('*'),
      supabase.from('subjects').select('*'),
      supabase.from('teachers').select('*'),
      supabase.from('exams').select('*'),
      supabase.from('site_config').select('*').single()
    ]);

    return {
      students: students.data || [],
      subjects: subjects.data || [],
      teachers: teachers.data || [],
      exams: exams.data || [],
      config: config.data || null
    };
  } catch (err) {
    console.error('Initial fetch failed:', err);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { UserRole, Student, Subject, AdminUser, Teacher, Exam, FooterData, HomeData } from './types';
import { MOCK_STUDENTS, SUBJECT_INFO, TEACHERS } from './constants';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Courses from './pages/Courses';
import TeachersPage from './pages/Teachers';
import Admission from './pages/Admission';
import Contact from './pages/Contact';
import Login from './pages/Login';
import StudentDashboard from './pages/StudentDashboard';
import AdminDashboard from './pages/AdminDashboard';
import { fetchAllData, syncData, signUpUser, signInUser, supabase } from './services/supabaseService';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<string>('home');
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [user, setUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  const [logo, setLogo] = useState<string>('P');
  const [adminProfile, setAdminProfile] = useState<AdminUser>({
    name: 'Headmaster Admin',
    email: 'admin@phoenix.com',
    password: 'admin', 
    avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=admin'
  });

  const [footerData, setFooterData] = useState<FooterData>({
    description: 'Igniting Academic Excellence for HSC Science Students in Kulaura since 2015.',
    address: 'Main Road, Kulaura, Moulvibazar',
    phone: '+880 1700-000000',
    email: 'info@phoenix-edu.com',
    quickLinks: [
      { name: 'About Us', url: '#' },
      { name: 'Admissions', url: '#' },
      { name: 'Success Stories', url: '#' },
      { name: 'Resources', url: '#' }
    ],
    supportLinks: [
      { name: 'Contact Support', url: '#' },
      { name: 'Terms & Conditions', url: '#' },
      { name: 'Privacy Policy', url: '#' }
    ]
  });

  const [homeData, setHomeData] = useState<HomeData>({
    heroTitle: 'Igniting Academic Excellence for HSC Science',
    heroEnrollText: 'Enroll Now',
    heroExploreText: 'Explore Courses',
    statExperience: '10+',
    statStudents: '2500+'
  });

  const [subjects, setSubjects] = useState<Subject[]>(
    Object.entries(SUBJECT_INFO).map(([name, info], idx) => ({
      id: `sub-${idx}`,
      name,
      icon: (info as any).icon,
      classesPerWeek: (info as any).classesPerWeek,
      fee: 2000 + (idx * 500),
      paymentType: idx % 2 === 0 ? 'Monthly' : 'One-time'
    }))
  );

  const [students, setStudents] = useState<Student[]>([]);
  const [teachers, setTeachers] = useState<Teacher[]>(TEACHERS);
  const [exams, setExams] = useState<Exam[]>([]);

  // --- SUPABASE HYDRATION ---
  useEffect(() => {
    const init = async () => {
      const data = await fetchAllData();
      if (data) {
        if (data.students.length > 0) setStudents(data.students);
        if (data.teachers.length > 0) setTeachers(data.teachers);
        if (data.subjects.length > 0) setSubjects(data.subjects);
        if (data.exams.length > 0) setExams(data.exams);
        if (data.config) {
          const cfg = data.config;
          if (cfg.logo) setLogo(cfg.logo);
          if (cfg.adminProfile) setAdminProfile(cfg.adminProfile);
          if (cfg.footerData) setFooterData(cfg.footerData);
          if (cfg.homeData) setHomeData(cfg.homeData);
        }
      } else {
        setStudents(MOCK_STUDENTS);
      }
      setIsLoading(false);
    };
    init();
  }, []);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const navigate = (page: string) => {
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogin = async (selectedRole: UserRole, identifier: string, password?: string) => {
    if (selectedRole === UserRole.STUDENT) {
      try {
        // Step 1: Find student in DB by phone or email to get their actual Supabase Auth email
        const { data: studentRecords, error: fetchError } = await supabase
          .from('students')
          .select('*')
          .or(`email.eq."${identifier}",ownPhone.eq."${identifier}",phone.eq."${identifier}",guardianPhone.eq."${identifier}"`);

        if (fetchError || !studentRecords || studentRecords.length === 0) {
          alert("No student account found with those credentials.");
          return;
        }

        const student = studentRecords[0];

        if (!student.isVerified) {
          alert("Your admission is still pending admin approval. Please wait for verification.");
          return;
        }

        // Step 2: Attempt Supabase Authentication using the found student's email
        const loginData = await signInUser(student.email, password || '');

        if (loginData.user) {
          setRole(selectedRole);
          setUser(student);
          navigate('student-dashboard');
        }
      } catch (err: any) {
        console.error("Login error:", err);
        alert(err.message || "Incorrect credentials or account not found.");
      }
    } else {
      if (identifier.toLowerCase() === adminProfile.email.toLowerCase() && password === adminProfile.password) {
         setRole(selectedRole);
         setUser(adminProfile);
         navigate('admin-dashboard');
      } else {
        alert("Invalid admin credentials.");
      }
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setRole(UserRole.GUEST);
    setUser(null);
    navigate('home');
  };

  const updateStudentsWithSync = (action: React.SetStateAction<Student[]>) => {
    setStudents(prev => {
      const next = typeof action === 'function' ? (action as (p: Student[]) => Student[])(prev) : action;
      syncData('students', next);
      return next;
    });
  };

  const updateSubjectsWithSync = (action: React.SetStateAction<Subject[]>) => {
    setSubjects(prev => {
      const next = typeof action === 'function' ? (action as (p: Subject[]) => Subject[])(prev) : action;
      syncData('subjects', next);
      return next;
    });
  };

  const updateTeachersWithSync = (action: React.SetStateAction<Teacher[]>) => {
    setTeachers(prev => {
      const next = typeof action === 'function' ? (action as (p: Teacher[]) => Teacher[])(prev) : action;
      syncData('teachers', next);
      return next;
    });
  };

  const updateExamsWithSync = (action: React.SetStateAction<Exam[]>) => {
    setExams(prev => {
      const next = typeof action === 'function' ? (action as (p: Exam[]) => Exam[])(prev) : action;
      syncData('exams', next);
      return next;
    });
  };

  const syncSiteConfig = (updatedLogo: string, updatedAdmin: AdminUser, updatedFooter: FooterData, updatedHome: HomeData) => {
    syncData('site_config', {
      id: 1, 
      logo: updatedLogo,
      adminProfile: updatedAdmin,
      footerData: updatedFooter,
      homeData: updatedHome
    });
  };

  const handleAdmissionSubmit = async (newAppData: any) => {
    try {
      // Step 1: Sign up in Supabase Auth to add to Users dashboard
      const authData = await signUpUser(newAppData.email, newAppData.password, { name: newAppData.name });

      if (!authData.user) throw new Error("Auth registration failed.");

      // Step 2: Create student record in Database
      const newStudent: Student = {
        id: authData.user.id, // Use Supabase Auth UID as primary key
        name: newAppData.name,
        email: newAppData.email,
        phone: newAppData.ownPhone || newAppData.guardianPhone,
        password: newAppData.password,
        class: newAppData.class,
        attendance: 0,
        averageScore: 0,
        assignments: 0,
        feesPaid: false,
        subjects: subjects.slice(0, 3).map(s => s.name),
        isVerified: false,
        address: newAppData.address,
        dob: newAppData.dob,
        sscRoll: newAppData.sscRoll,
        sscReg: newAppData.sscReg,
        ownPhone: newAppData.ownPhone,
        guardianPhone: newAppData.guardianPhone,
        dailyAttendance: {},
        monthlyFeeStatus: 'Due',
        courseFeeStatus: 'Due',
        subjectPayments: {}
      };

      updateStudentsWithSync(prev => [newStudent, ...prev]);
    } catch (err: any) {
      console.error("Admission Error:", err);
      alert(err.message || "Failed to submit admission. Please try a different email.");
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900">
        <div className="flex flex-col items-center space-y-4">
          <div className="w-12 h-12 border-4 border-orange-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="font-black text-slate-400 uppercase tracking-widest text-xs">Initializing Secure Backend...</p>
        </div>
      </div>
    );
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'home': return <Home navigate={navigate} homeData={homeData} role={role} />;
      case 'courses': return <Courses subjects={subjects} />;
      case 'teachers': return <TeachersPage teachers={teachers} />;
      case 'admission': return <Admission onSubmit={handleAdmissionSubmit} />;
      case 'contact': return <Contact />;
      case 'login': return <Login onLogin={handleLogin} />;
      case 'student-dashboard': 
        if (!user || role !== UserRole.STUDENT) {
          navigate('login');
          return null;
        }
        const currentStudent = students.find(s => s.id === user.id) || user;
        return <StudentDashboard student={currentStudent} exams={exams} onLogout={handleLogout} subjects={subjects} />;
      case 'admin-dashboard': 
        if (!user || role !== UserRole.ADMIN) {
          navigate('login');
          return null;
        }
        return (
          <AdminDashboard 
            onLogout={handleLogout} 
            logo={logo} 
            setLogo={(v) => { setLogo(v); syncSiteConfig(v, adminProfile, footerData, homeData); }} 
            subjects={subjects} 
            setSubjects={updateSubjectsWithSync}
            students={students}
            setStudents={updateStudentsWithSync}
            teachers={teachers}
            setTeachers={updateTeachersWithSync}
            exams={exams}
            setExams={updateExamsWithSync}
            adminProfile={adminProfile}
            setAdminProfile={(p) => { setAdminProfile(p); syncSiteConfig(logo, p, footerData, homeData); }}
            footerData={footerData}
            setFooterData={(f) => { setFooterData(f); syncSiteConfig(logo, adminProfile, f, homeData); }}
            homeData={homeData}
            setHomeData={(h) => { setHomeData(h); syncSiteConfig(logo, adminProfile, footerData, h); }}
          />
        );
      default: return <Home navigate={navigate} homeData={homeData} role={role} />;
    }
  };

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-200 ${darkMode ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <Navbar 
        currentPage={currentPage} 
        navigate={navigate} 
        role={role} 
        onLogout={handleLogout}
        darkMode={darkMode}
        toggleDarkMode={() => setDarkMode(!darkMode)}
        logoImage={logo}
      />
      <main className="flex-grow pt-16">
        {renderPage()}
      </main>
      <Footer 
        data={footerData} 
        onAdminClick={() => navigate('login')}
      />
    </div>
  );
};

export default App;
